function analyzeSpearmanCorrelation(statement) {
  const request = parseSpearmanInput(statement);
  const xRanks = rankValues(request.x).ranks;
  const yRanks = rankValues(request.y).ranks;
  const rho = pearsonCorrelation(xRanks, yRanks);
  const tStatistic = spearmanTStatistic(rho, request.x.length);
  const pValue = pValueForSpearman(rho, request.x.length, request.alternative);
  const decision = pValue < request.alpha
    ? `reject H0 at alpha=${formatNumber(request.alpha)}`
    : `fail to reject H0 at alpha=${formatNumber(request.alpha)}`;
  const differences = xRanks.map((rank, index) => rank - yRanks[index]);
  const squaredDifferences = differences.map((value) => value ** 2);
  const sumSquaredDifferences = squaredDifferences.reduce((sum, value) => sum + value, 0);
  const xTieCorrection = rankValues(request.x).tieCorrection;
  const yTieCorrection = rankValues(request.y).tieCorrection;

  return {
    mode: "statistics",
    tree: {
      kind: "statsRegression",
      label: "SPEARMAN",
      children: [
        statsDatasetNode(request.x, [], "X"),
        statsDatasetNode(request.y, [], "Y"),
        statsMetricNode("rho", rho),
        statsMetricNode("P", pValue),
      ],
    },
    answer: `rho = ${formatNumber(rho)}, p = ${formatNumber(pValue)}`,
    summary: "Spearman rank correlation",
    details: `${request.x.length} paired observations`,
    variables: [],
    metrics: treeMetrics(statsDatasetNode([...request.x, ...request.y])),
    steps: [
      {
        title: "Read paired data",
        expression: `${request.x.length} pairs`,
        detail: "Spearman correlation measures monotonic association by comparing ranks instead of raw values.",
      },
      {
        title: "Rank both variables",
        expression: `x ranks = ${formatVector(xRanks)}, y ranks = ${formatVector(yRanks)}`,
        detail: "Tied values receive average ranks.",
      },
      {
        title: "Correlate ranks",
        expression: `rho = ${formatNumber(rho)}`,
        detail: "Pearson correlation is computed on the two rank lists.",
      },
      {
        title: "Approximate p-value",
        expression: `t = ${formatStatisticValue(tStatistic)}, df = ${request.x.length - 2}, p = ${formatNumber(pValue)}`,
        detail: "For moderate samples, Spearman rho is commonly tested with a t approximation.",
      },
      {
        title: "Make decision",
        expression: decision,
        detail: "The null hypothesis is no monotonic association between the paired variables.",
      },
    ],
    table: {
      headers: ["Obs", "x", "y", "rank x", "rank y", "d", "d^2"],
      rows: request.x.map((value, index) => [
        String(index + 1),
        formatNumber(value),
        formatNumber(request.y[index]),
        formatNumber(xRanks[index]),
        formatNumber(yRanks[index]),
        formatNumber(differences[index]),
        formatNumber(squaredDifferences[index]),
      ]),
    },
    artifacts: [
      ["Spearman rho", formatNumber(rho)],
      ["t approximation", formatStatisticValue(tStatistic)],
      ["Degrees of freedom", formatNumber(request.x.length - 2)],
      ["p-value", formatNumber(pValue)],
      ["Alternative", request.alternative],
      ["Sum d^2", formatNumber(sumSquaredDifferences)],
      ["X tie correction", formatNumber(xTieCorrection)],
      ["Y tie correction", formatNumber(yTieCorrection)],
      ["Decision", decision],
    ],
  };
}

function analyzePearsonCorrelation(statement) {
  const request = parsePearsonInput(statement);
  const xSummary = descriptiveSummary(request.x);
  const ySummary = descriptiveSummary(request.y);
  const covarianceNumerator = request.x.reduce((sum, value, index) =>
    sum + (value - xSummary.mean) * (request.y[index] - ySummary.mean),
  0);
  const sampleCovariance = covarianceNumerator / (request.x.length - 1);
  const r = pearsonCorrelation(request.x, request.y);
  const rSquared = r ** 2;
  const xVariation = request.x.reduce((sum, value) => sum + (value - xSummary.mean) ** 2, 0);
  const trendSlope = covarianceNumerator / xVariation;
  const trendIntercept = ySummary.mean - trendSlope * xSummary.mean;
  const tStatistic = pearsonTStatistic(r, request.x.length);
  const pValue = pValueForPearson(r, request.x.length, request.alternative);
  const interval = fisherCorrelationInterval(r, request.x.length, request.level);
  const decision = pValue < request.alpha
    ? `reject H0 at alpha=${formatNumber(request.alpha)}`
    : `fail to reject H0 at alpha=${formatNumber(request.alpha)}`;
  const percent = formatNumber(request.level * 100);

  return {
    mode: "statistics",
    tree: {
      kind: "statsRegression",
      label: "PEARSON",
      children: [
        statsDatasetNode(request.x, [], "X"),
        statsDatasetNode(request.y, [], "Y"),
        statsMetricNode("r", r),
        statsMetricNode("P", pValue),
        statsMetricNode("R2", rSquared),
      ],
    },
    answer: `r = ${formatNumber(r)}, p = ${formatNumber(pValue)}`,
    summary: "Pearson correlation test",
    details: `${request.x.length} paired observations`,
    variables: [],
    metrics: treeMetrics(statsDatasetNode([...request.x, ...request.y])),
    steps: [
      {
        title: "Read paired data",
        expression: `${request.x.length} pairs`,
        detail: "Pearson correlation measures linear association between two quantitative variables.",
      },
      {
        title: "Compute covariance and standard deviations",
        expression: `cov = ${formatNumber(sampleCovariance)}, sx = ${formatNumber(xSummary.sampleStdDev)}, sy = ${formatNumber(ySummary.sampleStdDev)}`,
        detail: "Correlation standardizes covariance by the two sample standard deviations.",
      },
      {
        title: "Compute Pearson r",
        expression: `r = ${formatNumber(r)}, R^2 = ${formatNumber(rSquared)}`,
        detail: "R squared is the fraction of one variable's variation explained by the linear association with the other.",
      },
      {
        title: "Test zero correlation",
        expression: `t = ${formatStatisticValue(tStatistic)}, df = ${request.x.length - 2}, p = ${formatNumber(pValue)}`,
        detail: "The t test checks the null hypothesis that the population correlation is zero.",
      },
      {
        title: "Build Fisher-z interval",
        expression: `${percent}% CI = [${formatNumber(interval.lower)}, ${formatNumber(interval.upper)}]`,
        detail: "Fisher's z transform gives an approximate confidence interval for the population correlation.",
      },
      {
        title: "Make decision",
        expression: decision,
        detail: "Small p-values suggest a nonzero linear association.",
      },
    ],
    table: {
      headers: ["Obs", "x", "y", "x - xbar", "y - ybar", "Product"],
      rows: request.x.map((value, index) => {
        const xDeviation = value - xSummary.mean;
        const yDeviation = request.y[index] - ySummary.mean;
        return [
          String(index + 1),
          formatNumber(value),
          formatNumber(request.y[index]),
          formatNumber(xDeviation),
          formatNumber(yDeviation),
          formatNumber(xDeviation * yDeviation),
        ];
      }),
    },
    artifacts: [
      ["Pearson r", formatNumber(r)],
      ["R squared", formatNumber(rSquared)],
      ["Sample covariance", formatNumber(sampleCovariance)],
      ["Mean x", formatNumber(xSummary.mean)],
      ["Mean y", formatNumber(ySummary.mean)],
      ["Sample SD x", formatNumber(xSummary.sampleStdDev)],
      ["Sample SD y", formatNumber(ySummary.sampleStdDev)],
      ["t statistic", formatStatisticValue(tStatistic)],
      ["Degrees of freedom", formatNumber(request.x.length - 2)],
      ["p-value", formatNumber(pValue)],
      ["Alternative", request.alternative],
      ["Fisher z", formatNumber(interval.fisherZ)],
      ["Fisher SE", formatNumber(interval.standardError)],
      ["Trend line", `y = ${formatNumber(trendSlope)}x ${formatSigned(trendIntercept)}`],
      [`${percent}% Fisher z CI`, `[${formatNumber(interval.lower)}, ${formatNumber(interval.upper)}]`],
      ["Decision", decision],
    ],
    graph: buildScatterFitGraph(request.x, request.y, trendSlope, trendIntercept, "Pearson trend"),
  };
}

function analyzeKendallCorrelation(statement) {
  const request = parseKendallInput(statement);
  const result = kendallTauB(request.x, request.y);
  const zStatistic = kendallZStatistic(result.score, request.x.length);
  const pValue = pValueForNormal(zStatistic, request.alternative);
  const decision = pValue < request.alpha
    ? `reject H0 at alpha=${formatNumber(request.alpha)}`
    : `fail to reject H0 at alpha=${formatNumber(request.alpha)}`;

  return {
    mode: "statistics",
    tree: {
      kind: "statsRegression",
      label: "KENDALL",
      children: [
        statsDatasetNode(request.x, [], "X"),
        statsDatasetNode(request.y, [], "Y"),
        statsMetricNode("tau", result.tau),
        statsMetricNode("S", result.score),
        statsMetricNode("P", pValue),
      ],
    },
    answer: `tau-b = ${formatNumber(result.tau)}, p = ${formatNumber(pValue)}`,
    summary: "Kendall tau-b correlation",
    details: `${request.x.length} paired observations`,
    variables: [],
    metrics: treeMetrics(statsDatasetNode([...request.x, ...request.y])),
    steps: [
      {
        title: "Read paired data",
        expression: `${request.x.length} pairs`,
        detail: "Kendall tau-b measures ordinal association by comparing all pairs of observations.",
      },
      {
        title: "Classify observation pairs",
        expression: `concordant=${result.concordant}, discordant=${result.discordant}, ties=${result.tiedBoth + result.tiedX + result.tiedY}`,
        detail: "A pair is concordant when both variables move in the same direction and discordant when they move in opposite directions.",
      },
      {
        title: "Compute tau-b",
        expression: `tau-b = ${formatNumber(result.tau)}`,
        detail: "Tau-b adjusts the denominator for ties in x or y, so tied ordinal data are handled more fairly.",
      },
      {
        title: "Approximate p-value",
        expression: `z = ${formatNumber(zStatistic)}, p = ${formatNumber(pValue)}`,
        detail: "The p-value uses a large-sample normal approximation for the Kendall score.",
      },
      {
        title: "Make decision",
        expression: decision,
        detail: "The null hypothesis is no ordinal association between the paired variables.",
      },
    ],
    table: {
      headers: ["Pair", "x relation", "y relation", "Class"],
      rows: result.pairRows,
    },
    artifacts: [
      ["Kendall tau-b", formatNumber(result.tau)],
      ["Kendall S", formatNumber(result.score)],
      ["Concordant pairs", formatNumber(result.concordant)],
      ["Discordant pairs", formatNumber(result.discordant)],
      ["Ties only in x", formatNumber(result.tiedX)],
      ["Ties only in y", formatNumber(result.tiedY)],
      ["Ties in both", formatNumber(result.tiedBoth)],
      ["Total pairs", formatNumber(result.totalPairs)],
      ["z approximation", formatNumber(zStatistic)],
      ["p-value", formatNumber(pValue)],
      ["Alternative", request.alternative],
      ["Decision", decision],
      ["Approximation note", "Large-sample normal approximation; exact small-sample p-values are not used."],
    ],
  };
}

function kendallTauB(xValues, yValues) {
  let concordant = 0;
  let discordant = 0;
  let tiedX = 0;
  let tiedY = 0;
  let tiedBoth = 0;
  const pairRows = [];

  for (let left = 0; left < xValues.length - 1; left += 1) {
    for (let right = left + 1; right < xValues.length; right += 1) {
      const xComparison = compareNumbers(xValues[right], xValues[left]);
      const yComparison = compareNumbers(yValues[right], yValues[left]);
      let pairClass;

      if (xComparison === 0 && yComparison === 0) {
        tiedBoth += 1;
        pairClass = "tied both";
      } else if (xComparison === 0) {
        tiedX += 1;
        pairClass = "tied x";
      } else if (yComparison === 0) {
        tiedY += 1;
        pairClass = "tied y";
      } else if (xComparison === yComparison) {
        concordant += 1;
        pairClass = "concordant";
      } else {
        discordant += 1;
        pairClass = "discordant";
      }

      if (pairRows.length < 80) {
        pairRows.push([
          `${left + 1}-${right + 1}`,
          relationText(xComparison),
          relationText(yComparison),
          pairClass,
        ]);
      }
    }
  }

  const comparableX = concordant + discordant + tiedY;
  const comparableY = concordant + discordant + tiedX;
  const denominator = Math.sqrt(comparableX * comparableY);
  if (!(denominator > EPSILON)) {
    throw new Error("Kendall tau-b needs at least one pair with variation in both variables.");
  }
  const score = concordant - discordant;
  return {
    concordant,
    discordant,
    tiedX,
    tiedY,
    tiedBoth,
    totalPairs: xValues.length * (xValues.length - 1) / 2,
    score,
    tau: normalizeNumber(score / denominator),
    pairRows,
  };
}

function analyzeRegression(statement) {
  const parsedLists = parseXYLists(statement);
  const pairs = parsedLists ? zipPairs(parsedLists.x, parsedLists.y) : parsePairs(statement);
  const predictionRequest = parseSimpleRegressionPrediction(statement);

  if (pairs.length < 2) {
    throw new Error("Regression needs at least two coordinate pairs, such as (1,2), (2,3), (3,5).");
  }

  const xValues = pairs.map((pair) => pair.x);
  const yValues = pairs.map((pair) => pair.y);
  const meanX = mean(xValues);
  const meanY = mean(yValues);
  const sxx = xValues.reduce((sum, value) => sum + (value - meanX) ** 2, 0);
  const syy = yValues.reduce((sum, value) => sum + (value - meanY) ** 2, 0);
  const sxy = pairs.reduce((sum, pair) => sum + (pair.x - meanX) * (pair.y - meanY), 0);
  const slope = sxy / sxx;
  const intercept = meanY - slope * meanX;
  const r = sxy / Math.sqrt(sxx * syy);
  const rSquared = r ** 2;
  const fitted = xValues.map((value) => intercept + slope * value);
  const residuals = yValues.map((value, index) => yValues[index] - fitted[index]);
  const sse = residuals.reduce((sum, value) => sum + value ** 2, 0);
  const degreesFreedom = yValues.length - 2;
  const mse = degreesFreedom > 0 ? sse / degreesFreedom : Number.NaN;
  const normalMatrixInverse = invertMatrix([
    [yValues.length, xValues.reduce((sum, value) => sum + value, 0)],
    [xValues.reduce((sum, value) => sum + value, 0), xValues.reduce((sum, value) => sum + value ** 2, 0)],
  ]);
  const inference = Number.isFinite(mse)
    ? regressionCoefficientInference([intercept, slope], normalMatrixInverse, mse, degreesFreedom, ["Intercept", "Slope"])
    : [];
  const prediction = predictionRequest && Number.isFinite(mse)
    ? simpleRegressionPredictionInterval({
        xValue: predictionRequest.x,
        meanX,
        sxx,
        intercept,
        slope,
        mse,
        degreesFreedom,
        count: xValues.length,
        level: predictionRequest.level,
      })
    : null;
  const wantsCorrelation = statement.toLowerCase().includes("correlation") && !statement.toLowerCase().includes("regression");

  const steps = [
    {
      title: "Parse coordinate pairs",
      expression: pairs.map((pair) => `(${formatNumber(pair.x)}, ${formatNumber(pair.y)})`).join(", "),
      detail: "Each point contributes an x-value and a y-value.",
    },
    {
      title: "Compute means",
      expression: `xbar = ${formatNumber(meanX)}, ybar = ${formatNumber(meanY)}`,
      detail: "Regression compares each point to the center of the data.",
    },
    {
      title: "Compute slope and intercept",
      expression: `slope = ${formatNumber(slope)}, intercept = ${formatNumber(intercept)}`,
      detail: "The least-squares line minimizes squared vertical error.",
    },
    {
      title: "Compute correlation",
      expression: `r = ${formatNumber(r)}, r^2 = ${formatNumber(rSquared)}`,
      detail: "Correlation measures linear association from -1 to 1.",
    },
    ...(inference.length
      ? [{
          title: "Infer coefficient uncertainty",
          expression: `df = ${degreesFreedom}, slope p = ${formatNumber(inference[1].pValue)}`,
          detail: "The residual variance and inverse normal-equation matrix give standard errors, t statistics, p-values, and confidence intervals.",
        }]
      : []),
    ...(prediction
      ? [{
          title: "Predict at requested x",
          expression: `x=${formatNumber(prediction.x)}, yhat=${formatNumber(prediction.yHat)}`,
          detail: "The mean-response interval estimates the average response; the prediction interval is wider for a new observation.",
        }]
      : []),
  ];
  const percent = prediction ? formatNumber(prediction.level * 100) : "";

  return {
    mode: "statistics",
    tree: {
      kind: "statsRegression",
      children: [
        statsDatasetNode(xValues, [], "X"),
        statsDatasetNode(yValues, [], "Y"),
        statsMetricNode("r", r),
      ],
    },
    answer: wantsCorrelation
      ? `r = ${formatNumber(r)}`
      : prediction
        ? `y = ${formatNumber(slope)}x ${formatSigned(intercept)}; prediction = ${formatNumber(prediction.yHat)}`
        : `y = ${formatNumber(slope)}x ${formatSigned(intercept)}`,
    summary: wantsCorrelation ? "correlation" : "linear regression",
    details: `${pairs.length} paired observations`,
    variables: [],
    metrics: treeMetrics({
      kind: "statsRegression",
      children: [statsDatasetNode(xValues), statsDatasetNode(yValues)],
    }),
    steps,
    table: {
      headers: ["Obs", "Actual", "Fitted", "Residual"],
      rows: yValues.map((value, index) => [
        String(index + 1),
        formatNumber(value),
        formatNumber(fitted[index]),
        formatNumber(residuals[index]),
      ]),
    },
    artifacts: [
      ["Mean x", formatNumber(meanX)],
      ["Mean y", formatNumber(meanY)],
      ["Slope", formatNumber(slope)],
      ["Intercept", formatNumber(intercept)],
      ["Correlation r", formatNumber(r)],
      ["R squared", formatNumber(rSquared)],
      ["SSE", formatNumber(sse)],
      ["Residual standard error", Number.isFinite(mse) ? formatNumber(Math.sqrt(mse)) : "undefined"],
      ...regressionInferenceArtifacts(inference),
      ...(prediction
        ? [
            ["Prediction x", formatNumber(prediction.x)],
            ["Predicted y", formatNumber(prediction.yHat)],
            ["Mean response SE", formatNumber(prediction.meanStandardError)],
            [`${percent}% mean response CI`, `[${formatNumber(prediction.meanLower)}, ${formatNumber(prediction.meanUpper)}]`],
            ["Prediction SE", formatNumber(prediction.predictionStandardError)],
            [`${percent}% prediction interval`, `[${formatNumber(prediction.predictionLower)}, ${formatNumber(prediction.predictionUpper)}]`],
          ]
        : []),
    ],
    graph: buildScatterFitGraph(xValues, yValues, slope, intercept, "Least-squares fit"),
  };
}

function analyzeTimeSeries(statement) {
  if (isArimaQuestion(statement.toLowerCase())) {
    return analyzeArimaForecast(statement);
  }

  const request = parseTimeSeriesInput(statement);
  const result = fitAr1TimeSeries(request.values, request.forecastSteps);
  const lastForecast = result.forecasts[result.forecasts.length - 1];

  return {
    mode: "statistics",
    tree: statsDatasetNode(request.values, [
      statsMetricNode("PHI", result.phi),
      statsMetricNode("A", result.intercept),
      statsMetricNode("R2", result.rSquared),
      statsMetricNode("FORECAST", lastForecast.value),
    ], "AR(1)"),
    answer: `${request.forecastSteps}-step forecast = ${formatNumber(lastForecast.value)}`,
    summary: "AR(1) time-series forecast",
    details: "Autoregressive model with lag-1 dependence",
    variables: [],
    metrics: treeMetrics(statsDatasetNode(request.values)),
    steps: [
      {
        title: "Build lagged pairs",
        expression: `${request.values.length - 1} pairs: y_t on y_(t-1)`,
        detail: "AR(1) fits the current value as a linear function of the previous value.",
      },
      {
        title: "Estimate autoregressive model",
        expression: `y_t = ${formatNumber(result.intercept)} + ${formatNumber(result.phi)}y_(t-1)`,
        detail: "Least squares estimates the intercept and lag coefficient.",
      },
      {
        title: "Measure fit",
        expression: `R^2 = ${formatNumber(result.rSquared)}, lag-1 r = ${formatNumber(result.lagCorrelation)}`,
        detail: "The lag-1 correlation and R squared describe serial dependence.",
      },
      {
        title: "Forecast forward",
        expression: `${request.forecastSteps}-step forecast = ${formatNumber(lastForecast.value)}`,
        detail: "Each forecast becomes the previous value for the next step.",
      },
    ],
    table: {
      headers: ["Step", "Forecast"],
      rows: result.forecasts.map((forecast) => [
        formatNumber(forecast.step),
        formatNumber(forecast.value),
      ]),
    },
    artifacts: [
      ["Intercept", formatNumber(result.intercept)],
      ["Lag coefficient phi", formatNumber(result.phi)],
      ["Lag-1 correlation", formatNumber(result.lagCorrelation)],
      ["R squared", formatNumber(result.rSquared)],
      ["Residual SSE", formatNumber(result.sse)],
      ["Innovation SD", formatNumber(result.innovationSd)],
      ["Last observed value", formatNumber(request.values.at(-1))],
      [`${request.forecastSteps}-step forecast`, formatNumber(lastForecast.value)],
    ],
  };
}

function analyzeArimaForecast(statement) {
  const request = parseArimaInput(statement);
  const result = fitArimaAutoregression(request.values, request.p, request.d, request.forecastSteps);
  const lastForecast = result.forecasts.at(-1);
  const modelLabel = `ARIMA(${request.p}, ${request.d}, 0)`;
  const tree = statsDatasetNode(request.values, [
    statsMetricNode("p", request.p),
    statsMetricNode("d", request.d),
    statsMetricNode("sigma", result.innovationSd),
    statsMetricNode("FORECAST", lastForecast.value),
  ], "ARIMA");

  return {
    mode: "statistics",
    tree,
    answer: `${modelLabel} ${request.forecastSteps}-step forecast = ${formatNumber(lastForecast.value)}`,
    summary: "ARIMA forecast",
    details: `${modelLabel} autoregression on ${request.d === 0 ? "original" : `${request.d}-times differenced`} series`,
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read ARIMA order and series",
        expression: `${modelLabel}, n = ${formatNumber(request.values.length)}, horizon = ${formatNumber(request.forecastSteps)}`,
        detail: "ARIMA(p,d,0) differences the series d times, then fits an autoregression with p lag terms.",
      },
      {
        title: "Difference the series",
        expression: formatVector(result.differenced),
        detail: request.d === 0
          ? "With d = 0, the original series is modeled directly."
          : "Differencing removes trend before the autoregressive model is fit.",
      },
      {
        title: "Fit autoregression",
        expression: `w_t = ${formatNumber(result.intercept)}${result.phi.map((value, index) => ` ${formatSignedTerm(value, `w_(t-${index + 1})`)}`).join("")}`,
        detail: "Least squares estimates the intercept and autoregressive lag coefficients.",
      },
      {
        title: "Forecast and invert differencing",
        expression: `${request.forecastSteps}-step forecast = ${formatNumber(lastForecast.value)}`,
        detail: "Future differenced forecasts are cumulatively added back to the latest observed series levels.",
      },
    ],
    table: {
      headers: ["Step", "Differenced forecast", "Forecast"],
      rows: result.forecasts.map((forecast) => [
        formatNumber(forecast.step),
        formatNumber(forecast.differencedValue),
        formatNumber(forecast.value),
      ]),
    },
    artifacts: [
      ["Model", modelLabel],
      ["Differenced series", formatVector(result.differenced)],
      ["Intercept", formatNumber(result.intercept)],
      ["AR coefficients", formatVector(result.phi)],
      ["Fitted values", formatVector(result.fitted)],
      ["Residuals", formatVector(result.residuals)],
      ["Residual SSE", formatNumber(result.sse)],
      ["Innovation SD", formatNumber(result.innovationSd)],
      ["Last observed value", formatNumber(request.values.at(-1))],
      [`${request.forecastSteps}-step forecast`, formatNumber(lastForecast.value)],
    ],
  };
}

function fitAr1TimeSeries(values, forecastSteps) {
  const lagged = values.slice(0, -1);
  const current = values.slice(1);
  const meanLag = mean(lagged);
  const meanCurrent = mean(current);
  const sxx = lagged.reduce((sum, value) => sum + (value - meanLag) ** 2, 0);
  const syy = current.reduce((sum, value) => sum + (value - meanCurrent) ** 2, 0);
  const sxy = lagged.reduce(
    (sum, value, index) => sum + (value - meanLag) * (current[index] - meanCurrent),
    0,
  );

  if (nearlyEqual(sxx, 0) || nearlyEqual(syy, 0)) {
    throw new Error("AR(1) needs variation in both lagged and current values.");
  }

  const phi = sxy / sxx;
  const intercept = meanCurrent - phi * meanLag;
  const fitted = lagged.map((value) => intercept + phi * value);
  const residuals = current.map((value, index) => value - fitted[index]);
  const sse = residuals.reduce((sum, value) => sum + value ** 2, 0);
  const rSquared = 1 - sse / syy;
  const lagCorrelation = sxy / Math.sqrt(sxx * syy);
  const innovationSd = Math.sqrt(sse / Math.max(1, current.length - 2));
  const forecasts = [];
  let previous = values.at(-1);

  for (let step = 1; step <= forecastSteps; step += 1) {
    previous = intercept + phi * previous;
    forecasts.push({
      step,
      value: normalizeNumber(previous),
    });
  }

  return {
    intercept: normalizeNumber(intercept),
    phi: normalizeNumber(phi),
    fitted: fitted.map(normalizeNumber),
    residuals: residuals.map(normalizeNumber),
    sse: normalizeNumber(sse),
    rSquared: normalizeNumber(rSquared),
    lagCorrelation: normalizeNumber(lagCorrelation),
    innovationSd: normalizeNumber(innovationSd),
    forecasts,
  };
}

function fitArimaAutoregression(values, p, d, forecastSteps) {
  const differenced = differenceSeries(values, d);
  if (differenced.length <= p + 1) {
    throw new Error("ARIMA needs enough observations after differencing to estimate lag coefficients.");
  }

  const design = [];
  const response = [];
  for (let index = p; index < differenced.length; index += 1) {
    design.push([
      1,
      ...Array.from({ length: p }, (_, lag) => differenced[index - lag - 1]),
    ]);
    response.push(differenced[index]);
  }

  const fit = fitAutoregressionLeastSquares(response, design);
  const intercept = fit.coefficients[0];
  const phi = fit.coefficients.slice(1);
  const history = [...differenced];
  const states = differencingStates(values, d);
  const forecasts = [];

  for (let step = 1; step <= forecastSteps; step += 1) {
    const lagValues = Array.from({ length: p }, (_, lag) => history[history.length - lag - 1]);
    const differencedValue = intercept + dotProduct(phi, lagValues);
    history.push(differencedValue);
    const value = invertDifferencedForecast(states, differencedValue);
    forecasts.push({
      step,
      differencedValue: normalizeNumber(differencedValue),
      value: normalizeNumber(value),
    });
  }

  return {
    differenced: differenced.map(normalizeNumber),
    intercept: normalizeNumber(intercept),
    phi: phi.map(normalizeNumber),
    fitted: fit.fitted,
    residuals: fit.residuals,
    sse: fit.sse,
    innovationSd: normalizeNumber(Math.sqrt(fit.mse)),
    forecasts,
  };
}

function fitAutoregressionLeastSquares(response, design) {
  const transposed = transposeMatrix(design);
  const normalMatrix = multiplyMatrices(transposed, design);
  const normalVector = multiplyMatrixVector(transposed, response);
  let coefficients;
  try {
    coefficients = solveLinearSystem(normalMatrix, normalVector).map(normalizeNumber);
  } catch {
    const ridge = normalMatrix.map((row, rowIndex) =>
      row.map((value, columnIndex) => value + (rowIndex === columnIndex ? 1e-8 : 0)),
    );
    coefficients = solveLinearSystem(ridge, normalVector).map(normalizeNumber);
  }
  const fitted = design.map((row) => normalizeNumber(dotProduct(row, coefficients)));
  const residuals = response.map((value, index) => normalizeNumber(value - fitted[index]));
  const sse = residuals.reduce((sum, value) => sum + value ** 2, 0);
  const degreesFreedom = Math.max(1, response.length - coefficients.length);

  return {
    coefficients,
    fitted,
    residuals,
    sse: normalizeNumber(sse),
    mse: normalizeNumber(sse / degreesFreedom),
  };
}

function differenceSeries(values, order) {
  let current = [...values];
  for (let level = 0; level < order; level += 1) {
    current = current.slice(1).map((value, index) => value - current[index]);
  }
  return current;
}

function differencingStates(values, order) {
  const states = [values.at(-1)];
  let current = [...values];
  for (let level = 1; level <= order; level += 1) {
    current = current.slice(1).map((value, index) => value - current[index]);
    states.push(current.at(-1));
  }
  return states;
}

function invertDifferencedForecast(states, differencedValue) {
  if (states.length === 1) {
    states[0] = differencedValue;
    return states[0];
  }

  states[states.length - 1] = differencedValue;
  for (let level = states.length - 2; level >= 0; level -= 1) {
    states[level] += states[level + 1];
  }
  return states[0];
}

function analyzePolynomialRegression(statement) {
  const request = parsePolynomialRegressionInput(statement);
  const design = request.x.map((x) =>
    Array.from({ length: request.degree + 1 }, (_, power) => x ** power),
  );
  const transposed = transposeMatrix(design);
  const normalMatrix = multiplyMatrices(transposed, design);
  const normalVector = multiplyMatrixVector(transposed, request.y);
  const coefficients = solveLinearSystem(normalMatrix, normalVector).map(normalizeNumber);
  const fitted = design.map((row) => normalizeNumber(dotProduct(row, coefficients)));
  const residuals = request.y.map((value, index) => normalizeNumber(value - fitted[index]));
  const meanY = mean(request.y);
  const sse = residuals.reduce((sum, value) => sum + value ** 2, 0);
  const tss = request.y.reduce((sum, value) => sum + (value - meanY) ** 2, 0);
  const rSquared = nearlyEqual(tss, 0) ? 1 : 1 - sse / tss;
  const equation = formatPolynomialRegressionEquation(coefficients, "x");
  const prediction = Number.isFinite(request.prediction)
    ? evaluatePolynomialRegression(coefficients, request.prediction)
    : Number.NaN;
  const hasPrediction = Number.isFinite(prediction);
  const tree = {
    kind: "statsRegression",
    label: "POLY",
    children: [
      statsDatasetNode(request.x, [], "X"),
      statsDatasetNode(request.y, [], "Y"),
      statsMetricNode("degree", request.degree),
      statsMetricNode("R2", rSquared),
    ],
  };

  return {
    mode: "statistics",
    tree,
    answer: hasPrediction
      ? `${equation}; prediction = ${formatNumber(prediction)}`
      : equation,
    summary: "polynomial regression",
    details: `${request.x.length} observations, degree ${request.degree}`,
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read paired data and degree",
        expression: `degree = ${request.degree}, points = ${request.x.map((x, index) => `(${formatNumber(x)}, ${formatNumber(request.y[index])})`).join(", ")}`,
        detail: "Polynomial regression fits a nonlinear curve to paired data.",
      },
      {
        title: "Build polynomial design matrix",
        expression: `${request.x.length} x ${request.degree + 1}`,
        detail: "Each row contains powers 1, x, x^2, and so on up to the requested degree.",
      },
      {
        title: "Solve least-squares system",
        expression: equation,
        detail: "The coefficients solve the normal equations for the smallest squared residuals.",
      },
      {
        title: "Measure curve fit",
        expression: `R^2 = ${formatNumber(rSquared)}, SSE = ${formatNumber(sse)}`,
        detail: "R squared compares the fitted curve against using only the mean response.",
      },
      ...(hasPrediction
        ? [{
            title: "Predict new response",
            expression: `prediction = ${formatNumber(prediction)}`,
            detail: "The new x value is evaluated through the fitted polynomial.",
          }]
        : []),
    ],
    table: {
      headers: ["Obs", "x", "Actual", "Fitted", "Residual"],
      rows: request.y.map((value, index) => [
        String(index + 1),
        formatNumber(request.x[index]),
        formatNumber(value),
        formatNumber(fitted[index]),
        formatNumber(residuals[index]),
      ]),
    },
    artifacts: [
      ["Equation", equation],
      ["Degree", formatNumber(request.degree)],
      ...coefficients.map((coefficient, index) => [`Coefficient x^${index}`, formatNumber(coefficient)]),
      ["SSE", formatNumber(sse)],
      ["R squared", formatNumber(rSquared)],
      ...(hasPrediction ? [["Prediction", formatNumber(prediction)]] : []),
    ],
  };
}

function analyzeRegressionModelComparison(statement) {
  const request = parseRegressionModelComparisonInput(statement);
  const models = request.degrees.map((degree) =>
    fitPolynomialComparisonModel(request.x, request.y, degree, request.validation),
  );
  const criterion = models.every((model) => Number.isFinite(model.aicc)) ? "AICc" : "AIC";
  const best = pickBestRegressionComparisonModel(models, criterion);
  const bestCv = pickBestRegressionComparisonCvModel(models);
  const criterionGraph = buildRegressionModelComparisonGraph(models, criterion);
  const cvGraph = buildRegressionCvComparisonGraph(models);
  const requestedValidationGraphs = buildRequestedRegressionValidationGraphs(models, request.validation);
  const tableHeaders = regressionComparisonTableHeaders(request.validation);
  const tree = {
    kind: "statsRegression",
    label: "MODEL CMP",
    children: [
      statsDatasetNode(request.x, [], "X"),
      statsDatasetNode(request.y, [], "Y"),
      ...models.map((model) => statsMetricNode(`d${model.degree}`, regressionComparisonCriterionValue(model, criterion))),
    ],
  };

  return {
    mode: "statistics",
    tree,
    answer: `best degree ${best.degree} by ${criterion}: ${best.equation}`,
    summary: "regression model comparison",
    details: regressionComparisonDetails(request),
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read candidate models",
        expression: `degrees ${request.degrees.join(", ")}`,
        detail: "Each candidate is a polynomial regression model fit to the same paired data.",
      },
      {
        title: "Fit least-squares curves",
        expression: models.map((model) => `degree ${model.degree}: SSE=${formatNumber(model.sse)}`).join("; "),
        detail: "The solver solves normal equations for every candidate degree.",
      },
      {
        title: "Penalize complexity",
        expression: `${criterion}: lower is better`,
        detail: "AIC, AICc, and BIC reward smaller residual error while penalizing extra coefficients.",
      },
      {
        title: "Cross-validate predictions",
        expression: models.map((model) => `degree ${model.degree}: LOOCV RMSE=${formatFiniteNumber(model.loocvRmse)}`).join("; "),
        detail: "Leave-one-out cross-validation refits each candidate after holding out one observation, then scores the held-out prediction errors.",
      },
      ...requestedRegressionValidationSteps(models, request.validation),
      {
        title: "Select best model",
        expression: `degree ${best.degree}`,
        detail: `The selected model has the smallest ${criterion} among the candidates.`,
      },
    ],
    table: {
      headers: tableHeaders,
      rows: models.map((model) => regressionComparisonTableRow(model, request.validation)),
    },
    artifacts: [
      ["Criterion", criterion],
      ["Best degree", formatNumber(best.degree)],
      ["Best equation", best.equation],
      ["Best SSE", formatNumber(best.sse)],
      ["Best adjusted R squared", formatNumber(best.adjustedRSquared)],
      ["Best AIC", formatNumber(best.aic)],
      ["Best AICc", Number.isFinite(best.aicc) ? formatNumber(best.aicc) : "undefined"],
      ["Best BIC", formatNumber(best.bic)],
      ["LOOCV best degree", bestCv ? formatNumber(bestCv.degree) : "undefined"],
      ["LOOCV best RMSE", bestCv ? formatNumber(bestCv.loocvRmse) : "undefined"],
      ["LOOCV best MAE", bestCv ? formatNumber(bestCv.loocvMae) : "undefined"],
      ...requestedRegressionValidationArtifacts(models, request.validation),
    ],
    graph: criterionGraph,
    graphs: [criterionGraph, cvGraph, ...requestedValidationGraphs].filter(Boolean),
  };
}

function analyzeNonlinearRegressionModelComparison(statement) {
  const request = parseNonlinearRegressionModelComparisonInput(statement);
  const models = request.families.map((family) =>
    fitNonlinearRegressionFamily(request.x, request.y, family),
  );
  const viableModels = models.filter((model) => model.viable);
  if (viableModels.length < 2) {
    throw new Error("Nonlinear regression model comparison needs at least two valid model families for the supplied x and y data.");
  }

  const criterion = viableModels.every((model) => Number.isFinite(model.aicc)) ? "AICc" : "AIC";
  const best = pickBestNonlinearRegressionModel(viableModels, criterion);
  const criterionGraph = buildNonlinearRegressionCriterionGraph(viableModels, criterion);
  const fitGraph = buildNonlinearRegressionFitGraph(request.x, request.y, best);
  const familyOrder = viableModels.map((model, index) => `${index + 1}=${model.label}`).join(", ");

  return {
    mode: "statistics",
    tree: {
      kind: "statsRegression",
      label: "NONLINEAR CMP",
      children: [
        statsDatasetNode(request.x, [], "X"),
        statsDatasetNode(request.y, [], "Y"),
        ...viableModels.map((model) => statsMetricNode(model.family, nonlinearRegressionCriterionValue(model, criterion))),
      ],
    },
    answer: `best ${best.label.toLowerCase()} model by ${criterion}: ${best.equation}`,
    summary: "nonlinear regression model comparison",
    details: `${request.x.length} observations, families ${models.map((model) => model.label).join(", ")}`,
    variables: [],
    metrics: treeMetrics(statsDatasetNode(request.y, viableModels.map((model) =>
      statsMetricNode(model.family, nonlinearRegressionCriterionValue(model, criterion)),
    ))),
    steps: [
      {
        title: "Read candidate families",
        expression: models.map((model) => model.label).join(", "),
        detail: "The solver compares nonlinear families that can be fit by a transparent transformed least-squares model.",
      },
      {
        title: "Transform eligible models",
        expression: viableModels.map((model) => `${model.label}: ${model.transformedEquation}`).join("; "),
        detail: "Exponential and power-law models use log-response transforms; logarithmic models transform x; logistic growth uses damped nonlinear least squares.",
      },
      {
        title: "Score on original scale",
        expression: viableModels.map((model) => `${model.label}: SSE=${formatNumber(model.sse)}`).join("; "),
        detail: "Each fitted curve is converted back to original y values before SSE, R squared, AIC, AICc, and BIC are computed.",
      },
      {
        title: "Select best family",
        expression: `${criterion} minimum: ${best.label}`,
        detail: `${criterion} penalizes extra error while keeping the comparison on the same response scale.`,
      },
    ],
    table: {
      headers: ["Family", "Equation", "SSE", "R squared", "AIC", "AICc", "BIC", "Status"],
      rows: models.map((model) => [
        model.label,
        model.equation,
        formatFiniteNumber(model.sse),
        formatFiniteNumber(model.rSquared),
        formatFiniteNumber(model.aic),
        formatFiniteNumber(model.aicc),
        formatFiniteNumber(model.bic),
        model.status,
      ]),
    },
    artifacts: [
      ["Criterion", criterion],
      ["Best family", best.label],
      ["Best equation", best.equation],
      ["Best SSE", formatNumber(best.sse)],
      ["Best R squared", formatNumber(best.rSquared)],
      ["Best AIC", formatNumber(best.aic)],
      ["Best AICc", Number.isFinite(best.aicc) ? formatNumber(best.aicc) : "undefined"],
      ["Best BIC", formatNumber(best.bic)],
      ["Graph family order", familyOrder],
    ],
    graph: fitGraph,
    graphs: [fitGraph, criterionGraph].filter(Boolean),
  };
}

function analyzeCustomNonlinearRegressionModelComparison(statement) {
  const request = parseCustomNonlinearRegressionModelComparisonInput(statement);
  const models = request.entries.map((entry, index) =>
    fitCustomNonlinearComparisonModel(request, entry, index + 1),
  );
  const viableModels = models.filter((model) => model.viable);
  if (viableModels.length < 2) {
    throw new Error("Custom nonlinear model comparison needs at least two valid fitted formulas.");
  }

  const criterion = selectCustomNonlinearComparisonCriterion(viableModels, request.criterion);
  const weightedModels = applyNonlinearComparisonWeights(models, criterion);
  const weightedViable = weightedModels.filter((model) => model.viable);
  const best = pickBestNonlinearRegressionModel(weightedViable, criterion);
  const prediction = Number.isFinite(request.prediction)
    ? customNonlinearModelAveragedPrediction(weightedViable, request.prediction)
    : null;
  const bootstrap = request.bootstrap.resamples
    ? bootstrapCustomNonlinearModelComparison(request, criterion)
    : null;
  const averagedRows = customNonlinearModelAveragedRows(weightedViable, request);
  const bestGraph = buildNonlinearRegressionFitGraph(request.x, request.y, best);
  const averagedGraph = buildNonlinearRegressionFitGraph(request.x, request.y, {
    label: "Model-averaged custom",
    predict: (x) => customNonlinearWeightedPrediction(weightedViable, x),
  });
  const criterionGraph = buildNonlinearRegressionCriterionGraph(
    weightedViable,
    criterion,
    `${criterion} by custom nonlinear model`,
  );
  const loocvGraph = buildCustomNonlinearValidationMetricGraph(
    weightedViable,
    "loocvRmse",
    "LOOCV RMSE by custom nonlinear model",
    "LOOCV RMSE",
  );
  const requestedValidationGraphs = buildRequestedCustomNonlinearValidationGraphs(
    weightedViable,
    request.validation,
  );
  const bootstrapGraphs = buildCustomNonlinearBootstrapGraphs(bootstrap, request);

  return {
    mode: "statistics",
    tree: {
      kind: "statsRegression",
      label: "CUSTOM CMP",
      children: [
        statsDatasetNode(request.x, [], "X"),
        statsDatasetNode(request.y, [], "Y"),
        ...weightedViable.map((model) => statsMetricNode(model.label, nonlinearRegressionCriterionValue(model, criterion))),
      ],
    },
    answer: `best ${best.label} by ${criterion}: ${best.equation}${prediction ? `; averaged prediction = ${formatNumber(prediction.yHat)}` : ""}${bootstrap?.prediction ? `; bootstrap ${formatNumber(request.level * 100)}% CI = [${formatNumber(bootstrap.prediction.lower)}, ${formatNumber(bootstrap.prediction.upper)}]` : ""}`,
    summary: "custom nonlinear model comparison",
    details: customNonlinearComparisonDetails(request),
    variables: [],
    metrics: treeMetrics(statsDatasetNode(request.y, weightedViable.map((model) =>
      statsMetricNode(model.label, nonlinearRegressionCriterionValue(model, criterion)),
    ))),
    steps: [
      {
        title: "Read custom candidate formulas",
        expression: request.entries.map((entry) => `${entry.label}: ${entry.formula}`).join("; "),
        detail: "Each candidate is parsed as an expression tree with the same input variable and response data.",
      },
      {
        title: "Fit every candidate",
        expression: weightedViable.map((model) => `${model.label}: SSE=${formatNumber(model.sse)}`).join("; "),
        detail: "The solver runs bounded multi-start damped least squares for every custom formula.",
      },
      {
        title: "Score and weight models",
        expression: weightedViable.map((model) => `${model.label}: ${criterion}=${formatNumber(nonlinearRegressionCriterionValue(model, criterion))}, weight=${formatNumber(model.weight)}`).join("; "),
        detail: "Akaike-style weights are computed from criterion deltas so close models can contribute to an averaged prediction.",
      },
      {
        title: "Cross-validate candidates",
        expression: weightedViable.map((model) => `${model.label}: LOOCV RMSE=${formatFiniteNumber(model.loocvRmse)}`).join("; "),
        detail: "Leave-one-out cross-validation refits each custom formula after holding out one observation and scores held-out prediction error.",
      },
      ...requestedCustomNonlinearValidationSteps(weightedViable, request.validation),
      ...(prediction
        ? [{
            title: "Average requested prediction",
            expression: `${request.variable}=${formatNumber(prediction.x)}, averaged ${request.response}=${formatNumber(prediction.yHat)}`,
            detail: "The model-averaged prediction is the weighted mean of finite candidate predictions.",
          }]
        : []),
      ...(bootstrap
        ? [{
            title: "Bootstrap model uncertainty",
            expression: `${formatNumber(bootstrap.validResamples)} / ${formatNumber(bootstrap.resamples)} valid resamples`,
            detail: "Bootstrap rows are sampled with replacement, every custom formula is refit, and model weights plus averaged predictions are recomputed.",
          }]
        : []),
      {
        title: "Select best custom model",
        expression: `${best.label}: ${best.equation}`,
        detail: `The selected model has the smallest ${criterion}; weights are still shown for model-selection uncertainty.`,
      },
    ],
    table: {
      headers: customNonlinearComparisonTableHeaders(request.validation),
      rows: weightedModels.map((model) => customNonlinearComparisonTableRow(model, request)),
    },
    artifacts: [
      ["Criterion", criterion],
      ["Best model", best.label],
      ["Best formula", best.equation],
      ["Best SSE", formatNumber(best.sse)],
      ["Best R squared", formatNumber(best.rSquared)],
      ["Best weight", formatNumber(best.weight)],
      ["Model weights", weightedViable.map((model) => `${model.label}=${formatNumber(model.weight)}`).join(", ")],
      ["LOOCV best model", pickBestCustomNonlinearMetricModel(weightedViable, "loocvRmse", "loocvMae")?.label ?? "undefined"],
      ["LOOCV best RMSE", formatFiniteNumber(pickBestCustomNonlinearMetricModel(weightedViable, "loocvRmse", "loocvMae")?.loocvRmse)],
      ["LOOCV best MAE", formatFiniteNumber(pickBestCustomNonlinearMetricModel(weightedViable, "loocvRmse", "loocvMae")?.loocvMae)],
      ...requestedCustomNonlinearValidationArtifacts(weightedViable, request.validation),
      ...customNonlinearBootstrapArtifacts(bootstrap, request),
      ...(prediction ? [
        ["Prediction x", formatNumber(prediction.x)],
        ["Best model prediction", formatFiniteNumber(best.prediction?.yHat)],
        ["Model-averaged prediction", formatNumber(prediction.yHat)],
      ] : []),
    ],
    graph: bestGraph,
    graphs: [bestGraph, averagedGraph, criterionGraph, loocvGraph, ...requestedValidationGraphs, ...bootstrapGraphs].filter(Boolean),
    extraTables: [
      {
        title: "Model-averaged fitted values",
        headers: ["Obs", request.variable, "Actual", "Averaged fitted", "Residual"],
        rows: averagedRows,
      },
      ...customNonlinearBootstrapExtraTables(bootstrap),
    ],
  };
}

