function fitPolynomialComparisonModel(xValues, yValues, degree, validation = {}) {
  const coefficients = fitPolynomialCoefficients(xValues, yValues, degree);
  const fitted = xValues.map((x) => polynomialPrediction(coefficients, x));
  const residuals = yValues.map((value, index) => normalizeNumber(value - fitted[index]));
  const loocv = leaveOneOutPolynomialValidation(xValues, yValues, degree);
  const kFold = validation.kFold
    ? kFoldPolynomialValidation(xValues, yValues, degree, validation.kFold)
    : null;
  const holdout = validation.holdoutCount
    ? holdoutPolynomialValidation(xValues, yValues, degree, validation.holdoutCount)
    : null;
  const n = yValues.length;
  const parameterCount = degree + 1;
  const degreesFreedom = n - parameterCount;
  const sse = residuals.reduce((sum, value) => sum + value ** 2, 0);
  const meanY = mean(yValues);
  const tss = yValues.reduce((sum, value) => sum + (value - meanY) ** 2, 0);
  const rSquared = nearlyEqual(tss, 0) ? 1 : 1 - sse / tss;
  const adjustedRSquared = 1 - (1 - rSquared) * (n - 1) / degreesFreedom;
  const varianceEstimate = Math.max(sse / n, EPSILON);
  const aic = n * Math.log(varianceEstimate) + 2 * parameterCount;
  const aiccDenominator = n - parameterCount - 1;
  const aicc = aiccDenominator > 0
    ? aic + (2 * parameterCount * (parameterCount + 1)) / aiccDenominator
    : Number.NaN;
  const bic = n * Math.log(varianceEstimate) + parameterCount * Math.log(n);

  return {
    degree,
    coefficients,
    fitted,
    residuals,
    sse: normalizeNumber(sse),
    rSquared: normalizeNumber(rSquared),
    adjustedRSquared: normalizeNumber(adjustedRSquared),
    aic: normalizeNumber(aic),
    aicc: Number.isFinite(aicc) ? normalizeNumber(aicc) : Number.NaN,
    bic: normalizeNumber(bic),
    loocvRmse: loocv.rmse,
    loocvMae: loocv.mae,
    loocvErrors: loocv.errors,
    loocvPredictions: loocv.predictions,
    kFoldRmse: kFold?.rmse ?? Number.NaN,
    kFoldMae: kFold?.mae ?? Number.NaN,
    kFoldErrors: kFold?.errors ?? [],
    kFoldPredictions: kFold?.predictions ?? [],
    holdoutRmse: holdout?.rmse ?? Number.NaN,
    holdoutMae: holdout?.mae ?? Number.NaN,
    holdoutErrors: holdout?.errors ?? [],
    holdoutPredictions: holdout?.predictions ?? [],
    equation: formatPolynomialRegressionEquation(coefficients, "x"),
  };
}

function fitNonlinearRegressionFamily(xValues, yValues, family) {
  const definition = nonlinearRegressionFamilyDefinition(family);
  if (!definition.domain(xValues, yValues)) {
    return invalidNonlinearRegressionModel(family, definition, definition.domainMessage);
  }

  if (definition.fit) {
    try {
      return definition.fit(xValues, yValues);
    } catch {
      return invalidNonlinearRegressionModel(family, definition, "fit did not converge");
    }
  }

  const transformedX = xValues.map(definition.transformX);
  const transformedY = yValues.map(definition.transformY);
  const coefficients = fitPolynomialCoefficients(transformedX, transformedY, 1);
  const fitted = xValues.map((x) => normalizeNumber(definition.predict(coefficients, x)));
  if (fitted.some((value) => !Number.isFinite(value))) {
    return invalidNonlinearRegressionModel(family, definition, "produced non-finite fitted values");
  }

  return scoreNonlinearRegressionFit({
    family,
    label: definition.label,
    equation: definition.formatEquation(coefficients),
    transformedEquation: definition.transformedEquation,
    coefficients,
    fitted,
    parameterCount: definition.parameterCount,
    status: "fit",
    predict: (x) => normalizeNumber(definition.predict(coefficients, x)),
  }, yValues);
}

function invalidNonlinearRegressionModel(family, definition, status) {
  return {
    family,
    label: definition.label,
    equation: "undefined",
    transformedEquation: definition.transformedEquation,
    status,
    viable: false,
    sse: Number.NaN,
    rSquared: Number.NaN,
    aic: Number.NaN,
    aicc: Number.NaN,
    bic: Number.NaN,
    fitted: [],
    residuals: [],
  };
}

function scoreNonlinearRegressionFit(model, yValues) {
  const residuals = yValues.map((value, index) => normalizeNumber(value - model.fitted[index]));
  const sse = residuals.reduce((sum, value) => sum + value ** 2, 0);
  const meanY = mean(yValues);
  const tss = yValues.reduce((sum, value) => sum + (value - meanY) ** 2, 0);
  const rSquared = nearlyEqual(tss, 0) ? 1 : 1 - sse / tss;
  const n = yValues.length;
  const parameterCount = model.parameterCount ?? 2;
  const varianceEstimate = Math.max(sse / n, EPSILON);
  const aic = n * Math.log(varianceEstimate) + 2 * parameterCount;
  const aiccDenominator = n - parameterCount - 1;
  const aicc = aiccDenominator > 0
    ? aic + (2 * parameterCount * (parameterCount + 1)) / aiccDenominator
    : Number.NaN;
  const bic = n * Math.log(varianceEstimate) + parameterCount * Math.log(n);

  return {
    ...model,
    residuals,
    sse: normalizeNumber(sse),
    rSquared: normalizeNumber(rSquared),
    aic: normalizeNumber(aic),
    aicc: Number.isFinite(aicc) ? normalizeNumber(aicc) : Number.NaN,
    bic: normalizeNumber(bic),
    viable: true,
  };
}

function nonlinearRegressionFamilyDefinition(family) {
  const definitions = {
    linear: {
      label: "Linear",
      transformedEquation: "y = a + bx",
      parameterCount: 2,
      domain: () => true,
      domainMessage: "",
      transformX: (x) => x,
      transformY: (y) => y,
      predict: ([intercept, slope], x) => intercept + slope * x,
      formatEquation: ([intercept, slope]) => `y = ${formatNumber(slope)}x ${formatSigned(intercept)}`,
    },
    exponential: {
      label: "Exponential",
      transformedEquation: "ln(y) = a + bx",
      parameterCount: 2,
      domain: (_xValues, yValues) => yValues.every((value) => value > 0),
      domainMessage: "requires y > 0",
      transformX: (x) => x,
      transformY: (y) => Math.log(y),
      predict: ([intercept, slope], x) => Math.exp(intercept + slope * x),
      formatEquation: ([intercept, slope]) => `y = ${formatNumber(Math.exp(intercept))} * e^(${formatNumber(slope)}x)`,
    },
    logarithmic: {
      label: "Logarithmic",
      transformedEquation: "y = a + b ln(x)",
      parameterCount: 2,
      domain: (xValues) => xValues.every((value) => value > 0),
      domainMessage: "requires x > 0",
      transformX: (x) => Math.log(x),
      transformY: (y) => y,
      predict: ([intercept, slope], x) => intercept + slope * Math.log(x),
      formatEquation: ([intercept, slope]) => `y = ${formatNumber(intercept)} ${formatSignedTerm(slope, "ln(x)")}`,
    },
    power: {
      label: "Power-law",
      transformedEquation: "ln(y) = a + b ln(x)",
      parameterCount: 2,
      domain: (xValues, yValues) => xValues.every((value) => value > 0) && yValues.every((value) => value > 0),
      domainMessage: "requires x > 0 and y > 0",
      transformX: (x) => Math.log(x),
      transformY: (y) => Math.log(y),
      predict: ([intercept, slope], x) => Math.exp(intercept) * x ** slope,
      formatEquation: ([intercept, slope]) => `y = ${formatNumber(Math.exp(intercept))} * x^${formatNumber(slope)}`,
    },
    logistic: {
      label: "Logistic growth",
      transformedEquation: "y = L / (1 + e^(-(a + bx)))",
      parameterCount: 3,
      domain: (_xValues, yValues) => yValues.every((value) => value > 0),
      domainMessage: "requires y > 0",
      fit: fitLogisticGrowthRegressionFamily,
    },
  };
  return definitions[family];
}

function fitLogisticGrowthRegressionFamily(xValues, yValues) {
  const definition = nonlinearRegressionFamilyDefinition("logistic");
  const maxY = Math.max(...yValues);
  const minY = Math.min(...yValues);
  const spread = Math.max(EPSILON, maxY - minY);
  const starts = [1.05, 1.2, 1.5, 2, 3, 5, 10]
    .map((multiplier) => Math.max(maxY + spread * 0.05, maxY * multiplier));
  let best = null;

  for (const asymptote of starts) {
    const initial = initialLogisticGrowthParameters(xValues, yValues, asymptote);
    const fit = runLogisticGrowthLeastSquares(xValues, yValues, initial);
    if (fit && (!best || fit.sse < best.sse)) {
      best = fit;
    }
  }

  if (!best) {
    throw new Error("fit did not converge");
  }

  const coefficients = best.parameters.map(normalizeNumber);
  const fitted = xValues.map((x) => normalizeNumber(predictLogisticGrowth(coefficients, x)));
  return scoreNonlinearRegressionFit({
    family: "logistic",
    label: definition.label,
    equation: formatLogisticGrowthEquation(coefficients),
    transformedEquation: definition.transformedEquation,
    coefficients,
    fitted,
    parameterCount: definition.parameterCount,
    status: `fit in ${best.iterations} iterations`,
    predict: (x) => normalizeNumber(predictLogisticGrowth(coefficients, x)),
  }, yValues);
}

function initialLogisticGrowthParameters(xValues, yValues, asymptote) {
  const adjustedY = yValues.map((value) =>
    Math.min(asymptote - EPSILON, Math.max(EPSILON, value)),
  );
  const logits = adjustedY.map((value) => Math.log(value / (asymptote - value)));
  const [intercept, slope] = fitPolynomialCoefficients(xValues, logits, 1);
  return [asymptote, intercept, slope];
}

function runLogisticGrowthLeastSquares(xValues, yValues, initialParameters) {
  const minAsymptote = Math.max(...yValues) + EPSILON;
  let parameters = [...initialParameters];
  let damping = 1e-3;
  let bestSse = logisticGrowthSse(xValues, yValues, parameters);

  if (!Number.isFinite(bestSse)) {
    return null;
  }

  for (let iteration = 1; iteration <= 200; iteration += 1) {
    const normalMatrix = Array.from({ length: 3 }, () => Array(3).fill(0));
    const normalVector = Array(3).fill(0);

    for (let row = 0; row < xValues.length; row += 1) {
      const x = xValues[row];
      const prediction = predictLogisticGrowth(parameters, x);
      const residual = yValues[row] - prediction;
      const gradient = logisticGrowthGradient(parameters, x);
      for (let i = 0; i < 3; i += 1) {
        normalVector[i] += gradient[i] * residual;
        for (let j = 0; j < 3; j += 1) {
          normalMatrix[i][j] += gradient[i] * gradient[j];
        }
      }
    }

    for (let diagonal = 0; diagonal < 3; diagonal += 1) {
      normalMatrix[diagonal][diagonal] += damping * (normalMatrix[diagonal][diagonal] || 1);
    }

    let step;
    try {
      step = solveLinearSystem(normalMatrix, normalVector);
    } catch {
      damping *= 10;
      continue;
    }

    const candidate = parameters.map((value, index) => value + step[index]);
    if (candidate[0] <= minAsymptote || candidate.some((value) => !Number.isFinite(value))) {
      damping *= 10;
      continue;
    }

    const candidateSse = logisticGrowthSse(xValues, yValues, candidate);
    if (Number.isFinite(candidateSse) && candidateSse < bestSse) {
      parameters = candidate;
      if (Math.abs(bestSse - candidateSse) <= 1e-10 * Math.max(1, bestSse)) {
        return { parameters, sse: candidateSse, iterations: iteration };
      }
      bestSse = candidateSse;
      damping = Math.max(damping / 3, 1e-8);
    } else {
      damping *= 10;
    }
  }

  return { parameters, sse: bestSse, iterations: 200 };
}

function logisticGrowthSse(xValues, yValues, parameters) {
  return yValues.reduce((sum, value, index) => {
    const prediction = predictLogisticGrowth(parameters, xValues[index]);
    return sum + (value - prediction) ** 2;
  }, 0);
}

function logisticGrowthGradient([asymptote, intercept, slope], x) {
  const sigmoid = logisticGrowthSigmoid(intercept + slope * x);
  const sensitivity = asymptote * sigmoid * (1 - sigmoid);
  return [
    sigmoid,
    sensitivity,
    sensitivity * x,
  ];
}

function predictLogisticGrowth([asymptote, intercept, slope], x) {
  return asymptote * logisticGrowthSigmoid(intercept + slope * x);
}

function logisticGrowthSigmoid(value) {
  if (value >= 0) {
    const exponent = Math.exp(-value);
    return 1 / (1 + exponent);
  }
  const exponent = Math.exp(value);
  return exponent / (1 + exponent);
}

function formatLogisticGrowthEquation([asymptote, intercept, slope]) {
  return `y = ${formatNumber(asymptote)} / (1 + e^(${formatNumber(-intercept)} ${formatSignedTerm(-slope, "x")}))`;
}

function fitCustomNonlinearComparisonModel(request, entry, modelIndex) {
  try {
    const modelRequest = buildCustomNonlinearComparisonModelRequest(request, entry);
    const fit = fitCustomNonlinearRegression(modelRequest);
    const prediction = Number.isFinite(request.prediction)
      ? customNonlinearRegressionPrediction(modelRequest, fit.parameters, fit.covariance, request.prediction)
      : null;
    const loocv = request.skipValidation
      ? emptyValidationScore()
      : leaveOneOutCustomNonlinearValidation(modelRequest);
    const kFold = !request.skipValidation && request.validation.kFold
      ? kFoldCustomNonlinearValidation(modelRequest, request.validation.kFold)
      : null;
    const holdout = !request.skipValidation && request.validation.holdoutCount
      ? holdoutCustomNonlinearValidation(modelRequest, request.validation.holdoutCount)
      : null;
    return {
      ...fit,
      modelIndex,
      label: entry.label,
      family: `custom${modelIndex}`,
      equation: `${modelRequest.response} = ${modelRequest.formula}`,
      request: modelRequest,
      parameterNames: modelRequest.parameterNames,
      prediction,
      loocvRmse: loocv.rmse,
      loocvMae: loocv.mae,
      loocvErrors: loocv.errors,
      loocvPredictions: loocv.predictions,
      kFoldRmse: kFold?.rmse ?? Number.NaN,
      kFoldMae: kFold?.mae ?? Number.NaN,
      kFoldErrors: kFold?.errors ?? [],
      kFoldPredictions: kFold?.predictions ?? [],
      holdoutRmse: holdout?.rmse ?? Number.NaN,
      holdoutMae: holdout?.mae ?? Number.NaN,
      holdoutErrors: holdout?.errors ?? [],
      holdoutPredictions: holdout?.predictions ?? [],
      status: fit.converged
        ? `fit in ${fit.iterations} iterations`
        : `stopped after ${fit.iterations} iterations`,
    };
  } catch (error) {
    return invalidCustomNonlinearComparisonModel(entry, modelIndex, error.message);
  }
}

function buildCustomNonlinearComparisonModelRequest(request, entry) {
  const formulaInfo = entry.formulaInfo;
  const variable = parseCustomRegressionVariable(request.sourceText, formulaInfo.expression);
  if (variable !== request.variable) {
    throw new Error(`uses ${variable}, not ${request.variable}`);
  }
  const parameterNames = mathVariables(formulaInfo.expression)
    .filter((name) => name !== variable && !isMathConstantName(name));
  if (parameterNames.length === 0) {
    throw new Error("needs at least one fitted parameter");
  }
  if (request.x.length <= parameterNames.length) {
    throw new Error("needs more observations than fitted parameters");
  }
  const bounds = parseCustomRegressionBounds(request.sourceText, parameterNames);
  const initial = parseCustomRegressionInitialParameters(request.sourceText, parameterNames, bounds);
  return {
    response: formulaInfo.response,
    formula: formulaInfo.formula,
    expression: formulaInfo.expression,
    variable,
    parameterNames,
    initial,
    startCount: request.startCount,
    bounds,
    level: request.level,
    maxIterations: request.maxIterations,
    tolerance: request.tolerance,
    prediction: request.prediction,
    x: request.x,
    y: request.y,
  };
}

function invalidCustomNonlinearComparisonModel(entry, modelIndex, status) {
  return {
    modelIndex,
    label: entry.label,
    family: `custom${modelIndex}`,
    equation: entry.formula,
    parameterNames: [],
    parameters: [],
    fitted: [],
    residuals: [],
    viable: false,
    sse: Number.NaN,
    rSquared: Number.NaN,
    aic: Number.NaN,
    aicc: Number.NaN,
    bic: Number.NaN,
    delta: Number.NaN,
    weight: Number.NaN,
    prediction: null,
    loocvRmse: Number.NaN,
    loocvMae: Number.NaN,
    kFoldRmse: Number.NaN,
    kFoldMae: Number.NaN,
    holdoutRmse: Number.NaN,
    holdoutMae: Number.NaN,
    status: `invalid: ${status}`,
  };
}

function selectCustomNonlinearComparisonCriterion(models, requestedCriterion) {
  if (requestedCriterion) {
    const missing = models.some((model) => !Number.isFinite(nonlinearRegressionCriterionValue(model, requestedCriterion)));
    if (missing) {
      throw new Error(`Custom nonlinear model comparison could not compute finite ${requestedCriterion} for every valid model.`);
    }
    return requestedCriterion;
  }
  return models.every((model) => Number.isFinite(model.aicc)) ? "AICc" : "AIC";
}

function applyNonlinearComparisonWeights(models, criterion) {
  const viable = models.filter((model) =>
    model.viable && Number.isFinite(nonlinearRegressionCriterionValue(model, criterion)),
  );
  const bestCriterion = Math.min(...viable.map((model) => nonlinearRegressionCriterionValue(model, criterion)));
  const rawWeights = new Map(viable.map((model) => {
    const delta = nonlinearRegressionCriterionValue(model, criterion) - bestCriterion;
    return [model.modelIndex, { delta, rawWeight: Math.exp(-0.5 * delta) }];
  }));
  const totalWeight = [...rawWeights.values()].reduce((sum, item) => sum + item.rawWeight, 0);
  return models.map((model) => {
    const raw = rawWeights.get(model.modelIndex);
    if (!raw || !(totalWeight > 0)) {
      return {
        ...model,
        delta: Number.NaN,
        weight: Number.NaN,
      };
    }
    return {
      ...model,
      delta: normalizeNumber(raw.delta),
      weight: normalizeNumber(raw.rawWeight / totalWeight),
    };
  });
}

function customNonlinearComparisonDetails(request) {
  const validationDetails = [];
  if (request.validation.kFold) {
    validationDetails.push(`${request.validation.kFold}-fold CV`);
  }
  if (request.validation.holdoutCount) {
    validationDetails.push(`${request.validation.holdoutCount}-point holdout`);
  }
  if (request.bootstrap.resamples) {
    validationDetails.push(`${request.bootstrap.resamples} bootstrap resamples`);
  }
  return [
    `${request.x.length} observations`,
    `${request.entries.length} custom formulas`,
    ...validationDetails,
  ].join(", ");
}

function customNonlinearComparisonTableHeaders(validation) {
  const headers = ["Model", "Formula", "Parameters", "SSE", "R squared", "AIC", "AICc", "BIC", "Delta", "Weight", "LOOCV RMSE", "LOOCV MAE"];
  if (validation.kFold) {
    headers.push("K-fold RMSE", "K-fold MAE");
  }
  if (validation.holdoutCount) {
    headers.push("Holdout RMSE", "Holdout MAE");
  }
  headers.push("Prediction", "Status");
  return headers;
}

function customNonlinearComparisonTableRow(model, request) {
  const row = [
    model.label,
    model.equation,
    model.viable ? formatCustomParameterVector(model.parameters, model.parameterNames) : "undefined",
    formatFiniteNumber(model.sse),
    formatFiniteNumber(model.rSquared),
    formatFiniteNumber(model.aic),
    formatFiniteNumber(model.aicc),
    formatFiniteNumber(model.bic),
    formatFiniteNumber(model.delta),
    formatFiniteNumber(model.weight),
    formatFiniteNumber(model.loocvRmse),
    formatFiniteNumber(model.loocvMae),
  ];
  if (request.validation.kFold) {
    row.push(formatFiniteNumber(model.kFoldRmse), formatFiniteNumber(model.kFoldMae));
  }
  if (request.validation.holdoutCount) {
    row.push(formatFiniteNumber(model.holdoutRmse), formatFiniteNumber(model.holdoutMae));
  }
  row.push(
    Number.isFinite(request.prediction) ? formatFiniteNumber(model.prediction?.yHat) : "",
    model.status,
  );
  return row;
}

function pickBestCustomNonlinearMetricModel(models, rmseKey, maeKey) {
  const candidates = models.filter((model) => Number.isFinite(model[rmseKey]));
  return [...candidates].sort((left, right) =>
    left[rmseKey] - right[rmseKey] ||
    left[maeKey] - right[maeKey] ||
    left.modelIndex - right.modelIndex,
  )[0] ?? null;
}

function requestedCustomNonlinearValidationSteps(models, validation) {
  const steps = [];
  if (validation.kFold) {
    steps.push({
      title: "Run k-fold validation",
      expression: models.map((model) => `${model.label}: RMSE=${formatFiniteNumber(model.kFoldRmse)}`).join("; "),
      detail: `${validation.kFold}-fold validation assigns observations to deterministic round-robin folds and scores held-out custom-model predictions.`,
    });
  }
  if (validation.holdoutCount) {
    steps.push({
      title: "Run holdout validation",
      expression: models.map((model) => `${model.label}: RMSE=${formatFiniteNumber(model.holdoutRmse)}`).join("; "),
      detail: `The solver trains custom formulas on the first ${models[0].fitted.length - validation.holdoutCount} observations and tests on the final ${validation.holdoutCount}.`,
    });
  }
  return steps;
}

function requestedCustomNonlinearValidationArtifacts(models, validation) {
  const artifacts = [];
  if (validation.kFold) {
    const best = pickBestCustomNonlinearMetricModel(models, "kFoldRmse", "kFoldMae");
    artifacts.push(
      ["K-fold count", formatNumber(validation.kFold)],
      ["K-fold best model", best ? best.label : "undefined"],
      ["K-fold best RMSE", formatFiniteNumber(best?.kFoldRmse)],
      ["K-fold best MAE", formatFiniteNumber(best?.kFoldMae)],
    );
  }
  if (validation.holdoutCount) {
    const best = pickBestCustomNonlinearMetricModel(models, "holdoutRmse", "holdoutMae");
    artifacts.push(
      ["Holdout count", formatNumber(validation.holdoutCount)],
      ["Holdout best model", best ? best.label : "undefined"],
      ["Holdout best RMSE", formatFiniteNumber(best?.holdoutRmse)],
      ["Holdout best MAE", formatFiniteNumber(best?.holdoutMae)],
    );
  }
  return artifacts;
}

function buildRequestedCustomNonlinearValidationGraphs(models, validation) {
  return [
    validation.kFold
      ? buildCustomNonlinearValidationMetricGraph(models, "kFoldRmse", `${validation.kFold}-fold RMSE by custom nonlinear model`, "K-fold RMSE")
      : null,
    validation.holdoutCount
      ? buildCustomNonlinearValidationMetricGraph(models, "holdoutRmse", "Holdout RMSE by custom nonlinear model", "Holdout RMSE")
      : null,
  ].filter(Boolean);
}

function buildCustomNonlinearValidationMetricGraph(models, metricKey, expression, scatterLabel) {
  const points = models
    .filter((model) => Number.isFinite(model[metricKey]))
    .map((model, index) => ({
      x: index + 1,
      y: model[metricKey],
    }));
  if (points.length === 0) {
    return null;
  }
  const [yMin, yMax] = paddedNumericRange(points.map((point) => point.y));
  return {
    expression,
    kind: "regression-diagnostic",
    scatterLabel,
    xMin: 1,
    xMax: points.length,
    yMin,
    yMax,
    scatter: points,
    lines: [
      {
        label: scatterLabel,
        points,
      },
    ],
  };
}

function bootstrapCustomNonlinearModelComparison(request, criterion) {
  const random = seededRandom(request.bootstrap.seed);
  const bestCounts = new Map(request.entries.map((entry, index) => [index + 1, 0]));
  const weightSums = new Map(request.entries.map((entry, index) => [index + 1, 0]));
  const predictions = [];
  let validResamples = 0;

  for (let resample = 0; resample < request.bootstrap.resamples; resample += 1) {
    const indices = Array.from({ length: request.x.length }, () => Math.floor(random() * request.x.length));
    const bootstrapRequest = {
      ...request,
      x: indices.map((index) => request.x[index]),
      y: indices.map((index) => request.y[index]),
      validation: { kFold: null, holdoutCount: null },
      bootstrap: { resamples: 0, seed: request.bootstrap.seed },
      skipValidation: true,
    };
    const models = request.entries.map((entry, index) =>
      fitCustomNonlinearComparisonModel(bootstrapRequest, entry, index + 1),
    );
    const viableModels = models.filter((model) => model.viable);
    if (viableModels.length < 2) {
      continue;
    }

    let bootstrapCriterion;
    try {
      bootstrapCriterion = selectCustomNonlinearComparisonCriterion(viableModels, criterion);
    } catch {
      continue;
    }
    const weightedModels = applyNonlinearComparisonWeights(models, bootstrapCriterion);
    const weightedViable = weightedModels.filter((model) => model.viable);
    if (weightedViable.length < 2) {
      continue;
    }

    const best = pickBestNonlinearRegressionModel(weightedViable, bootstrapCriterion);
    bestCounts.set(best.modelIndex, (bestCounts.get(best.modelIndex) ?? 0) + 1);
    for (const model of weightedViable) {
      if (Number.isFinite(model.weight)) {
        weightSums.set(model.modelIndex, (weightSums.get(model.modelIndex) ?? 0) + model.weight);
      }
    }
    if (Number.isFinite(request.prediction)) {
      const prediction = customNonlinearModelAveragedPrediction(weightedViable, request.prediction);
      if (prediction) {
        predictions.push(prediction.yHat);
      }
    }
    validResamples += 1;
  }

  const sortedPredictions = [...predictions].sort((left, right) => left - right);
  const alpha = (1 - request.level) / 2;
  return {
    resamples: request.bootstrap.resamples,
    validResamples,
    seed: request.bootstrap.seed,
    prediction: sortedPredictions.length
      ? {
          x: request.prediction,
          mean: normalizeNumber(mean(sortedPredictions)),
          lower: percentileFromSorted(sortedPredictions, alpha),
          upper: percentileFromSorted(sortedPredictions, 1 - alpha),
        }
      : null,
    modelRows: request.entries.map((entry, index) => {
      const modelIndex = index + 1;
      const count = bestCounts.get(modelIndex) ?? 0;
      return {
        label: entry.label,
        selected: count,
        selectionRate: validResamples ? normalizeNumber(count / validResamples) : Number.NaN,
        meanWeight: validResamples ? normalizeNumber((weightSums.get(modelIndex) ?? 0) / validResamples) : Number.NaN,
      };
    }),
  };
}

function customNonlinearBootstrapArtifacts(bootstrap, request) {
  if (!bootstrap) {
    return [];
  }
  const percent = formatNumber(request.level * 100);
  return [
    ["Bootstrap resamples", formatNumber(bootstrap.resamples)],
    ["Bootstrap valid resamples", formatNumber(bootstrap.validResamples)],
    ["Bootstrap seed", formatNumber(bootstrap.seed)],
    ...(bootstrap.prediction ? [
      ["Bootstrap mean averaged prediction", formatNumber(bootstrap.prediction.mean)],
      [`Bootstrap ${percent}% averaged prediction CI`, `[${formatNumber(bootstrap.prediction.lower)}, ${formatNumber(bootstrap.prediction.upper)}]`],
    ] : []),
  ];
}

function customNonlinearBootstrapExtraTables(bootstrap) {
  if (!bootstrap) {
    return [];
  }
  return [{
    title: "Bootstrap model uncertainty",
    headers: ["Model", "Selected", "Selection rate", "Mean weight"],
    rows: bootstrap.modelRows.map((row) => [
      row.label,
      formatNumber(row.selected),
      formatFiniteNumber(row.selectionRate),
      formatFiniteNumber(row.meanWeight),
    ]),
  }];
}

function buildCustomNonlinearBootstrapGraphs(bootstrap, request) {
  if (!bootstrap) {
    return [];
  }

  const modelPoints = bootstrap.modelRows.map((row, index) => ({
    x: index + 1,
    y: row.selectionRate,
  })).filter((point) => Number.isFinite(point.y));
  const weightPoints = bootstrap.modelRows.map((row, index) => ({
    x: index + 1,
    y: row.meanWeight,
  })).filter((point) => Number.isFinite(point.y));
  const graphs = [];

  if (modelPoints.length || weightPoints.length) {
    graphs.push({
      expression: "Bootstrap custom model uncertainty",
      kind: "regression-diagnostic",
      scatterLabel: "Selection rate",
      xMin: 1,
      xMax: Math.max(1, bootstrap.modelRows.length),
      yMin: 0,
      yMax: 1,
      scatter: modelPoints,
      lines: [
        modelPoints.length ? { label: "Selection rate", points: modelPoints, className: "graph-line-accent" } : null,
        weightPoints.length ? { label: "Mean weight", points: weightPoints, className: "graph-line-muted" } : null,
      ].filter(Boolean),
    });
  }

  if (bootstrap.prediction) {
    const halfWidth = Math.max(0.5, Math.abs(request.prediction) * 0.04);
    graphs.push({
      expression: `Bootstrap ${formatNumber(request.level * 100)}% averaged prediction interval`,
      kind: "regression-diagnostic",
      scatterLabel: "Mean averaged prediction",
      xMin: request.prediction - halfWidth * 1.6,
      xMax: request.prediction + halfWidth * 1.6,
      yMin: bootstrap.prediction.lower,
      yMax: bootstrap.prediction.upper,
      scatter: [{ x: request.prediction, y: bootstrap.prediction.mean }],
      areas: [{
        label: "Bootstrap interval",
        points: [
          { x: request.prediction - halfWidth, y: bootstrap.prediction.lower },
          { x: request.prediction + halfWidth, y: bootstrap.prediction.lower },
          { x: request.prediction + halfWidth, y: bootstrap.prediction.upper },
          { x: request.prediction - halfWidth, y: bootstrap.prediction.upper },
        ],
      }],
      lines: [{
        label: "Mean",
        className: "graph-line-accent",
        points: [
          { x: request.prediction - halfWidth, y: bootstrap.prediction.mean },
          { x: request.prediction + halfWidth, y: bootstrap.prediction.mean },
        ],
      }],
    });
  }

  return graphs;
}

function customNonlinearWeightedPrediction(models, x) {
  const finitePredictions = models
    .map((model) => ({
      weight: model.weight,
      prediction: model.predict(x),
    }))
    .filter((item) => Number.isFinite(item.weight) && Number.isFinite(item.prediction));
  const totalWeight = finitePredictions.reduce((sum, item) => sum + item.weight, 0);
  if (!(totalWeight > 0)) {
    return Number.NaN;
  }
  return normalizeNumber(finitePredictions.reduce((sum, item) =>
    sum + item.weight * item.prediction,
  0) / totalWeight);
}

function customNonlinearModelAveragedPrediction(models, x) {
  const yHat = customNonlinearWeightedPrediction(models, x);
  return Number.isFinite(yHat)
    ? { x, yHat }
    : null;
}

function customNonlinearModelAveragedRows(models, request) {
  return request.x.map((x, index) => {
    const fitted = customNonlinearWeightedPrediction(models, x);
    const residual = Number.isFinite(fitted) ? request.y[index] - fitted : Number.NaN;
    return [
      String(index + 1),
      formatNumber(x),
      formatNumber(request.y[index]),
      formatFiniteNumber(fitted),
      formatFiniteNumber(residual),
    ];
  });
}

function leaveOneOutCustomNonlinearValidation(request) {
  const splits = Array.from({ length: request.y.length }, (_, heldOut) => ({
    train: complementIndices(request.y.length, [heldOut]),
    test: [heldOut],
  }));
  return scoreCustomNonlinearValidationSplits(request, splits);
}

function kFoldCustomNonlinearValidation(request, kFold) {
  const folds = Array.from({ length: kFold }, () => []);
  for (let index = 0; index < request.y.length; index += 1) {
    folds[index % kFold].push(index);
  }
  const splits = folds
    .filter((fold) => fold.length > 0)
    .map((fold) => ({
      train: complementIndices(request.y.length, fold),
      test: fold,
    }));
  return scoreCustomNonlinearValidationSplits(request, splits);
}

function holdoutCustomNonlinearValidation(request, holdoutCount) {
  const test = Array.from(
    { length: holdoutCount },
    (_, index) => request.y.length - holdoutCount + index,
  );
  return scoreCustomNonlinearValidationSplits(request, [
    {
      train: complementIndices(request.y.length, test),
      test,
    },
  ]);
}

function scoreCustomNonlinearValidationSplits(request, splits) {
  const predictions = [];
  const errors = [];

  for (const split of splits) {
    if (split.train.length <= request.parameterNames.length) {
      return emptyValidationScore();
    }
    const trainRequest = {
      ...request,
      prediction: Number.NaN,
      x: split.train.map((index) => request.x[index]),
      y: split.train.map((index) => request.y[index]),
    };
    let fit;
    try {
      fit = fitCustomNonlinearRegression(trainRequest);
    } catch {
      return emptyValidationScore();
    }

    for (const testIndex of split.test) {
      const prediction = evaluateCustomNonlinearFormula(
        request.expression,
        request.variable,
        request.parameterNames,
        fit.parameters,
        request.x[testIndex],
      );
      if (!Number.isFinite(prediction)) {
        return emptyValidationScore();
      }
      const normalizedPrediction = normalizeNumber(prediction);
      predictions.push(normalizedPrediction);
      errors.push(normalizeNumber(request.y[testIndex] - normalizedPrediction));
    }
  }

  if (errors.length === 0) {
    return emptyValidationScore();
  }
  const mse = mean(errors.map((error) => error ** 2));
  const mae = mean(errors.map((error) => Math.abs(error)));
  return {
    predictions,
    errors,
    rmse: normalizeNumber(Math.sqrt(mse)),
    mae: normalizeNumber(mae),
  };
}

function emptyValidationScore() {
  return { predictions: [], errors: [], rmse: Number.NaN, mae: Number.NaN };
}

function fitCustomNonlinearRegression(request) {
  const starts = generateCustomRegressionStarts(request.initial, request.bounds, request.startCount);
  const runs = starts.map((start, index) =>
    runCustomNonlinearRegressionStart(request, start, index + 1),
  );
  const best = [...runs].sort((left, right) =>
    left.sse - right.sse ||
    left.startIndex - right.startIndex,
  )[0];

  if (!best || !Number.isFinite(best.sse)) {
    throw new Error("Custom nonlinear regression produced non-finite predictions for every start.");
  }

  const normalizedParameters = best.parameters.map(normalizeNumber);
  const normalizedFitted = best.fitted.map(normalizeNumber);
  const covariance = customNonlinearRegressionCovariance(request, normalizedParameters, best.sse);
  const scored = scoreNonlinearRegressionFit({
    family: "custom",
    label: "Custom nonlinear",
    equation: `${request.response} = ${request.formula}`,
    transformedEquation: `${request.response} = ${request.formula}`,
    coefficients: normalizedParameters,
    fitted: normalizedFitted,
    parameterCount: request.parameterNames.length,
    status: `fit in ${best.iterations} iterations`,
    predict: (x) => evaluateCustomNonlinearFormula(request.expression, request.variable, request.parameterNames, normalizedParameters, x),
  }, request.y);
  return {
    ...scored,
    parameters: normalizedParameters,
    iterations: best.iterations,
    converged: best.converged,
    damping: normalizeNumber(best.damping),
    gradientNorm: normalizeNumber(best.gradientNorm),
    stepNorm: normalizeNumber(best.stepNorm),
    covariance,
    inference: customNonlinearRegressionInference(request, normalizedParameters, covariance),
    prediction: Number.isFinite(request.prediction)
      ? customNonlinearRegressionPrediction(request, normalizedParameters, covariance, request.prediction)
      : null,
    startCount: starts.length,
    bestStart: best.startIndex,
    trace: best.trace,
    startSummaries: runs.map((run) => ({
      startIndex: run.startIndex,
      initial: run.initial,
      sse: run.sse,
      iterations: run.iterations,
      converged: run.converged,
    })),
  };
}

function runCustomNonlinearRegressionStart(request, initial, startIndex) {
  let parameters = applyCustomParameterBounds([...initial], request.bounds);
  let damping = 1e-3;
  let fitted = evaluateCustomRegressionFitted(request, parameters);
  let bestSse = customRegressionSse(request.y, fitted);
  let converged = false;
  let stepNorm = Number.NaN;
  const trace = [customOptimizerTraceRow(0, bestSse, damping, stepNorm, "start")];

  if (!Number.isFinite(bestSse)) {
    return {
      startIndex,
      initial,
      parameters,
      fitted: [],
      sse: Number.POSITIVE_INFINITY,
      iterations: 0,
      converged: false,
      damping,
      gradientNorm: Number.NaN,
      stepNorm,
      trace,
    };
  }

  let iterations = 0;
  for (let iteration = 1; iteration <= request.maxIterations; iteration += 1) {
    iterations = iteration;
    const jacobian = customRegressionJacobian(request, parameters);
    const residuals = request.y.map((value, index) => value - fitted[index]);
    const normalMatrix = Array.from({ length: parameters.length }, () => Array(parameters.length).fill(0));
    const normalVector = Array(parameters.length).fill(0);

    for (let row = 0; row < request.x.length; row += 1) {
      for (let i = 0; i < parameters.length; i += 1) {
        normalVector[i] += jacobian[row][i] * residuals[row];
        for (let j = 0; j < parameters.length; j += 1) {
          normalMatrix[i][j] += jacobian[row][i] * jacobian[row][j];
        }
      }
    }

    for (let diagonal = 0; diagonal < parameters.length; diagonal += 1) {
      normalMatrix[diagonal][diagonal] += damping * (normalMatrix[diagonal][diagonal] || 1);
    }

    let step;
    try {
      step = solveLinearSystem(normalMatrix, normalVector);
    } catch {
      damping *= 10;
      continue;
    }
    stepNorm = vectorMagnitude(step);

    const candidate = applyCustomParameterBounds(
      parameters.map((value, index) => value + step[index]),
      request.bounds,
    );
    if (candidate.some((value) => !Number.isFinite(value))) {
      damping *= 10;
      trace.push(customOptimizerTraceRow(iteration, bestSse, damping, stepNorm, "no"));
      continue;
    }

    const candidateFitted = evaluateCustomRegressionFitted(request, candidate);
    const candidateSse = customRegressionSse(request.y, candidateFitted);
    if (Number.isFinite(candidateSse) && candidateSse < bestSse) {
      parameters = candidate;
      fitted = candidateFitted;
      if (Math.abs(bestSse - candidateSse) <= request.tolerance * Math.max(1, bestSse)) {
        bestSse = candidateSse;
        converged = true;
        trace.push(customOptimizerTraceRow(iteration, bestSse, damping, stepNorm, "yes"));
        break;
      }
      bestSse = candidateSse;
      damping = Math.max(damping / 3, 1e-8);
      trace.push(customOptimizerTraceRow(iteration, bestSse, damping, stepNorm, "yes"));
    } else {
      damping *= 10;
      trace.push(customOptimizerTraceRow(iteration, bestSse, damping, stepNorm, "no"));
    }
  }

  return {
    startIndex,
    initial,
    parameters,
    fitted,
    sse: bestSse,
    iterations,
    converged,
    damping,
    gradientNorm: customRegressionGradientNorm(request, parameters, fitted),
    stepNorm,
    trace,
  };
}

function customOptimizerTraceRow(iteration, sse, damping, stepNorm, accepted) {
  return {
    iteration,
    sse: Number.isFinite(sse) ? normalizeNumber(sse) : Number.POSITIVE_INFINITY,
    damping: normalizeNumber(damping),
    stepNorm: normalizeNumber(stepNorm),
    accepted,
  };
}

function generateCustomRegressionStarts(initial, bounds, startCount) {
  const starts = [applyCustomParameterBounds(initial, bounds)];
  for (let startIndex = 1; startIndex < startCount; startIndex += 1) {
    starts.push(applyCustomParameterBounds(initial.map((value, parameterIndex) =>
      customRegressionStartValue(value, bounds[parameterIndex], startIndex, parameterIndex),
    ), bounds));
  }
  return starts;
}

function customRegressionStartValue(value, bound, startIndex, parameterIndex) {
  if (Number.isFinite(bound.lower) && Number.isFinite(bound.upper)) {
    const fraction = deterministicFraction(startIndex, parameterIndex);
    return bound.lower + (bound.upper - bound.lower) * fraction;
  }
  const scale = Math.abs(value) + 1;
  const direction = (startIndex + parameterIndex) % 2 === 0 ? 1 : -1;
  const magnitude = 0.5 + 0.25 * startIndex;
  return value + direction * scale * magnitude;
}

function deterministicFraction(startIndex, parameterIndex) {
  const raw = Math.sin((startIndex + 1) * (parameterIndex + 2) * 12.9898) * 43758.5453;
  const fraction = raw - Math.floor(raw);
  return Math.min(0.9, Math.max(0.1, fraction));
}

function customNonlinearExtraTables(fit, request) {
  const traceRows = fit.trace.map((row) => [
    formatNumber(row.iteration),
    formatFiniteNumber(row.sse),
    formatFiniteNumber(row.damping),
    formatFiniteNumber(row.stepNorm),
    row.accepted,
  ]);
  const tables = [{
    title: "Optimizer trace",
    headers: ["Iteration", "SSE", "Damping", "Step norm", "Accepted"],
    rows: traceRows,
  }];
  if (fit.startSummaries.length > 1) {
    tables.push({
      title: "Multi-start summary",
      headers: ["Start", "Initial", "Final SSE", "Iterations", "Converged"],
      rows: fit.startSummaries.map((summary) => [
        formatNumber(summary.startIndex),
        formatCustomParameterVector(summary.initial, request.parameterNames),
        formatFiniteNumber(summary.sse),
        formatNumber(summary.iterations),
        summary.converged ? "yes" : "no",
      ]),
    });
  }
  return tables;
}

function formatCustomParameterVector(values, parameterNames) {
  return parameterNames
    .map((name, index) => `${name}=${formatNumber(values[index])}`)
    .join(", ");
}

function customNonlinearPredictionArtifacts(prediction, percent) {
  return [
    ["Prediction x", formatNumber(prediction.x)],
    ["Predicted y", formatFiniteNumber(prediction.yHat)],
    ["Mean response SE", formatFiniteNumber(prediction.meanStandardError)],
    [`${percent}% mean response CI`, Number.isFinite(prediction.meanLower) ? `[${formatNumber(prediction.meanLower)}, ${formatNumber(prediction.meanUpper)}]` : "undefined"],
    ["Prediction SE", formatFiniteNumber(prediction.predictionStandardError)],
    [`${percent}% prediction interval`, Number.isFinite(prediction.predictionLower) ? `[${formatNumber(prediction.predictionLower)}, ${formatNumber(prediction.predictionUpper)}]` : "undefined"],
  ];
}

function evaluateCustomRegressionFitted(request, parameters) {
  return request.x.map((x) =>
    evaluateCustomNonlinearFormula(request.expression, request.variable, request.parameterNames, parameters, x),
  );
}

function evaluateCustomNonlinearFormula(expression, variable, parameterNames, parameters, x) {
  const values = { [variable]: x };
  parameterNames.forEach((name, index) => {
    values[name] = parameters[index];
  });
  const value = evaluateMath(expression, values);
  return Number.isFinite(value) ? value : Number.NaN;
}

function customRegressionSse(actual, fitted) {
  return fitted.reduce((sum, value, index) => {
    if (!Number.isFinite(value)) {
      return Number.POSITIVE_INFINITY;
    }
    return sum + (actual[index] - value) ** 2;
  }, 0);
}

function customRegressionJacobian(request, parameters) {
  return request.x.map((x) => request.parameterNames.map((_, parameterIndex) => {
    const center = parameters[parameterIndex];
    const step = 1e-5 * (Math.abs(center) + 1);
    const plus = applyCustomParameterBounds(parameters.map((value, index) =>
      index === parameterIndex ? value + step : value,
    ), request.bounds);
    const minus = applyCustomParameterBounds(parameters.map((value, index) =>
      index === parameterIndex ? value - step : value,
    ), request.bounds);
    const plusValue = evaluateCustomNonlinearFormula(request.expression, request.variable, request.parameterNames, plus, x);
    const minusValue = evaluateCustomNonlinearFormula(request.expression, request.variable, request.parameterNames, minus, x);
    const denominator = plus[parameterIndex] - minus[parameterIndex];
    if (!Number.isFinite(plusValue) || !Number.isFinite(minusValue) || Math.abs(denominator) <= EPSILON) {
      return 0;
    }
    return (plusValue - minusValue) / denominator;
  }));
}

function applyCustomParameterBounds(parameters, bounds) {
  return parameters.map((value, index) => {
    const bound = bounds[index];
    return Math.min(bound.upper, Math.max(bound.lower, value));
  });
}

function customRegressionGradientNorm(request, parameters, fitted) {
  const jacobian = customRegressionJacobian(request, parameters);
  const residuals = request.y.map((value, index) => value - fitted[index]);
  const gradient = Array(parameters.length).fill(0);
  for (let row = 0; row < request.x.length; row += 1) {
    for (let column = 0; column < parameters.length; column += 1) {
      gradient[column] += jacobian[row][column] * residuals[row];
    }
  }
  return vectorMagnitude(gradient);
}

function customNonlinearRegressionCovariance(request, parameters, sse) {
  const degreesFreedom = request.y.length - parameters.length;
  if (degreesFreedom <= 0) {
    return {
      covariance: null,
      degreesFreedom,
      mse: Number.NaN,
      critical: Number.NaN,
    };
  }

  const jacobian = customRegressionJacobian(request, parameters);
  const normalMatrix = multiplyMatrices(transposeMatrix(jacobian), jacobian);
  let inverse;
  try {
    inverse = invertMatrixBySolves(normalMatrix);
  } catch {
    inverse = null;
  }
  const mse = sse / degreesFreedom;
  const critical = inverseStudentTCdf((1 + request.level) / 2, degreesFreedom);

  return {
    covariance: inverse ? inverse.map((row) => row.map((value) => normalizeNumber(value * mse))) : null,
    degreesFreedom,
    mse: normalizeNumber(mse),
    critical,
  };
}

function customNonlinearRegressionInference(request, parameters, covarianceInfo) {
  if (!covarianceInfo.covariance) {
    return request.parameterNames.map((name, index) => ({
      label: name,
      coefficient: parameters[index],
      standardError: Number.NaN,
      lower: Number.NaN,
      upper: Number.NaN,
    }));
  }

  return request.parameterNames.map((name, index) => {
    const variance = covarianceInfo.covariance[index][index];
    const standardError = Number.isFinite(variance) ? Math.sqrt(Math.max(0, variance)) : Number.NaN;
    return {
      label: name,
      coefficient: parameters[index],
      standardError: normalizeNumber(standardError),
      lower: normalizeNumber(parameters[index] - covarianceInfo.critical * standardError),
      upper: normalizeNumber(parameters[index] + covarianceInfo.critical * standardError),
    };
  });
}

function customNonlinearRegressionPrediction(request, parameters, covarianceInfo, xValue) {
  const yHat = evaluateCustomNonlinearFormula(request.expression, request.variable, request.parameterNames, parameters, xValue);
  const gradient = customPredictionGradient(request, parameters, xValue);
  const meanVariance = covarianceInfo.covariance
    ? quadraticForm(covarianceInfo.covariance, gradient)
    : Number.NaN;
  const meanStandardError = Number.isFinite(meanVariance)
    ? Math.sqrt(Math.max(0, meanVariance))
    : Number.NaN;
  const predictionStandardError = Number.isFinite(meanStandardError) && Number.isFinite(covarianceInfo.mse)
    ? Math.sqrt(meanStandardError ** 2 + covarianceInfo.mse)
    : Number.NaN;
  const critical = covarianceInfo.critical;
  return {
    x: normalizeNumber(xValue),
    yHat: normalizeNumber(yHat),
    meanStandardError: normalizeNumber(meanStandardError),
    predictionStandardError: normalizeNumber(predictionStandardError),
    meanLower: normalizeNumber(yHat - critical * meanStandardError),
    meanUpper: normalizeNumber(yHat + critical * meanStandardError),
    predictionLower: normalizeNumber(yHat - critical * predictionStandardError),
    predictionUpper: normalizeNumber(yHat + critical * predictionStandardError),
  };
}

function customPredictionGradient(request, parameters, xValue) {
  return request.parameterNames.map((_, parameterIndex) => {
    const center = parameters[parameterIndex];
    const step = 1e-5 * (Math.abs(center) + 1);
    const plus = applyCustomParameterBounds(parameters.map((value, index) =>
      index === parameterIndex ? value + step : value,
    ), request.bounds);
    const minus = applyCustomParameterBounds(parameters.map((value, index) =>
      index === parameterIndex ? value - step : value,
    ), request.bounds);
    const plusValue = evaluateCustomNonlinearFormula(request.expression, request.variable, request.parameterNames, plus, xValue);
    const minusValue = evaluateCustomNonlinearFormula(request.expression, request.variable, request.parameterNames, minus, xValue);
    const denominator = plus[parameterIndex] - minus[parameterIndex];
    if (!Number.isFinite(plusValue) || !Number.isFinite(minusValue) || Math.abs(denominator) <= EPSILON) {
      return 0;
    }
    return (plusValue - minusValue) / denominator;
  });
}

function quadraticForm(matrix, vector) {
  return vector.reduce((sum, leftValue, row) =>
    sum + vector.reduce((inner, rightValue, column) =>
      inner + leftValue * matrix[row][column] * rightValue,
    0),
  0);
}

function invertMatrixBySolves(matrix) {
  const columns = matrix.map((_, column) => {
    const basis = Array(matrix.length).fill(0);
    basis[column] = 1;
    return solveLinearSystem(matrix, basis);
  });
  return transposeMatrix(columns);
}

function fitPolynomialCoefficients(xValues, yValues, degree) {
  const design = polynomialDesignMatrix(xValues, degree);
  const transposed = transposeMatrix(design);
  const normalMatrix = multiplyMatrices(transposed, design);
  const normalVector = multiplyMatrixVector(transposed, yValues);
  return solveLinearSystem(normalMatrix, normalVector).map(normalizeNumber);
}

function polynomialDesignMatrix(xValues, degree) {
  return xValues.map((x) => Array.from({ length: degree + 1 }, (_, power) => x ** power));
}

function polynomialPrediction(coefficients, x) {
  return normalizeNumber(coefficients.reduce((sum, coefficient, power) => sum + coefficient * x ** power, 0));
}

function leaveOneOutPolynomialValidation(xValues, yValues, degree) {
  const splits = Array.from({ length: yValues.length }, (_, heldOut) => ({
    train: complementIndices(yValues.length, [heldOut]),
    test: [heldOut],
  }));
  return scorePolynomialValidationSplits(xValues, yValues, degree, splits);
}

function kFoldPolynomialValidation(xValues, yValues, degree, kFold) {
  const folds = Array.from({ length: kFold }, () => []);
  for (let index = 0; index < yValues.length; index += 1) {
    folds[index % kFold].push(index);
  }
  const splits = folds
    .filter((fold) => fold.length > 0)
    .map((fold) => ({
      train: complementIndices(yValues.length, fold),
      test: fold,
    }));
  return scorePolynomialValidationSplits(xValues, yValues, degree, splits);
}

function holdoutPolynomialValidation(xValues, yValues, degree, holdoutCount) {
  const test = Array.from(
    { length: holdoutCount },
    (_, index) => yValues.length - holdoutCount + index,
  );
  return scorePolynomialValidationSplits(xValues, yValues, degree, [
    {
      train: complementIndices(yValues.length, test),
      test,
    },
  ]);
}

function scorePolynomialValidationSplits(xValues, yValues, degree, splits) {
  const predictions = [];
  const errors = [];

  for (const split of splits) {
    const trainX = split.train.map((index) => xValues[index]);
    const trainY = split.train.map((index) => yValues[index]);
    const distinctTrainX = new Set(trainX.map((x) => formatNumber(x))).size;
    if (trainX.length < degree + 1 || distinctTrainX < degree + 1) {
      return { predictions: [], errors: [], rmse: Number.NaN, mae: Number.NaN };
    }

    try {
      const coefficients = fitPolynomialCoefficients(trainX, trainY, degree);
      for (const testIndex of split.test) {
        const prediction = polynomialPrediction(coefficients, xValues[testIndex]);
        predictions.push(prediction);
        errors.push(normalizeNumber(yValues[testIndex] - prediction));
      }
    } catch {
      return { predictions: [], errors: [], rmse: Number.NaN, mae: Number.NaN };
    }
  }

  if (errors.length === 0) {
    return { predictions: [], errors: [], rmse: Number.NaN, mae: Number.NaN };
  }
  const mse = mean(errors.map((error) => error ** 2));
  const mae = mean(errors.map((error) => Math.abs(error)));
  return {
    predictions,
    errors,
    rmse: normalizeNumber(Math.sqrt(mse)),
    mae: normalizeNumber(mae),
  };
}

function complementIndices(length, excluded) {
  const excludedSet = new Set(excluded);
  return Array.from({ length }, (_, index) => index)
    .filter((index) => !excludedSet.has(index));
}

function pickBestRegressionComparisonModel(models, criterion) {
  return [...models].sort((left, right) =>
    regressionComparisonCriterionValue(left, criterion) - regressionComparisonCriterionValue(right, criterion) ||
    left.bic - right.bic ||
    left.degree - right.degree,
  )[0];
}

function pickBestRegressionComparisonCvModel(models) {
  const candidates = models.filter((model) => Number.isFinite(model.loocvRmse));
  return [...candidates].sort((left, right) =>
    left.loocvRmse - right.loocvRmse ||
    left.loocvMae - right.loocvMae ||
    left.degree - right.degree,
  )[0] ?? null;
}

function pickBestRegressionComparisonMetricModel(models, rmseKey, maeKey) {
  const candidates = models.filter((model) => Number.isFinite(model[rmseKey]));
  return [...candidates].sort((left, right) =>
    left[rmseKey] - right[rmseKey] ||
    left[maeKey] - right[maeKey] ||
    left.degree - right.degree,
  )[0] ?? null;
}

function regressionComparisonCriterionValue(model, criterion) {
  return criterion === "AICc" ? model.aicc : model.aic;
}

function regressionComparisonDetails(request) {
  const validationDetails = [];
  if (request.validation.kFold) {
    validationDetails.push(`${request.validation.kFold}-fold CV`);
  }
  if (request.validation.holdoutCount) {
    validationDetails.push(`${request.validation.holdoutCount}-point holdout`);
  }
  return [
    `${request.x.length} observations`,
    `degrees ${request.degrees.join(", ")}`,
    ...validationDetails,
  ].join(", ");
}

function regressionComparisonTableHeaders(validation) {
  const headers = ["Degree", "Equation", "SSE", "R squared", "Adjusted R^2", "AIC", "AICc", "BIC", "LOOCV RMSE", "LOOCV MAE"];
  if (validation.kFold) {
    headers.push("K-fold RMSE", "K-fold MAE");
  }
  if (validation.holdoutCount) {
    headers.push("Holdout RMSE", "Holdout MAE");
  }
  return headers;
}

function regressionComparisonTableRow(model, validation) {
  const row = [
    formatNumber(model.degree),
    model.equation,
    formatNumber(model.sse),
    formatNumber(model.rSquared),
    formatNumber(model.adjustedRSquared),
    formatNumber(model.aic),
    Number.isFinite(model.aicc) ? formatNumber(model.aicc) : "undefined",
    formatNumber(model.bic),
    formatFiniteNumber(model.loocvRmse),
    formatFiniteNumber(model.loocvMae),
  ];
  if (validation.kFold) {
    row.push(formatFiniteNumber(model.kFoldRmse), formatFiniteNumber(model.kFoldMae));
  }
  if (validation.holdoutCount) {
    row.push(formatFiniteNumber(model.holdoutRmse), formatFiniteNumber(model.holdoutMae));
  }
  return row;
}

function requestedRegressionValidationSteps(models, validation) {
  const steps = [];
  if (validation.kFold) {
    steps.push({
      title: "Run k-fold validation",
      expression: models.map((model) => `degree ${model.degree}: RMSE=${formatFiniteNumber(model.kFoldRmse)}`).join("; "),
      detail: `${validation.kFold}-fold validation assigns observations to deterministic round-robin folds and scores held-out predictions.`,
    });
  }
  if (validation.holdoutCount) {
    steps.push({
      title: "Run holdout validation",
      expression: models.map((model) => `degree ${model.degree}: RMSE=${formatFiniteNumber(model.holdoutRmse)}`).join("; "),
      detail: `The solver trains on the first ${models[0].fitted.length - validation.holdoutCount} observations and tests on the final ${validation.holdoutCount}.`,
    });
  }
  return steps;
}

function requestedRegressionValidationArtifacts(models, validation) {
  const artifacts = [];
  if (validation.kFold) {
    const best = pickBestRegressionComparisonMetricModel(models, "kFoldRmse", "kFoldMae");
    artifacts.push(
      ["K-fold count", formatNumber(validation.kFold)],
      ["K-fold best degree", best ? formatNumber(best.degree) : "undefined"],
      ["K-fold best RMSE", best ? formatNumber(best.kFoldRmse) : "undefined"],
      ["K-fold best MAE", best ? formatNumber(best.kFoldMae) : "undefined"],
    );
  }
  if (validation.holdoutCount) {
    const best = pickBestRegressionComparisonMetricModel(models, "holdoutRmse", "holdoutMae");
    artifacts.push(
      ["Holdout count", formatNumber(validation.holdoutCount)],
      ["Holdout best degree", best ? formatNumber(best.degree) : "undefined"],
      ["Holdout best RMSE", best ? formatNumber(best.holdoutRmse) : "undefined"],
      ["Holdout best MAE", best ? formatNumber(best.holdoutMae) : "undefined"],
    );
  }
  return artifacts;
}

function buildRegressionModelComparisonGraph(models, criterion) {
  const criterionValues = models.map((model) => regressionComparisonCriterionValue(model, criterion));
  const [yMin, yMax] = paddedNumericRange(criterionValues);
  const points = models.map((model) => ({
    x: model.degree,
    y: regressionComparisonCriterionValue(model, criterion),
  }));
  return {
    expression: `${criterion} by polynomial degree`,
    kind: "regression-diagnostic",
    scatterLabel: criterion,
    xMin: Math.min(...models.map((model) => model.degree)),
    xMax: Math.max(...models.map((model) => model.degree)),
    yMin,
    yMax,
    scatter: points,
    lines: [
      {
        label: criterion,
        points,
      },
    ],
  };
}

function buildRegressionCvComparisonGraph(models) {
  return buildRegressionValidationMetricGraph(models, "loocvRmse", "LOOCV RMSE by polynomial degree", "LOOCV RMSE");
}

function buildRequestedRegressionValidationGraphs(models, validation) {
  return [
    validation.kFold
      ? buildRegressionValidationMetricGraph(models, "kFoldRmse", `${validation.kFold}-fold RMSE by polynomial degree`, "K-fold RMSE")
      : null,
    validation.holdoutCount
      ? buildRegressionValidationMetricGraph(models, "holdoutRmse", "Holdout RMSE by polynomial degree", "Holdout RMSE")
      : null,
  ].filter(Boolean);
}

function buildRegressionValidationMetricGraph(models, metricKey, expression, scatterLabel) {
  const points = models
    .filter((model) => Number.isFinite(model[metricKey]))
    .map((model) => ({
      x: model.degree,
      y: model[metricKey],
    }));
  if (points.length === 0) {
    return null;
  }
  const [yMin, yMax] = paddedNumericRange(points.map((point) => point.y));
  return {
    expression,
    kind: "regression-diagnostic",
    scatterLabel,
    xMin: Math.min(...points.map((point) => point.x)),
    xMax: Math.max(...points.map((point) => point.x)),
    yMin,
    yMax,
    scatter: points,
    lines: [
      {
        label: scatterLabel,
        points,
      },
    ],
  };
}

function pickBestNonlinearRegressionModel(models, criterion) {
  return [...models].sort((left, right) =>
    nonlinearRegressionCriterionValue(left, criterion) - nonlinearRegressionCriterionValue(right, criterion) ||
    left.bic - right.bic ||
    left.label.localeCompare(right.label),
  )[0];
}

function nonlinearRegressionCriterionValue(model, criterion) {
  if (criterion === "AICc") return model.aicc;
  if (criterion === "BIC") return model.bic;
  return model.aic;
}

function buildNonlinearRegressionCriterionGraph(models, criterion, expression = `${criterion} by nonlinear regression family`) {
  const points = models.map((model, index) => ({
    x: index + 1,
    y: nonlinearRegressionCriterionValue(model, criterion),
  }));
  const [yMin, yMax] = paddedNumericRange(points.map((point) => point.y));
  return {
    expression,
    kind: "regression-diagnostic",
    scatterLabel: criterion,
    xMin: 1,
    xMax: points.length,
    yMin,
    yMax,
    scatter: points,
    lines: [
      {
        label: criterion,
        points,
      },
    ],
  };
}

function buildNonlinearRegressionFitGraph(xValues, yValues, model) {
  const xMin = Math.min(...xValues);
  const xMax = Math.max(...xValues);
  const samples = Array.from({ length: 80 }, (_, index) => {
    const ratio = index / 79;
    const x = xMin + (xMax - xMin) * ratio;
    return {
      x,
      y: model.predict(x),
    };
  }).filter((point) => Number.isFinite(point.y));
  const scatter = xValues.map((x, index) => ({ x, y: yValues[index] }));
  const allY = [...yValues, ...samples.map((point) => point.y)];
  const [yMin, yMax] = paddedNumericRange(allY);
  return {
    expression: `${model.label} best fit`,
    kind: "scatter-fit",
    scatterLabel: "Data",
    xMin,
    xMax,
    yMin,
    yMax,
    scatter,
    lines: [
      {
        label: model.label,
        points: samples,
      },
    ],
  };
}

function analyzeMultipleRegression(statement) {
  const request = parseMultipleRegressionInput(statement);
  const design = request.y.map((_, row) => [
    1,
    ...request.predictors.map((predictor) => predictor.values[row]),
  ]);
  const transposed = transposeMatrix(design);
  const normalMatrix = multiplyMatrices(transposed, design);
  const normalVector = multiplyMatrixVector(transposed, request.y);
  const coefficients = solveLinearSystem(normalMatrix, normalVector);
  const fitted = design.map((row) => dotProduct(row, coefficients));
  const residuals = request.y.map((value, index) => value - fitted[index]);
  const meanY = mean(request.y);
  const sse = residuals.reduce((sum, value) => sum + value ** 2, 0);
  const tss = request.y.reduce((sum, value) => sum + (value - meanY) ** 2, 0);
  const rSquared = nearlyEqual(tss, 0) ? 1 : 1 - sse / tss;
  const predictorCount = request.predictors.length;
  const degreesFreedom = request.y.length - predictorCount - 1;
  const adjustedRSquared = degreesFreedom > 0
    ? 1 - (1 - rSquared) * (request.y.length - 1) / degreesFreedom
    : Number.NaN;
  const residualStdError = degreesFreedom > 0 ? Math.sqrt(sse / degreesFreedom) : Number.NaN;
  const normalMatrixInverse = degreesFreedom > 0 ? invertMatrix(normalMatrix) : [];
  const coefficientNames = ["Intercept", ...request.predictors.map((predictor) => predictor.name)];
  const inference = degreesFreedom > 0
    ? regressionCoefficientInference(coefficients, normalMatrixInverse, sse / degreesFreedom, degreesFreedom, coefficientNames)
    : [];
  const equation = formatMultipleRegressionEquation(coefficients, request.predictors.map((predictor) => predictor.name));
  const hasPrediction = request.prediction.every(Number.isFinite);
  const prediction = hasPrediction
    ? dotProduct([1, ...request.prediction], coefficients)
    : Number.NaN;
  const tree = {
    kind: "statsRegression",
    children: [
      statsDatasetNode(request.y, [], "Y"),
      ...request.predictors.map((predictor) => statsDatasetNode(predictor.values, [], predictor.name)),
      statsMetricNode("R2", rSquared),
    ],
  };

  return {
    mode: "statistics",
    tree,
    answer: hasPrediction
      ? `${equation}; prediction = ${formatNumber(prediction)}`
      : equation,
    summary: "multiple linear regression",
    details: `${request.y.length} observations, ${predictorCount} predictors`,
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read response and predictors",
        expression: `n = ${request.y.length}, predictors = ${request.predictors.map((predictor) => predictor.name).join(", ")}`,
        detail: "Multiple regression models one response using several predictor columns.",
      },
      {
        title: "Build design matrix",
        expression: `${request.y.length} x ${predictorCount + 1}`,
        detail: "The first design column is the intercept; the remaining columns are predictors.",
      },
      {
        title: "Solve normal equations",
        expression: equation,
        detail: "Least squares solves (X'X)b = X'y for the coefficient vector.",
      },
      {
        title: "Measure fit",
        expression: `R^2 = ${formatNumber(rSquared)}, SSE = ${formatNumber(sse)}`,
        detail: "R squared measures how much response variation the model explains.",
      },
      ...(inference.length
        ? [{
            title: "Infer coefficient uncertainty",
            expression: `df = ${degreesFreedom}, ${inference.slice(1).map((item) => `${item.label} p=${formatNumber(item.pValue)}`).join(", ")}`,
            detail: "The residual variance and inverse of X'X produce standard errors, t tests, and coefficient confidence intervals.",
          }]
        : []),
      ...(hasPrediction
        ? [{
            title: "Predict new response",
            expression: `prediction = ${formatNumber(prediction)}`,
            detail: "The new predictor values are plugged into the fitted linear model.",
          }]
        : []),
    ],
    table: {
      headers: ["Obs", "Actual", "Fitted", "Residual"],
      rows: request.y.map((value, index) => [
        String(index + 1),
        formatNumber(value),
        formatNumber(fitted[index]),
        formatNumber(residuals[index]),
      ]),
    },
    artifacts: [
      ["Equation", equation],
      ["Intercept", formatNumber(coefficients[0])],
      ...request.predictors.map((predictor, index) => [`Coefficient ${predictor.name}`, formatNumber(coefficients[index + 1])]),
      ["SSE", formatNumber(sse)],
      ["R squared", formatNumber(rSquared)],
      ["Adjusted R squared", Number.isFinite(adjustedRSquared) ? formatNumber(adjustedRSquared) : "undefined"],
      ["Residual standard error", Number.isFinite(residualStdError) ? formatNumber(residualStdError) : "undefined"],
      ...regressionInferenceArtifacts(inference),
      ...(hasPrediction ? [["Prediction", formatNumber(prediction)]] : []),
    ],
  };
}

function analyzeRegressionDiagnostics(statement) {
  const request = parseRegressionDiagnosticsInput(statement);
  const result = fitOlsDiagnostics(request.y, request.predictors);
  const predictorNames = request.predictors.map((predictor) => predictor.name);
  const largestCook = Math.max(...result.cooksDistances);
  const largestLeverage = Math.max(...result.leverages);
  const maxAbsStandardizedResidual = Math.max(...result.standardizedResiduals.map(Math.abs));
  const cookThreshold = 4 / result.observationCount;
  const leverageThreshold = 2 * result.parameterCount / result.observationCount;
  const influentialCount = result.cooksDistances.filter((value) => value > cookThreshold).length;
  const highLeverageCount = result.leverages.filter((value) => value > leverageThreshold).length;
  const bpDecision = result.breuschPagan.pValue < 0.05
    ? "heteroscedasticity flagged"
    : "no strong heteroscedasticity signal";
  const jbDecision = result.jarqueBera.pValue < 0.05
    ? "residual non-normality flagged"
    : "no strong residual non-normality signal";
  const autocorrelationNote = Number.isFinite(result.durbinWatson)
    ? result.durbinWatson < 1.5
      ? "positive autocorrelation signal"
      : result.durbinWatson > 2.5
        ? "negative autocorrelation signal"
        : "no strong autocorrelation signal"
    : "undefined autocorrelation diagnostic";

  return {
    mode: "statistics",
    tree: {
      kind: "statsRegression",
      label: "REG DIAG",
      children: [
        statsDatasetNode(request.y, [], "Y"),
        ...request.predictors.map((predictor) => statsDatasetNode(predictor.values, [], predictor.name)),
        statsMetricNode("R2", result.rSquared),
        statsMetricNode("DW", result.durbinWatson),
        statsMetricNode("BP", result.breuschPagan.statistic),
        statsMetricNode("COOK", largestCook),
      ],
    },
    answer: `R^2 = ${formatNumber(result.rSquared)}, DW = ${formatNumber(result.durbinWatson)}, BP p = ${formatNumber(result.breuschPagan.pValue)}`,
    summary: "regression diagnostics",
    details: `${result.observationCount} observations, ${predictorNames.length} predictors`,
    variables: [],
    metrics: treeMetrics(statsDatasetNode(request.y)),
    steps: [
      {
        title: "Fit least-squares model",
        expression: result.equation,
        detail: "Diagnostics start from the same ordinary least-squares fit used by regression mode.",
      },
      {
        title: "Analyze residual scale",
        expression: `SSE = ${formatNumber(result.sse)}, RSE = ${formatNumber(result.residualStandardError)}`,
        detail: "Residual standard error measures typical vertical prediction error after accounting for model size.",
      },
      {
        title: "Check residual autocorrelation",
        expression: `Durbin-Watson = ${formatNumber(result.durbinWatson)}`,
        detail: "Values near 2 suggest little first-order residual autocorrelation.",
      },
      {
        title: "Check heteroscedasticity",
        expression: `Breusch-Pagan LM = ${formatNumber(result.breuschPagan.statistic)}, p = ${formatNumber(result.breuschPagan.pValue)}`,
        detail: "The Breusch-Pagan diagnostic regresses squared residuals on the predictors.",
      },
      {
        title: "Check residual normality",
        expression: `JB = ${formatNumber(result.jarqueBera.statistic)}, p = ${formatNumber(result.jarqueBera.pValue)}`,
        detail: "The residual Jarque-Bera diagnostic summarizes skewness and tail weight.",
      },
      {
        title: "Find influential observations",
        expression: `max Cook's D = ${formatNumber(largestCook)}, max leverage = ${formatNumber(largestLeverage)}`,
        detail: "Cook's distance and leverage identify observations that can strongly affect the fitted model.",
      },
    ],
    table: {
      headers: ["Obs", "Actual", "Fitted", "Residual", "Std residual", "Leverage", "Cook's D"],
      rows: request.y.map((value, index) => [
        String(index + 1),
        formatNumber(value),
        formatNumber(result.fitted[index]),
        formatNumber(result.residuals[index]),
        formatNumber(result.standardizedResiduals[index]),
        formatNumber(result.leverages[index]),
        formatNumber(result.cooksDistances[index]),
      ]),
    },
    artifacts: [
      ["Equation", result.equation],
      ["SSE", formatNumber(result.sse)],
      ["R squared", formatNumber(result.rSquared)],
      ["Adjusted R squared", formatNumber(result.adjustedRSquared)],
      ["Residual standard error", formatNumber(result.residualStandardError)],
      ["Degrees of freedom", formatNumber(result.degreesFreedom)],
      ["Durbin-Watson", formatNumber(result.durbinWatson)],
      ["Autocorrelation note", autocorrelationNote],
      ["Breusch-Pagan statistic", formatNumber(result.breuschPagan.statistic)],
      ["Breusch-Pagan p-value", formatNumber(result.breuschPagan.pValue)],
      ["Breusch-Pagan note", bpDecision],
      ["Residual JB statistic", formatNumber(result.jarqueBera.statistic)],
      ["Residual JB p-value", formatNumber(result.jarqueBera.pValue)],
      ["Residual normality note", jbDecision],
      ["Max standardized residual", formatNumber(maxAbsStandardizedResidual)],
      ["Max leverage", formatNumber(largestLeverage)],
      ["High leverage count", formatNumber(highLeverageCount)],
      ["Max Cook's D", formatNumber(largestCook)],
      ["Influential count", formatNumber(influentialCount)],
      ["Cook's D threshold", formatNumber(cookThreshold)],
      ["Leverage threshold", formatNumber(leverageThreshold)],
    ],
    graphs: buildRegressionDiagnosticGraphs(request.y, result, {
      cookThreshold,
      leverageThreshold,
    }),
  };
}

function buildRegressionDiagnosticGraphs(actualValues, result, thresholds) {
  return [
    buildActualVsFittedGraph(actualValues, result.fitted),
    buildResidualsVsFittedGraph(result.fitted, result.residuals),
    buildInfluenceDiagnosticGraph(result.leverages, result.cooksDistances, thresholds),
  ];
}

function buildActualVsFittedGraph(actualValues, fittedValues) {
  const [minValue, maxValue] = paddedNumericRange([...actualValues, ...fittedValues]);
  return {
    expression: "Actual vs fitted",
    kind: "regression-diagnostic",
    scatterLabel: "Observations",
    xMin: minValue,
    xMax: maxValue,
    yMin: minValue,
    yMax: maxValue,
    scatter: fittedValues.map((value, index) => ({
      x: normalizeNumber(value),
      y: normalizeNumber(actualValues[index]),
    })),
    lines: [
      {
        label: "perfect fit",
        className: "graph-line-muted",
        points: [
          { x: minValue, y: minValue },
          { x: maxValue, y: maxValue },
        ],
      },
    ],
  };
}

function buildResidualsVsFittedGraph(fittedValues, residuals) {
  const [xMin, xMax] = paddedNumericRange(fittedValues);
  const [yMin, yMax] = paddedNumericRange([...residuals, 0]);
  return {
    expression: "Residuals vs fitted",
    kind: "regression-diagnostic",
    scatterLabel: "Residuals",
    xMin,
    xMax,
    yMin,
    yMax,
    scatter: fittedValues.map((value, index) => ({
      x: normalizeNumber(value),
      y: normalizeNumber(residuals[index]),
    })),
    lines: [
      {
        label: "zero residual",
        className: "graph-line-muted",
        points: [
          { x: xMin, y: 0 },
          { x: xMax, y: 0 },
        ],
      },
    ],
  };
}

function buildInfluenceDiagnosticGraph(leverages, cooksDistances, thresholds) {
  const xMax = normalizeNumber(Math.max(...leverages, thresholds.leverageThreshold, EPSILON) * 1.2);
  const yMax = normalizeNumber(Math.max(...cooksDistances, thresholds.cookThreshold, EPSILON) * 1.2);
  return {
    expression: "Leverage vs Cook's D",
    kind: "regression-diagnostic",
    scatterLabel: "Influence",
    xMin: 0,
    xMax,
    yMin: 0,
    yMax,
    scatter: leverages.map((value, index) => ({
      x: normalizeNumber(value),
      y: normalizeNumber(cooksDistances[index]),
    })),
    lines: [
      {
        label: "Cook's D threshold",
        className: "graph-line-accent",
        points: [
          { x: 0, y: thresholds.cookThreshold },
          { x: xMax, y: thresholds.cookThreshold },
        ],
      },
      {
        label: "leverage threshold",
        className: "graph-line-muted",
        points: [
          { x: thresholds.leverageThreshold, y: 0 },
          { x: thresholds.leverageThreshold, y: yMax },
        ],
      },
    ],
  };
}

function paddedNumericRange(values) {
  const finite = values.filter(Number.isFinite);
  const minimum = Math.min(...finite);
  const maximum = Math.max(...finite);
  if (nearlyEqual(minimum, maximum)) {
    const pad = Math.max(1, Math.abs(minimum) * 0.1);
    return [normalizeNumber(minimum - pad), normalizeNumber(maximum + pad)];
  }
  const pad = (maximum - minimum) * 0.08;
  return [normalizeNumber(minimum - pad), normalizeNumber(maximum + pad)];
}

function fitOlsDiagnostics(yValues, predictors) {
  const predictorNames = predictors.map((predictor) => predictor.name);
  const design = yValues.map((_, row) => [
    1,
    ...predictors.map((predictor) => predictor.values[row]),
  ]);
  const transposed = transposeMatrix(design);
  const normalMatrix = multiplyMatrices(transposed, design);
  const normalMatrixInverse = invertMatrix(normalMatrix);
  const normalVector = multiplyMatrixVector(transposed, yValues);
  const coefficients = solveLinearSystem(normalMatrix, normalVector);
  const fitted = design.map((row) => dotProduct(row, coefficients));
  const residuals = yValues.map((value, index) => value - fitted[index]);
  const observationCount = yValues.length;
  const parameterCount = predictors.length + 1;
  const degreesFreedom = observationCount - parameterCount;
  if (!(degreesFreedom > 0)) {
    throw new Error("Regression diagnostics need more observations than model parameters.");
  }
  const sse = residuals.reduce((sum, value) => sum + value ** 2, 0);
  if (!(sse > EPSILON)) {
    throw new Error("Regression diagnostics need nonzero residual variation.");
  }
  const mse = sse / degreesFreedom;
  const residualStandardError = Math.sqrt(mse);
  const meanY = mean(yValues);
  const tss = yValues.reduce((sum, value) => sum + (value - meanY) ** 2, 0);
  const rSquared = nearlyEqual(tss, 0) ? 1 : 1 - sse / tss;
  const adjustedRSquared = 1 - (1 - rSquared) * (observationCount - 1) / degreesFreedom;
  const leverages = design.map((row) => dotProduct(row, multiplyMatrixVector(normalMatrixInverse, row)));
  const standardizedResiduals = residuals.map((residual, index) =>
    residual / (residualStandardError * Math.sqrt(Math.max(EPSILON, 1 - leverages[index]))),
  );
  const cooksDistances = residuals.map((residual, index) =>
    ((residual ** 2) / (parameterCount * mse)) *
    (leverages[index] / Math.max(EPSILON, (1 - leverages[index]) ** 2)),
  );
  const durbinWatsonNumerator = residuals.slice(1).reduce((sum, residual, index) =>
    sum + (residual - residuals[index]) ** 2,
  0);
  const durbinWatson = durbinWatsonNumerator / sse;
  const jarqueBera = jarqueBeraNormalityTest(residuals);
  const breuschPagan = breuschPaganDiagnostic(residuals, predictors, normalMatrix, transposed);

  return {
    observationCount,
    parameterCount,
    degreesFreedom,
    coefficients: coefficients.map(normalizeNumber),
    fitted: fitted.map(normalizeNumber),
    residuals: residuals.map(normalizeNumber),
    sse: normalizeNumber(sse),
    rSquared: normalizeNumber(rSquared),
    adjustedRSquared: normalizeNumber(adjustedRSquared),
    residualStandardError: normalizeNumber(residualStandardError),
    leverages: leverages.map(normalizeNumber),
    standardizedResiduals: standardizedResiduals.map(normalizeNumber),
    cooksDistances: cooksDistances.map(normalizeNumber),
    durbinWatson: normalizeNumber(durbinWatson),
    jarqueBera,
    breuschPagan,
    equation: formatMultipleRegressionEquation(coefficients, predictorNames),
  };
}

function fitLinearModelFromDesign(yValues, design) {
  const transposed = transposeMatrix(design);
  const normalMatrix = multiplyMatrices(transposed, design);
  const normalMatrixInverse = invertMatrix(normalMatrix);
  const normalVector = multiplyMatrixVector(transposed, yValues);
  const coefficients = solveLinearSystem(normalMatrix, normalVector);
  const fitted = design.map((row) => dotProduct(row, coefficients));
  const residuals = yValues.map((value, index) => value - fitted[index]);
  const degreesFreedom = yValues.length - coefficients.length;
  if (!(degreesFreedom > 0)) {
    throw new Error("Linear model needs more observations than model parameters.");
  }
  const sse = residuals.reduce((sum, value) => sum + value ** 2, 0);
  if (!(sse > EPSILON)) {
    throw new Error("Linear model needs nonzero residual variation.");
  }

  return {
    coefficients: coefficients.map(normalizeNumber),
    fitted: fitted.map(normalizeNumber),
    residuals: residuals.map(normalizeNumber),
    sse: normalizeNumber(sse),
    mse: normalizeNumber(sse / degreesFreedom),
    degreesFreedom,
    normalMatrixInverse,
  };
}

function breuschPaganDiagnostic(residuals, predictors, normalMatrix, transposedDesign) {
  const squaredResiduals = residuals.map((value) => value ** 2);
  const meanSquaredResidual = mean(squaredResiduals);
  const tss = squaredResiduals.reduce((sum, value) => sum + (value - meanSquaredResidual) ** 2, 0);
  if (!(tss > EPSILON)) {
    return {
      statistic: Number.NaN,
      pValue: Number.NaN,
      rSquared: Number.NaN,
    };
  }
  const auxVector = multiplyMatrixVector(transposedDesign, squaredResiduals);
  const auxCoefficients = solveLinearSystem(normalMatrix, auxVector);
  const fitted = residuals.map((_, row) =>
    auxCoefficients[0] + predictors.reduce((sum, predictor, index) =>
      sum + auxCoefficients[index + 1] * predictor.values[row],
    0),
  );
  const sse = squaredResiduals.reduce((sum, value, index) => sum + (value - fitted[index]) ** 2, 0);
  const rSquared = Math.max(0, Math.min(1, 1 - sse / tss));
  const statistic = residuals.length * rSquared;
  const pValue = chiSquareRightTailApprox(statistic, predictors.length);
  return {
    statistic: normalizeNumber(statistic),
    pValue: normalizeNumber(pValue),
    rSquared: normalizeNumber(rSquared),
  };
}

function analyzeRidgeRegression(statement) {
  const request = parseRidgeRegressionInput(statement);
  const design = request.y.map((_, row) => [
    1,
    ...request.predictors.map((predictor) => predictor.values[row]),
  ]);
  const transposed = transposeMatrix(design);
  const normalMatrix = multiplyMatrices(transposed, design);
  const penalizedMatrix = addRidgePenalty(normalMatrix, request.lambda);
  const normalVector = multiplyMatrixVector(transposed, request.y);
  const coefficients = solveLinearSystem(penalizedMatrix, normalVector);
  const fitted = design.map((row) => dotProduct(row, coefficients));
  const residuals = request.y.map((value, index) => value - fitted[index]);
  const meanY = mean(request.y);
  const rss = residuals.reduce((sum, value) => sum + value ** 2, 0);
  const tss = request.y.reduce((sum, value) => sum + (value - meanY) ** 2, 0);
  const rSquared = nearlyEqual(tss, 0) ? 1 : 1 - rss / tss;
  const penalty = request.lambda * coefficients.slice(1).reduce((sum, value) => sum + value ** 2, 0);
  const objective = rss + penalty;
  const predictorNames = request.predictors.map((predictor) => predictor.name);
  const equation = formatMultipleRegressionEquation(coefficients, predictorNames);
  const hasPrediction = request.prediction.every(Number.isFinite);
  const prediction = hasPrediction
    ? dotProduct([1, ...request.prediction], coefficients)
    : Number.NaN;
  const tree = {
    kind: "statsRegression",
    label: "RIDGE",
    children: [
      statsDatasetNode(request.y, [], "Y"),
      ...request.predictors.map((predictor) => statsDatasetNode(predictor.values, [], predictor.name)),
      statsMetricNode("lambda", request.lambda),
      statsMetricNode("RSS", rss),
    ],
  };

  return {
    mode: "statistics",
    tree,
    answer: hasPrediction
      ? `${equation}; prediction = ${formatNumber(prediction)}`
      : equation,
    summary: "ridge regression",
    details: `${request.y.length} observations, ${request.predictors.length} predictors, lambda = ${formatNumber(request.lambda)}`,
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read response, predictors, and penalty",
        expression: `lambda = ${formatNumber(request.lambda)}, predictors = ${predictorNames.join(", ")}`,
        detail: "Ridge regression fits a linear model while shrinking predictor coefficients.",
      },
      {
        title: "Build penalized normal equations",
        expression: "(X'X + lambda I*)b = X'y",
        detail: "The penalty matrix leaves the intercept unpenalized and adds lambda to predictor diagonal entries.",
      },
      {
        title: "Solve ridge system",
        expression: equation,
        detail: "The coefficients minimize residual squared error plus the coefficient penalty.",
      },
      {
        title: "Measure penalized fit",
        expression: `RSS = ${formatNumber(rss)}, penalty = ${formatNumber(penalty)}, objective = ${formatNumber(objective)}`,
        detail: "The objective balances fit to the data against coefficient size.",
      },
      ...(hasPrediction
        ? [{
            title: "Predict new response",
            expression: `prediction = ${formatNumber(prediction)}`,
            detail: "The requested predictor values are plugged into the regularized linear model.",
          }]
        : []),
    ],
    table: {
      headers: ["Obs", "Actual", "Fitted", "Residual"],
      rows: request.y.map((value, index) => [
        String(index + 1),
        formatNumber(value),
        formatNumber(fitted[index]),
        formatNumber(residuals[index]),
      ]),
    },
    artifacts: [
      ["Equation", equation],
      ["Lambda", formatNumber(request.lambda)],
      ["Intercept", formatNumber(coefficients[0])],
      ...request.predictors.map((predictor, index) => [`Coefficient ${predictor.name}`, formatNumber(coefficients[index + 1])]),
      ["RSS", formatNumber(rss)],
      ["R squared", formatNumber(rSquared)],
      ["Penalty", formatNumber(penalty)],
      ["Ridge objective", formatNumber(objective)],
      ...(hasPrediction ? [["Prediction", formatNumber(prediction)]] : []),
    ],
  };
}

function analyzeLassoRegression(statement) {
  const request = parseLassoRegressionInput(statement);
  const fit = fitLassoRegression(request.y, request.predictors, request.lambda);
  const coefficients = [fit.intercept, ...fit.coefficients];
  const predictorNames = request.predictors.map((predictor) => predictor.name);
  const design = request.y.map((_, row) => [
    1,
    ...request.predictors.map((predictor) => predictor.values[row]),
  ]);
  const fitted = design.map((row) => dotProduct(row, coefficients));
  const residuals = request.y.map((value, index) => value - fitted[index]);
  const meanY = mean(request.y);
  const rss = residuals.reduce((sum, value) => sum + value ** 2, 0);
  const tss = request.y.reduce((sum, value) => sum + (value - meanY) ** 2, 0);
  const rSquared = nearlyEqual(tss, 0) ? 1 : 1 - rss / tss;
  const l1Penalty = request.lambda * fit.standardizedCoefficients.reduce((sum, value) => sum + Math.abs(value), 0);
  const objective = 0.5 * rss + l1Penalty;
  const activePredictors = fit.coefficients.filter((value) => Math.abs(value) > 1e-7).length;
  const equation = formatMultipleRegressionEquation(coefficients, predictorNames);
  const hasPrediction = request.prediction.every(Number.isFinite);
  const prediction = hasPrediction
    ? dotProduct([1, ...request.prediction], coefficients)
    : Number.NaN;
  const tree = {
    kind: "statsRegression",
    label: "LASSO",
    children: [
      statsDatasetNode(request.y, [], "Y"),
      ...request.predictors.map((predictor) => statsDatasetNode(predictor.values, [], predictor.name)),
      statsMetricNode("lambda", request.lambda),
      statsMetricNode("active", activePredictors),
    ],
  };

  return {
    mode: "statistics",
    tree,
    answer: hasPrediction
      ? `${equation}; prediction = ${formatNumber(prediction)}`
      : equation,
    summary: "LASSO regression",
    details: `${request.y.length} observations, ${request.predictors.length} predictors, ${activePredictors} active predictors`,
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read response, predictors, and penalty",
        expression: `lambda = ${formatNumber(request.lambda)}, predictors = ${predictorNames.join(", ")}`,
        detail: "LASSO regression fits a linear model while allowing coefficients to shrink exactly to zero.",
      },
      {
        title: "Standardize predictors",
        expression: "center y, center and scale each predictor",
        detail: "Standardization makes the L1 penalty comparable across predictors with different scales.",
      },
      {
        title: "Run coordinate descent",
        expression: `${fit.iterations} iterations, ${fit.converged ? "converged" : "stopped"}`,
        detail: "Each coordinate update applies soft-thresholding to decide whether a predictor stays active.",
      },
      {
        title: "Measure sparse fit",
        expression: `RSS = ${formatNumber(rss)}, L1 penalty = ${formatNumber(l1Penalty)}, active = ${activePredictors}`,
        detail: "The objective balances residual error against the absolute size of standardized coefficients.",
      },
      ...(hasPrediction
        ? [{
            title: "Predict new response",
            expression: `prediction = ${formatNumber(prediction)}`,
            detail: "The requested predictor values are plugged into the sparse linear model.",
          }]
        : []),
    ],
    table: {
      headers: ["Obs", "Actual", "Fitted", "Residual"],
      rows: request.y.map((value, index) => [
        String(index + 1),
        formatNumber(value),
        formatNumber(fitted[index]),
        formatNumber(residuals[index]),
      ]),
    },
    artifacts: [
      ["Equation", equation],
      ["Lambda", formatNumber(request.lambda)],
      ["Intercept", formatNumber(fit.intercept)],
      ...request.predictors.map((predictor, index) => [`Coefficient ${predictor.name}`, formatNumber(fit.coefficients[index])]),
      ["Active predictors", formatNumber(activePredictors)],
      ["RSS", formatNumber(rss)],
      ["R squared", formatNumber(rSquared)],
      ["L1 penalty", formatNumber(l1Penalty)],
      ["LASSO objective", formatNumber(objective)],
      ["Iterations", formatNumber(fit.iterations)],
      ["Converged", fit.converged ? "yes" : "no"],
      ...(hasPrediction ? [["Prediction", formatNumber(prediction)]] : []),
    ],
  };
}

function analyzeLogisticRegression(statement) {
  const request = parseLogisticRegressionInput(statement);
  const design = request.y.map((_, row) => [
    1,
    ...request.predictors.map((predictor) => predictor.values[row]),
  ]);
  const fit = fitLogisticRegression(design, request.y);
  const probabilities = fit.probabilities;
  const predictedClasses = probabilities.map((probability) => (probability >= 0.5 ? 1 : 0));
  const correct = predictedClasses.filter((value, index) => value === request.y[index]).length;
  const accuracy = correct / request.y.length;
  const nullProbability = mean(request.y);
  const nullLogLikelihood = request.y.reduce((sum, value) => {
    const probability = clampLogLikelihoodProbability(value === 1 ? nullProbability : 1 - nullProbability);
    return sum + Math.log(probability);
  }, 0);
  const deviance = -2 * fit.logLikelihood;
  const mcfaddenR2 = nullLogLikelihood < 0 ? 1 - fit.logLikelihood / nullLogLikelihood : Number.NaN;
  const equation = formatLogisticRegressionEquation(fit.coefficients, request.predictors.map((predictor) => predictor.name));
  const hasPrediction = request.prediction.every(Number.isFinite);
  const predictedProbability = hasPrediction
    ? logisticSigmoid(dotProduct([1, ...request.prediction], fit.coefficients))
    : Number.NaN;
  const tree = {
    kind: "statsRegression",
    label: "LOGISTIC",
    children: [
      statsDatasetNode(request.y, [], "Y"),
      ...request.predictors.map((predictor) => statsDatasetNode(predictor.values, [], predictor.name)),
      statsMetricNode("LL", fit.logLikelihood),
      statsMetricNode("ACC", accuracy),
    ],
  };

  return {
    mode: "statistics",
    tree,
    answer: hasPrediction
      ? `${equation}; P(y=1) = ${formatNumber(predictedProbability)}`
      : equation,
    summary: "logistic regression",
    details: `${request.y.length} observations, ${request.predictors.length} predictors`,
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read binary response and predictors",
        expression: `n = ${request.y.length}, predictors = ${request.predictors.map((predictor) => predictor.name).join(", ")}`,
        detail: "Logistic regression models a 0/1 response with probabilities instead of direct numeric predictions.",
      },
      {
        title: "Build logit model",
        expression: "logit(p) = b0 + b1x1 + ...",
        detail: "The logit link converts probabilities into a linear predictor.",
      },
      {
        title: "Fit by Newton iterations",
        expression: `${fit.iterations} iterations, ${fit.converged ? "converged" : "stopped"}`,
        detail: "Each iteration updates the coefficient vector using the likelihood gradient and information matrix.",
      },
      {
        title: "Measure classification fit",
        expression: `log likelihood = ${formatNumber(fit.logLikelihood)}, accuracy = ${formatNumber(accuracy)}`,
        detail: "The fitted probabilities are converted into classes using a 0.5 threshold.",
      },
      ...(hasPrediction
        ? [{
            title: "Predict probability",
            expression: `P(y=1) = ${formatNumber(predictedProbability)}`,
            detail: "The requested predictor values are plugged into the fitted logit model.",
          }]
        : []),
    ],
    table: {
      headers: ["Obs", "Actual", "P(y=1)", "Predicted"],
      rows: request.y.map((value, index) => [
        String(index + 1),
        formatNumber(value),
        formatNumber(probabilities[index]),
        formatNumber(predictedClasses[index]),
      ]),
    },
    artifacts: [
      ["Equation", equation],
      ["Intercept", formatNumber(fit.coefficients[0])],
      ...request.predictors.map((predictor, index) => [`Coefficient ${predictor.name}`, formatNumber(fit.coefficients[index + 1])]),
      ["Log likelihood", formatNumber(fit.logLikelihood)],
      ["Deviance", formatNumber(deviance)],
      ["McFadden R squared", Number.isFinite(mcfaddenR2) ? formatNumber(mcfaddenR2) : "undefined"],
      ["Accuracy", formatNumber(accuracy)],
      ["Converged", fit.converged ? "yes" : "no"],
      ...(hasPrediction ? [["Predicted probability", formatNumber(predictedProbability)]] : []),
    ],
  };
}

function analyzeNaiveBayes(statement) {
  const request = parseNaiveBayesInput(statement);
  const model = fitGaussianNaiveBayes(request.classes, request.predictors);
  const hasPrediction = request.prediction.every(Number.isFinite);
  const prediction = hasPrediction
    ? predictGaussianNaiveBayes(model, request.prediction)
    : null;
  const fitted = request.classes.map((_, row) =>
    predictGaussianNaiveBayes(model, request.predictors.map((predictor) => predictor.values[row])),
  );
  const accuracy = fitted.filter((item, index) => item.classValue === request.classes[index]).length / request.classes.length;
  const classLabels = model.classes.map((classInfo) => formatNumber(classInfo.value)).join(", ");
  const tree = {
    kind: "statsRegression",
    label: "NAIVE BAYES",
    children: [
      statsDatasetNode(request.classes, [], "CLASS"),
      ...request.predictors.map((predictor) => statsDatasetNode(predictor.values, [], predictor.name)),
      statsMetricNode("ACC", accuracy),
    ],
  };

  return {
    mode: "statistics",
    tree,
    answer: prediction
      ? `predicted class = ${formatNumber(prediction.classValue)}`
      : `classes = ${classLabels}`,
    summary: "Gaussian Naive Bayes",
    details: `${request.classes.length} observations, ${model.classes.length} classes, ${request.predictors.length} features`,
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read classes and numeric features",
        expression: `classes = ${classLabels}, features = ${request.predictors.map((predictor) => predictor.name).join(", ")}`,
        detail: "Gaussian Naive Bayes learns one normal distribution per class and feature.",
      },
      {
        title: "Estimate priors and likelihoods",
        expression: model.classes
          .map((classInfo) => `P(${formatNumber(classInfo.value)})=${formatNumber(classInfo.prior)}`)
          .join(", "),
        detail: "Class priors come from class frequencies, and feature likelihoods use class-specific means and variances.",
      },
      {
        title: "Evaluate training predictions",
        expression: `accuracy = ${formatNumber(accuracy)}`,
        detail: "Each training row is classified by the largest posterior probability.",
      },
      ...(prediction
        ? [{
            title: "Predict class posterior",
            expression: prediction.posteriors
              .map((posterior) => `P(${formatNumber(posterior.classValue)}|x)=${formatNumber(posterior.probability)}`)
              .join(", "),
            detail: "Log likelihoods are normalized into posterior probabilities to avoid underflow.",
          }]
        : []),
    ],
    table: {
      headers: ["Obs", "Actual", "Predicted", "Confidence"],
      rows: request.classes.map((value, index) => [
        String(index + 1),
        formatNumber(value),
        formatNumber(fitted[index].classValue),
        formatNumber(fitted[index].probability),
      ]),
    },
    artifacts: [
      ["Classes", classLabels],
      ["Training accuracy", formatNumber(accuracy)],
      ...model.classes.map((classInfo) => [`Prior class ${formatNumber(classInfo.value)}`, formatNumber(classInfo.prior)]),
      ...model.classes.flatMap((classInfo) =>
        classInfo.features.flatMap((feature, index) => [
          [`Class ${formatNumber(classInfo.value)} ${request.predictors[index].name} mean`, formatNumber(feature.mean)],
          [`Class ${formatNumber(classInfo.value)} ${request.predictors[index].name} variance`, formatNumber(feature.variance)],
        ]),
      ),
      ...(prediction
        ? [
            ["Predicted class", formatNumber(prediction.classValue)],
            ["Posterior probability", formatNumber(prediction.probability)],
            ...prediction.posteriors.map((posterior) => [
              `Posterior class ${formatNumber(posterior.classValue)}`,
              formatNumber(posterior.probability),
            ]),
          ]
        : []),
    ],
  };
}

