function analyzeRocAnalysis(statement) {
  const request = parseRocInput(statement);
  const result = computeRocAnalysis(request.labels, request.scores, request.threshold);
  const selected = result.selected;
  const tree = statsDatasetNode(request.scores, [
    statsMetricNode("AUC", result.auc),
    statsMetricNode("BEST", result.best.threshold),
    statsMetricNode("TPR", selected.sensitivity),
    statsMetricNode("FPR", selected.falsePositiveRate),
  ], "ROC");

  return {
    mode: "statistics",
    tree,
    answer: `AUC = ${formatNumber(result.auc)}, best threshold = ${formatNumber(result.best.threshold)}`,
    summary: "ROC/AUC analysis",
    details: `${request.labels.length} scored binary cases`,
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read binary labels and scores",
        expression: `positives = ${result.positives}, negatives = ${result.negatives}`,
        detail: "ROC analysis evaluates how well numeric scores rank positive cases above negative cases.",
      },
      {
        title: "Sweep classification thresholds",
        expression: `${result.curve.length - 1} score thresholds`,
        detail: "Each threshold converts scores into positive or negative predictions.",
      },
      {
        title: "Integrate ROC curve",
        expression: `AUC = ${formatNumber(result.auc)}`,
        detail: "The area under the curve is the trapezoidal area across false-positive and true-positive rates.",
      },
      {
        title: "Choose operating threshold",
        expression: `threshold = ${formatNumber(selected.threshold)}, sensitivity = ${formatNumber(selected.sensitivity)}, specificity = ${formatNumber(selected.specificity)}`,
        detail: "The default threshold maximizes Youden's J statistic unless a threshold is supplied.",
      },
    ],
    table: {
      headers: ["Threshold", "TPR", "FPR", "Specificity", "Precision", "Accuracy", "Youden J"],
      rows: result.curve.slice(1).map((point) => [
        formatNumber(point.threshold),
        formatNumber(point.sensitivity),
        formatNumber(point.falsePositiveRate),
        formatNumber(point.specificity),
        formatNumber(point.precision),
        formatNumber(point.accuracy),
        formatNumber(point.youden),
      ]),
    },
    artifacts: [
      ["AUC", formatNumber(result.auc)],
      ["Best threshold", formatNumber(result.best.threshold)],
      ["Best Youden J", formatNumber(result.best.youden)],
      ["Selected threshold", formatNumber(selected.threshold)],
      ["Sensitivity", formatNumber(selected.sensitivity)],
      ["Specificity", formatNumber(selected.specificity)],
      ["False positive rate", formatNumber(selected.falsePositiveRate)],
      ["Precision", formatNumber(selected.precision)],
      ["Accuracy", formatNumber(selected.accuracy)],
      ["True positives", formatNumber(selected.tp)],
      ["False positives", formatNumber(selected.fp)],
      ["True negatives", formatNumber(selected.tn)],
      ["False negatives", formatNumber(selected.fn)],
    ],
  };
}

function analyzeDecisionTreeClassifier(statement) {
  const request = parseDecisionTreeInput(statement);
  const model = fitDecisionTreeClassifier(request.classes, request.predictors, request.maxDepth, request.minLeaf);
  const predictorNames = request.predictors.map((predictor) => predictor.name);
  const trainingPredictions = request.classes.map((_, row) =>
    predictDecisionTree(model.root, request.predictors.map((predictor) => predictor.values[row]), predictorNames),
  );
  const correct = trainingPredictions.filter((prediction, index) => prediction.classValue === request.classes[index]).length;
  const accuracy = correct / request.classes.length;
  const hasPrediction = request.prediction.every(Number.isFinite);
  const prediction = hasPrediction ? predictDecisionTree(model.root, request.prediction, predictorNames) : null;
  const rootLabel = model.root.leaf
    ? `leaf ${formatNumber(model.root.predictedClass)}`
    : `${predictorNames[model.root.featureIndex]} <= ${formatNumber(model.root.threshold)}`;
  const classLabels = model.classes.map(formatNumber).join(", ");
  const tree = {
    kind: "statsRegression",
    label: "TREE",
    children: [
      statsDatasetNode(request.classes, [], "CLASS"),
      ...request.predictors.map((predictor) => statsDatasetNode(predictor.values, [], predictor.name)),
      statsMetricNode("ACC", accuracy),
      statsMetricNode("NODES", model.nodeCount),
    ],
  };

  return {
    mode: "statistics",
    tree,
    answer: prediction
      ? `predicted class = ${formatNumber(prediction.classValue)}`
      : `root split = ${rootLabel}`,
    summary: "decision tree classifier",
    details: `${request.classes.length} observations, ${model.classes.length} classes, depth ${model.depth}`,
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read classes and numeric features",
        expression: `classes = ${classLabels}, features = ${predictorNames.join(", ")}`,
        detail: "The tree classifier learns numeric split rules from labeled feature data.",
      },
      {
        title: "Choose Gini splits",
        expression: `root: ${rootLabel}`,
        detail: "Each internal node picks the split that most reduces weighted Gini impurity.",
      },
      {
        title: "Evaluate training predictions",
        expression: `accuracy = ${formatNumber(accuracy)}, nodes = ${model.nodeCount}`,
        detail: "Training rows are passed through the learned tree and compared with their labels.",
      },
      ...(prediction
        ? [{
            title: "Trace prediction path",
            expression: prediction.path.join(" -> "),
            detail: "The new feature values follow split decisions until they reach a leaf.",
          }]
        : []),
    ],
    table: {
      headers: ["Obs", "Actual", "Predicted", "Leaf Samples"],
      rows: request.classes.map((value, index) => [
        String(index + 1),
        formatNumber(value),
        formatNumber(trainingPredictions[index].classValue),
        formatNumber(trainingPredictions[index].samples),
      ]),
    },
    artifacts: [
      ["Classes", classLabels],
      ["Max depth", formatNumber(request.maxDepth)],
      ["Min leaf", formatNumber(request.minLeaf)],
      ["Tree depth", formatNumber(model.depth)],
      ["Node count", formatNumber(model.nodeCount)],
      ["Training accuracy", formatNumber(accuracy)],
      ["Root split", rootLabel],
      ["Root Gini", formatNumber(model.root.gini)],
      ...decisionTreeRuleArtifacts(model.root, predictorNames),
      ...(prediction
        ? [
            ["Predicted class", formatNumber(prediction.classValue)],
            ["Prediction path", prediction.path.join(" -> ")],
            ["Prediction leaf samples", formatNumber(prediction.samples)],
          ]
        : []),
    ],
  };
}

function analyzeRandomForestClassifier(statement) {
  const request = parseRandomForestInput(statement);
  const model = fitRandomForestClassifier(request.classes, request.predictors, request);
  const predictorNames = request.predictors.map((predictor) => predictor.name);
  const trainingPredictions = request.classes.map((_, row) =>
    predictRandomForest(model.trees, request.predictors.map((predictor) => predictor.values[row]), predictorNames),
  );
  const correct = trainingPredictions.filter((prediction, index) => prediction.classValue === request.classes[index]).length;
  const accuracy = correct / request.classes.length;
  const oob = evaluateRandomForestOob(model.trees, request.classes, request.predictors, predictorNames);
  const hasPrediction = request.prediction.every(Number.isFinite);
  const prediction = hasPrediction ? predictRandomForest(model.trees, request.prediction, predictorNames) : null;
  const classLabels = model.classes.map(formatNumber).join(", ");
  const tree = {
    kind: "statsRegression",
    label: "FOREST",
    children: [
      statsDatasetNode(request.classes, [], "CLASS"),
      ...request.predictors.map((predictor) => statsDatasetNode(predictor.values, [], predictor.name)),
      statsMetricNode("TREES", request.treeCount),
      statsMetricNode("ACC", accuracy),
      statsMetricNode("OOB", Number.isFinite(oob.accuracy) ? oob.accuracy : 0),
    ],
  };

  return {
    mode: "statistics",
    tree,
    answer: prediction
      ? `predicted class = ${formatNumber(prediction.classValue)} (vote confidence = ${formatNumber(prediction.confidence)})`
      : `training accuracy = ${formatNumber(accuracy)}`,
    summary: "random forest classifier",
    details: `${request.classes.length} observations, ${model.classes.length} classes, ${request.treeCount} trees, mtry ${request.mtry}`,
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read classes and numeric features",
        expression: `classes = ${classLabels}, features = ${predictorNames.join(", ")}`,
        detail: "The forest learns many decision trees from the same labeled numeric dataset.",
      },
      {
        title: "Bootstrap and subsample features",
        expression: `${request.treeCount} trees, sample size ${request.sampleSize}, mtry ${request.mtry}, seed ${request.seed}`,
        detail: "Each tree trains on a seeded bootstrap sample and considers a random subset of features at each split.",
      },
      {
        title: "Vote across trees",
        expression: `accuracy = ${formatNumber(accuracy)}, OOB accuracy = ${Number.isFinite(oob.accuracy) ? formatNumber(oob.accuracy) : "not available"}`,
        detail: "Predictions use majority vote; out-of-bag rows estimate performance from trees that did not train on that row.",
      },
      ...(prediction
        ? [{
            title: "Predict new values",
            expression: `votes = ${formatVoteCounts(prediction.votes)}`,
            detail: "The predicted class is the class with the most tree votes.",
          }]
        : []),
    ],
    table: {
      headers: ["Obs", "Actual", "Predicted", "Vote Confidence", "OOB Prediction"],
      rows: request.classes.map((value, index) => [
        String(index + 1),
        formatNumber(value),
        formatNumber(trainingPredictions[index].classValue),
        formatNumber(trainingPredictions[index].confidence),
        oob.predictions[index] ? formatNumber(oob.predictions[index].classValue) : "-",
      ]),
    },
    artifacts: [
      ["Classes", classLabels],
      ["Trees", formatNumber(request.treeCount)],
      ["Max depth", formatNumber(request.maxDepth)],
      ["Min leaf", formatNumber(request.minLeaf)],
      ["Mtry", formatNumber(request.mtry)],
      ["Sample size", formatNumber(request.sampleSize)],
      ["Seed", formatNumber(request.seed)],
      ["Training accuracy", formatNumber(accuracy)],
      ["OOB accuracy", Number.isFinite(oob.accuracy) ? formatNumber(oob.accuracy) : "not available"],
      ["OOB rows scored", formatNumber(oob.scoredCount)],
      ["Average tree depth", formatNumber(model.averageDepth)],
      ["Average node count", formatNumber(model.averageNodeCount)],
      ...randomForestTreeArtifacts(model.trees, predictorNames),
      ...(prediction
        ? [
            ["Predicted class", formatNumber(prediction.classValue)],
            ["Vote confidence", formatNumber(prediction.confidence)],
            ["Prediction votes", formatVoteCounts(prediction.votes)],
          ]
        : []),
    ],
  };
}

function analyzePoissonRegression(statement) {
  const request = parsePoissonRegressionInput(statement);
  const design = request.y.map((_, row) => [
    1,
    ...request.predictors.map((predictor) => predictor.values[row]),
  ]);
  const fit = fitPoissonRegression(design, request.y);
  const residuals = request.y.map((value, index) => normalizeNumber(value - fit.rates[index]));
  const nullMean = mean(request.y);
  const nullLogLikelihood = request.y.reduce(
    (sum, value) => sum + poissonRegressionObservationLogLikelihood(value, nullMean),
    0,
  );
  const mcfaddenR2 = nullLogLikelihood < 0 ? 1 - fit.logLikelihood / nullLogLikelihood : Number.NaN;
  const predictorNames = request.predictors.map((predictor) => predictor.name);
  const equation = formatPoissonRegressionEquation(fit.coefficients, predictorNames);
  const hasPrediction = request.prediction.every(Number.isFinite);
  const predictedRate = hasPrediction
    ? poissonMeanFromLinearPredictor(dotProduct([1, ...request.prediction], fit.coefficients))
    : Number.NaN;
  const tree = {
    kind: "statsRegression",
    label: "POISSON REG",
    children: [
      statsDatasetNode(request.y, [], "Y"),
      ...request.predictors.map((predictor) => statsDatasetNode(predictor.values, [], predictor.name)),
      statsMetricNode("LL", fit.logLikelihood),
      statsMetricNode("DEV", fit.deviance),
    ],
  };

  return {
    mode: "statistics",
    tree,
    answer: hasPrediction
      ? `${equation}; expected count = ${formatNumber(predictedRate)}`
      : equation,
    summary: "Poisson regression",
    details: `${request.y.length} count observations, ${request.predictors.length} predictors`,
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read count response and predictors",
        expression: `n = ${request.y.length}, predictors = ${predictorNames.join(", ")}`,
        detail: "Poisson regression models nonnegative integer counts using predictor variables.",
      },
      {
        title: "Build log-link model",
        expression: "log(lambda) = b0 + b1x1 + ...",
        detail: "The log link keeps the fitted expected counts positive.",
      },
      {
        title: "Fit by Fisher scoring",
        expression: `${fit.iterations} iterations, ${fit.converged ? "converged" : "stopped"}`,
        detail: "Each iteration updates the coefficients using the Poisson likelihood gradient and information matrix.",
      },
      {
        title: "Measure count-model fit",
        expression: `log likelihood = ${formatNumber(fit.logLikelihood)}, deviance = ${formatNumber(fit.deviance)}`,
        detail: "Deviance compares the fitted rates to a saturated model that exactly matches the counts.",
      },
      ...(hasPrediction
        ? [{
            title: "Predict expected count",
            expression: `lambda = ${formatNumber(predictedRate)}`,
            detail: "The requested predictor values are plugged into the fitted log-link model.",
          }]
        : []),
    ],
    table: {
      headers: ["Obs", "Actual", "Fitted count", "Residual"],
      rows: request.y.map((value, index) => [
        String(index + 1),
        formatNumber(value),
        formatNumber(fit.rates[index]),
        formatNumber(residuals[index]),
      ]),
    },
    artifacts: [
      ["Equation", equation],
      ["Intercept", formatNumber(fit.coefficients[0])],
      ...request.predictors.map((predictor, index) => [`Coefficient ${predictor.name}`, formatNumber(fit.coefficients[index + 1])]),
      ["Log likelihood", formatNumber(fit.logLikelihood)],
      ["Deviance", formatNumber(fit.deviance)],
      ["McFadden R squared", Number.isFinite(mcfaddenR2) ? formatNumber(mcfaddenR2) : "undefined"],
      ["Converged", fit.converged ? "yes" : "no"],
      ...(hasPrediction ? [["Predicted expected count", formatNumber(predictedRate)]] : []),
    ],
  };
}

function analyzeMultivariateStatistics(statement) {
  const lower = statement.toLowerCase();
  const dataset = parseMultivariateStatsInput(statement);
  const columns = dataset.columns.map((column) => column.values);
  const covariance = covarianceMatrixFromColumns(columns);
  const wantsPca = lower.includes("pca") || lower.includes("principal component");
  const wantsCorrelation = lower.includes("correlation");
  const correlation = covariance.every((row, index) => row[index] > EPSILON)
    ? correlationMatrixFromCovariance(covariance)
    : null;
  if (wantsCorrelation && !correlation) {
    throw new Error("Correlation matrix needs every variable to have nonzero sample variance.");
  }
  const tree = {
    kind: "statsDistribution",
    label: wantsPca ? "PCA" : wantsCorrelation ? "CORR" : "COV",
    children: [
      ...dataset.columns.map((column) => statsDatasetNode(column.values, [], column.name)),
      matrixNode("COV", covariance),
      ...(correlation && wantsCorrelation ? [matrixNode("R", correlation)] : []),
    ],
  };

  if (wantsPca) {
    const components = principalComponents(covariance);
    const scores = principalComponentScores(dataset, components);
    const pcTree = {
      ...tree,
      children: [
        ...tree.children,
        ...components.map((component, index) => vectorNode(`PC${index + 1}`, component.vector)),
      ],
    };

    return {
      mode: "statistics",
      tree: pcTree,
      answer: `PC1 variance = ${formatNumber(components[0].eigenvalue)}, explained = ${formatNumber(components[0].explained * 100)}%; direction = ${formatVector(components[0].vector)}`,
      summary: "principal component analysis",
      details: `${dataset.n} observations, ${dataset.columns.length} variables`,
      variables: [],
      metrics: treeMetrics(pcTree),
      steps: [
        {
          title: "Read variables",
          expression: dataset.columns.map((column) => `${column.name}: ${column.values.map(formatNumber).join(", ")}`).join("; "),
          detail: "PCA treats each labeled list as one variable measured on the same observations.",
        },
        {
          title: "Center variables",
          expression: dataset.columns.map((column) => `${column.name}bar = ${formatNumber(column.mean)}`).join(", "),
          detail: "Subtracting each mean makes the covariance matrix measure shared variation.",
        },
        {
          title: "Build covariance matrix",
          expression: formatMatrix(covariance),
          detail: "Sample covariance uses denominator n - 1.",
        },
        {
          title: "Find principal components",
          expression: `lambda = ${formatVector(components.map((component) => component.eigenvalue))}`,
          detail: "The eigenvectors of the covariance matrix are the principal component directions.",
        },
        {
          title: "Project observations",
          expression: `PC scores for row 1 = ${formatVector(scores[0])}`,
          detail: "Each centered observation is projected onto the component directions.",
        },
      ],
      table: multivariateObservationTable(dataset),
      artifacts: [
        ["Variables", dataset.columns.map((column) => column.name).join(", ")],
        ["Observations", formatNumber(dataset.n)],
        ["Covariance matrix", formatMatrix(covariance)],
        ["Correlation matrix", correlation ? formatMatrix(correlation) : "undefined"],
        ...components.flatMap((component, index) => [
          [`PC${index + 1} eigenvalue`, formatNumber(component.eigenvalue)],
          [`PC${index + 1} explained variance`, `${formatNumber(component.explained * 100)}%`],
          [`PC${index + 1} cumulative variance`, `${formatNumber(component.cumulative * 100)}%`],
          [`PC${index + 1} direction`, formatVector(component.vector)],
        ]),
        ["PC score matrix", formatMatrix(scores)],
      ],
    };
  }

  const matrix = wantsCorrelation ? correlation : covariance;
  const label = wantsCorrelation ? "correlation matrix" : "covariance matrix";
  return {
    mode: "statistics",
    tree: {
      ...tree,
      children: correlation && !wantsCorrelation ? [...tree.children, matrixNode("R", correlation)] : tree.children,
    },
    answer: `${label} = ${formatMatrix(matrix)}`,
    summary: label,
    details: `${dataset.n} observations, ${dataset.columns.length} variables`,
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read variables",
        expression: dataset.columns.map((column) => `${column.name}: ${column.values.map(formatNumber).join(", ")}`).join("; "),
        detail: "Each labeled list must have the same number of observations.",
      },
      {
        title: "Center variables",
        expression: dataset.columns.map((column) => `${column.name}bar = ${formatNumber(column.mean)}`).join(", "),
        detail: "Covariance and correlation compare deviations from each variable mean.",
      },
      {
        title: "Compute covariance",
        expression: formatMatrix(covariance),
        detail: "The covariance matrix stores every pairwise sample covariance.",
      },
      {
        title: "Scale to correlation",
        expression: correlation ? formatMatrix(correlation) : "undefined",
        detail: correlation
          ? "Correlation divides covariance by the product of the two sample standard deviations."
          : "A constant variable has zero sample standard deviation, so correlation is undefined.",
      },
    ],
    table: multivariateObservationTable(dataset),
    artifacts: [
      ["Variables", dataset.columns.map((column) => column.name).join(", ")],
      ["Observations", formatNumber(dataset.n)],
      ["Covariance matrix", formatMatrix(covariance)],
      ["Correlation matrix", correlation ? formatMatrix(correlation) : "undefined"],
    ],
  };
}

