function analyzeBinomial(statement) {
  const params = parseNamedProbabilityParams(statement);
  const n = params.n;
  const p = params.p;
  const k = params.k;

  if (!Number.isInteger(n) || !Number.isInteger(k) || n < 0 || k < 0 || k > n) {
    throw new Error("Binomial probability needs integer values with 0 <= k <= n.");
  }
  if (!(p >= 0 && p <= 1)) {
    throw new Error("Binomial probability needs p between 0 and 1.");
  }

  const exact = binomialProbability(n, p, k);
  const atMost = sumRange(0, k, (value) => binomialProbability(n, p, value));
  const atLeast = sumRange(k, n, (value) => binomialProbability(n, p, value));
  const expected = n * p;
  const variance = n * p * (1 - p);

  const steps = [
    {
      title: "Read binomial parameters",
      expression: `n = ${n}, p = ${formatNumber(p)}, k = ${k}`,
      detail: "A binomial model counts successes in independent trials.",
    },
    {
      title: "Apply probability formula",
      expression: "P(X = k) = C(n,k) p^k (1-p)^(n-k)",
      detail: "The combination counts which trials are successes.",
    },
    {
      title: "Compute exact probability",
      expression: `P(X = ${k}) = ${formatNumber(exact)}`,
      detail: "This is the probability of exactly k successes.",
    },
  ];

  return {
    mode: "statistics",
    tree: {
      kind: "statsDistribution",
      label: "BINOMIAL",
      children: [
        statsMetricNode("n", n),
        statsMetricNode("p", p),
        statsMetricNode("k", k),
      ],
    },
    answer: `P(X = ${k}) = ${formatNumber(exact)}`,
    summary: "binomial probability",
    details: "Discrete probability distribution",
    variables: [],
    metrics: treeMetrics({
      kind: "statsDistribution",
      children: [statsMetricNode("n", n), statsMetricNode("p", p), statsMetricNode("k", k)],
    }),
    steps,
    artifacts: [
      [`P(X = ${k})`, formatNumber(exact)],
      [`P(X <= ${k})`, formatNumber(atMost)],
      [`P(X >= ${k})`, formatNumber(atLeast)],
      ["Expected value", formatNumber(expected)],
      ["Variance", formatNumber(variance)],
      ["Standard deviation", formatNumber(Math.sqrt(variance))],
    ],
  };
}

function analyzePoisson(statement) {
  const request = parsePoissonInput(statement);
  const lambda = request.lambda;
  const k = request.k;

  if (!(lambda > 0)) {
    throw new Error("Poisson probability needs lambda greater than 0.");
  }
  if (!Number.isInteger(k) || k < 0) {
    throw new Error("Poisson probability needs a nonnegative integer k.");
  }

  const exact = poissonProbability(lambda, k);
  const atMost = sumRange(0, k, (value) => poissonProbability(lambda, value));
  const below = k === 0 ? 0 : sumRange(0, k - 1, (value) => poissonProbability(lambda, value));
  const atLeast = 1 - below;
  const greater = 1 - atMost;
  const probability = request.tail === "at-most"
    ? atMost
    : request.tail === "less"
      ? below
      : request.tail === "at-least"
        ? atLeast
        : request.tail === "greater"
          ? greater
          : exact;
  const label = poissonProbabilityLabel(request.tail, k);

  return {
    mode: "statistics",
    tree: {
      kind: "statsDistribution",
      label: "POISSON",
      children: [
        statsMetricNode("lambda", lambda),
        statsMetricNode("k", k),
        statsMetricNode("P", probability),
      ],
    },
    answer: `${label} = ${formatNumber(probability)}`,
    summary: "Poisson probability",
    details: "Discrete count distribution",
    variables: [],
    metrics: treeMetrics({
      kind: "statsDistribution",
      children: [statsMetricNode("lambda", lambda), statsMetricNode("k", k)],
    }),
    steps: [
      {
        title: "Read Poisson parameters",
        expression: `lambda = ${formatNumber(lambda)}, k = ${k}`,
        detail: "A Poisson model counts events occurring at a constant average rate.",
      },
      {
        title: "Apply probability formula",
        expression: "P(X = k) = e^-lambda lambda^k / k!",
        detail: "The formula gives the probability of exactly k events.",
      },
      {
        title: "Evaluate requested tail",
        expression: `${label} = ${formatNumber(probability)}`,
        detail: "Cumulative questions sum the exact probabilities over the requested counts.",
      },
    ],
    artifacts: [
      [`P(X = ${k})`, formatNumber(exact)],
      [`P(X <= ${k})`, formatNumber(atMost)],
      [`P(X >= ${k})`, formatNumber(atLeast)],
      ["Expected value", formatNumber(lambda)],
      ["Variance", formatNumber(lambda)],
      ["Standard deviation", formatNumber(Math.sqrt(lambda))],
    ],
  };
}

function analyzeGeometric(statement) {
  const request = parseGeometricInput(statement);
  const p = request.p;
  const k = request.k;

  if (!(p > 0 && p <= 1)) {
    throw new Error("Geometric probability needs p with 0 < p <= 1.");
  }
  if (!Number.isInteger(k) || k < 1) {
    throw new Error("Geometric probability uses trial count k with integer k >= 1.");
  }

  const exact = geometricProbability(p, k);
  const atMost = 1 - (1 - p) ** k;
  const below = k === 1 ? 0 : 1 - (1 - p) ** (k - 1);
  const atLeast = (1 - p) ** (k - 1);
  const greater = (1 - p) ** k;
  const probability = request.tail === "at-most"
    ? atMost
    : request.tail === "less"
      ? below
      : request.tail === "at-least"
        ? atLeast
        : request.tail === "greater"
          ? greater
          : exact;
  const label = poissonProbabilityLabel(request.tail, k);
  const expected = 1 / p;
  const variance = (1 - p) / (p ** 2);

  return {
    mode: "statistics",
    tree: {
      kind: "statsDistribution",
      label: "GEOMETRIC",
      children: [
        statsMetricNode("p", p),
        statsMetricNode("k", k),
        statsMetricNode("P", probability),
      ],
    },
    answer: `${label} = ${formatNumber(probability)}`,
    summary: "geometric probability",
    details: "Trials until first success",
    variables: [],
    metrics: treeMetrics({
      kind: "statsDistribution",
      children: [statsMetricNode("p", p), statsMetricNode("k", k)],
    }),
    steps: [
      {
        title: "Read geometric parameters",
        expression: `p = ${formatNumber(p)}, k = ${k}`,
        detail: "A geometric model counts the trial on which the first success occurs.",
      },
      {
        title: "Apply probability formula",
        expression: "P(X = k) = (1-p)^(k-1) p",
        detail: "The first k-1 trials fail and the kth trial succeeds.",
      },
      {
        title: "Evaluate requested tail",
        expression: `${label} = ${formatNumber(probability)}`,
        detail: "Cumulative questions use the geometric series for repeated failures.",
      },
    ],
    artifacts: [
      [`P(X = ${k})`, formatNumber(exact)],
      [`P(X <= ${k})`, formatNumber(atMost)],
      [`P(X >= ${k})`, formatNumber(atLeast)],
      ["Expected value", formatNumber(expected)],
      ["Variance", formatNumber(variance)],
      ["Standard deviation", formatNumber(Math.sqrt(variance))],
    ],
  };
}

function analyzeExponential(statement) {
  const request = parseExponentialInput(statement);
  const lambda = request.lambda;
  const x = request.x;

  if (!(lambda > 0)) {
    throw new Error("Exponential probability needs lambda greater than 0, or a positive mean.");
  }
  if (!(x >= 0)) {
    throw new Error("Exponential probability needs x >= 0.");
  }

  const leftTail = 1 - Math.exp(-lambda * x);
  const rightTail = Math.exp(-lambda * x);
  const probability = request.tail === "greater" || request.tail === "at-least" ? rightTail : leftTail;
  const label = request.tail === "greater" || request.tail === "at-least"
    ? `P(X > ${formatNumber(x)})`
    : `P(X <= ${formatNumber(x)})`;
  const expected = 1 / lambda;
  const variance = 1 / (lambda ** 2);

  return {
    mode: "statistics",
    tree: {
      kind: "statsDistribution",
      label: "EXPONENTIAL",
      children: [
        statsMetricNode("lambda", lambda),
        statsMetricNode("x", x),
        statsMetricNode("P", probability),
      ],
    },
    answer: `${label} = ${formatNumber(probability)}`,
    summary: "exponential probability",
    details: "Continuous waiting-time distribution",
    variables: [],
    metrics: treeMetrics({
      kind: "statsDistribution",
      children: [statsMetricNode("lambda", lambda), statsMetricNode("x", x)],
    }),
    steps: [
      {
        title: "Read exponential parameters",
        expression: `lambda = ${formatNumber(lambda)}, x = ${formatNumber(x)}`,
        detail: "An exponential model measures waiting time between events.",
      },
      {
        title: "Evaluate CDF or survival function",
        expression: request.tail === "greater" || request.tail === "at-least"
          ? "P(X > x) = e^(-lambda x)"
          : "P(X <= x) = 1 - e^(-lambda x)",
        detail: "Continuous tail probabilities come from the exponential curve.",
      },
      {
        title: "Report probability",
        expression: `${label} = ${formatNumber(probability)}`,
        detail: "The solver also reports the distribution moments.",
      },
    ],
    artifacts: [
      [`P(X <= ${formatNumber(x)})`, formatNumber(leftTail)],
      [`P(X > ${formatNumber(x)})`, formatNumber(rightTail)],
      ["Expected value", formatNumber(expected)],
      ["Variance", formatNumber(variance)],
      ["Standard deviation", formatNumber(Math.sqrt(variance))],
    ],
  };
}

function analyzeUniform(statement) {
  const request = parseUniformInput(statement);
  const min = request.min;
  const max = request.max;

  if (!(max > min)) {
    throw new Error("Uniform probability needs max greater than min.");
  }

  const width = max - min;
  const density = 1 / width;
  let probability;
  let label;
  let expression;
  if (request.interval) {
    const lower = Math.max(min, Math.min(request.interval.left, request.interval.right));
    const upper = Math.min(max, Math.max(request.interval.left, request.interval.right));
    probability = Math.max(0, upper - lower) / width;
    label = `P(${formatNumber(request.interval.left)} <= X <= ${formatNumber(request.interval.right)})`;
    expression = "P(a <= X <= b) = interval length / total length";
  } else if (request.tail === "greater" || request.tail === "at-least") {
    probability = clampProbability((max - request.x) / width);
    label = `P(X > ${formatNumber(request.x)})`;
    expression = "P(X > x) = (max - x) / (max - min)";
  } else {
    probability = clampProbability((request.x - min) / width);
    label = `P(X <= ${formatNumber(request.x)})`;
    expression = "P(X <= x) = (x - min) / (max - min)";
  }
  const expected = (min + max) / 2;
  const variance = width ** 2 / 12;

  return {
    mode: "statistics",
    tree: {
      kind: "statsDistribution",
      label: "UNIFORM",
      children: [
        statsMetricNode("min", min),
        statsMetricNode("max", max),
        statsMetricNode("P", probability),
      ],
    },
    answer: `${label} = ${formatNumber(probability)}`,
    summary: "uniform probability",
    details: "Continuous equal-density distribution",
    variables: [],
    metrics: treeMetrics({
      kind: "statsDistribution",
      children: [statsMetricNode("min", min), statsMetricNode("max", max)],
    }),
    steps: [
      {
        title: "Read uniform interval",
        expression: `[${formatNumber(min)}, ${formatNumber(max)}]`,
        detail: "A uniform model gives every equal-length subinterval the same probability.",
      },
      {
        title: "Compute length ratio",
        expression,
        detail: "The probability is a length inside the interval divided by total interval length.",
      },
      {
        title: "Report probability",
        expression: `${label} = ${formatNumber(probability)}`,
        detail: "The solver clamps probabilities to the valid support of the distribution.",
      },
    ],
    artifacts: [
      [label, formatNumber(probability)],
      ["Density", formatNumber(density)],
      ["Expected value", formatNumber(expected)],
      ["Variance", formatNumber(variance)],
      ["Standard deviation", formatNumber(Math.sqrt(variance))],
    ],
  };
}

function analyzeDiscreteDistribution(statement) {
  const { values, probabilities } = parseDiscreteDistributionInput(statement);
  const expectedValue = values.reduce((sum, value, index) => sum + value * probabilities[index], 0);
  const variance = values.reduce((sum, value, index) => sum + probabilities[index] * (value - expectedValue) ** 2, 0);
  const standardDeviation = Math.sqrt(variance);
  let cumulative = 0;
  const rows = values.map((value, index) => {
    cumulative += probabilities[index];
    return [
      formatNumber(value),
      formatNumber(probabilities[index]),
      formatNumber(value * probabilities[index]),
      formatNumber(cumulative),
    ];
  });

  return {
    mode: "statistics",
    tree: {
      kind: "statsDistribution",
      label: "DISCRETE",
      children: [
        statsMetricNode("E[X]", expectedValue),
        statsMetricNode("VAR", variance),
        statsMetricNode("SD", standardDeviation),
      ],
    },
    answer: `E(X) = ${formatNumber(expectedValue)}, Var(X) = ${formatNumber(variance)}`,
    summary: "discrete expected value",
    details: "Expected value and variance from a probability mass function",
    variables: [],
    metrics: treeMetrics({
      kind: "statsDistribution",
      children: values.map((value, index) => statsMetricNode(formatNumber(value), probabilities[index])),
    }),
    steps: [
      {
        title: "Read probability mass function",
        expression: values.map((value, index) => `${formatNumber(value)}:${formatNumber(probabilities[index])}`).join(", "),
        detail: "Each outcome is paired with its probability.",
      },
      {
        title: "Compute expected value",
        expression: `E(X) = sum x p(x) = ${formatNumber(expectedValue)}`,
        detail: "Expected value is the long-run weighted average outcome.",
      },
      {
        title: "Compute variance",
        expression: `Var(X) = sum p(x)(x - E(X))^2 = ${formatNumber(variance)}`,
        detail: "Variance measures the weighted squared distance from the expected value.",
      },
    ],
    table: {
      headers: ["Outcome", "Probability", "x p(x)", "Cumulative"],
      rows,
    },
    artifacts: [
      ["Expected value", formatNumber(expectedValue)],
      ["Variance", formatNumber(variance)],
      ["Standard deviation", formatNumber(standardDeviation)],
    ],
  };
}

function analyzeBayes(statement) {
  const { prior, sensitivity, falsePositiveRate, specificity } = parseBayesInput(statement);
  const truePositiveMass = sensitivity * prior;
  const falsePositiveMass = falsePositiveRate * (1 - prior);
  const positiveProbability = truePositiveMass + falsePositiveMass;
  const posteriorPositive = truePositiveMass / positiveProbability;
  const falseNegativeMass = (1 - sensitivity) * prior;
  const trueNegativeMass = specificity * (1 - prior);
  const negativeProbability = falseNegativeMass + trueNegativeMass;
  const posteriorNegative = negativeProbability > 0 ? falseNegativeMass / negativeProbability : Number.NaN;
  const likelihoodRatioPositive = falsePositiveRate > 0 ? sensitivity / falsePositiveRate : Infinity;
  const likelihoodRatioPositiveText = falsePositiveRate > 0 ? formatNumber(likelihoodRatioPositive) : "infinity";

  return {
    mode: "statistics",
    tree: {
      kind: "statsDistribution",
      label: "BAYES",
      children: [
        statsMetricNode("PRIOR", prior),
        statsMetricNode("TPR", sensitivity),
        statsMetricNode("FPR", falsePositiveRate),
        statsMetricNode("POST", posteriorPositive),
      ],
    },
    answer: `P(H | positive) = ${formatNumber(posteriorPositive)}`,
    summary: "Bayes theorem",
    details: "Posterior probability after a positive test",
    variables: [],
    metrics: treeMetrics({
      kind: "statsDistribution",
      children: [
        statsMetricNode("prior", prior),
        statsMetricNode("sensitivity", sensitivity),
        statsMetricNode("false positive", falsePositiveRate),
      ],
    }),
    steps: [
      {
        title: "Read prior and test rates",
        expression: `prior = ${formatNumber(prior)}, sensitivity = ${formatNumber(sensitivity)}, specificity = ${formatNumber(specificity)}`,
        detail: "Bayes theorem updates a prior probability after observing test evidence.",
      },
      {
        title: "Compute positive evidence",
        expression: `P(positive) = ${formatNumber(truePositiveMass)} + ${formatNumber(falsePositiveMass)} = ${formatNumber(positiveProbability)}`,
        detail: "Positive results can come from true positives or false positives.",
      },
      {
        title: "Apply Bayes theorem",
        expression: `P(H | positive) = ${formatNumber(truePositiveMass)} / ${formatNumber(positiveProbability)} = ${formatNumber(posteriorPositive)}`,
        detail: "The posterior divides true-positive probability mass by all positive probability mass.",
      },
    ],
    table: {
      headers: ["Event", "Probability mass"],
      rows: [
        ["true positive", formatNumber(truePositiveMass)],
        ["false positive", formatNumber(falsePositiveMass)],
        ["positive result", formatNumber(positiveProbability)],
        ["false negative", formatNumber(falseNegativeMass)],
        ["true negative", formatNumber(trueNegativeMass)],
      ],
    },
    artifacts: [
      ["Prior P(H)", formatNumber(prior)],
      ["Sensitivity P(+|H)", formatNumber(sensitivity)],
      ["Specificity P(-|not H)", formatNumber(specificity)],
      ["False positive rate", formatNumber(falsePositiveRate)],
      ["P(positive)", formatNumber(positiveProbability)],
      ["P(H | positive)", formatNumber(posteriorPositive)],
      ["P(H | negative)", formatNumber(posteriorNegative)],
      ["Positive likelihood ratio", likelihoodRatioPositiveText],
    ],
  };
}

function analyzeBayesianNormalMean(statement) {
  const request = parseBayesianNormalInput(statement);
  const summary = descriptiveSummary(request.values);
  const priorVariance = request.priorSd ** 2;
  const observationVariance = request.sigma ** 2;
  const posteriorVariance = 1 / ((1 / priorVariance) + (summary.count / observationVariance));
  const posteriorSd = Math.sqrt(posteriorVariance);
  const posteriorMean = posteriorVariance *
    ((request.priorMean / priorVariance) + (summary.count * summary.mean / observationVariance));
  const dataWeight = (summary.count / observationVariance) /
    ((1 / priorVariance) + (summary.count / observationVariance));
  const critical = zCriticalForLevel(request.level);
  const lower = posteriorMean - critical * posteriorSd;
  const upper = posteriorMean + critical * posteriorSd;
  const predictiveSd = Math.sqrt(observationVariance + posteriorVariance);
  const predictiveLower = posteriorMean - critical * predictiveSd;
  const predictiveUpper = posteriorMean + critical * predictiveSd;
  const thresholdProbability = Number.isFinite(request.threshold)
    ? 1 - normalCdf((request.threshold - posteriorMean) / posteriorSd)
    : Number.NaN;
  const percent = formatNumber(request.level * 100);
  const tree = {
    kind: "statsDistribution",
    label: "NORMAL-POST",
    children: [
      statsMetricNode("prior", request.priorMean),
      statsMetricNode("xbar", summary.mean),
      statsMetricNode("post", posteriorMean),
      statsMetricNode("sd", posteriorSd),
    ],
  };

  return {
    mode: "statistics",
    tree,
    answer: `posterior mean = ${formatNumber(posteriorMean)}, ${percent}% credible interval = [${formatNumber(lower)}, ${formatNumber(upper)}]`,
    summary: "Bayesian normal mean",
    details: "Normal-normal conjugate update with known observation standard deviation",
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read prior and normal data",
        expression: `prior N(${formatNumber(request.priorMean)}, ${formatNumber(request.priorSd)}^2), sigma=${formatNumber(request.sigma)}, n=${formatNumber(summary.count)}`,
        detail: "A normal prior is conjugate to normal observations when the observation standard deviation is known.",
      },
      {
        title: "Summarize sample",
        expression: `xbar = ${formatNumber(summary.mean)}, sample sd = ${formatNumber(summary.sampleStdDev)}`,
        detail: "The likelihood contributes information through the sample mean and known sigma.",
      },
      {
        title: "Update posterior precision",
        expression: `posterior SD = ${formatNumber(posteriorSd)}, data weight = ${formatNumber(dataWeight)}`,
        detail: "Prior precision and data precision add together; more precise data receives more weight.",
      },
      {
        title: "Build credible interval",
        expression: `[${formatNumber(lower)}, ${formatNumber(upper)}]`,
        detail: "The posterior interval is centered on the posterior mean.",
      },
      {
        title: "Build predictive interval",
        expression: `[${formatNumber(predictiveLower)}, ${formatNumber(predictiveUpper)}]`,
        detail: "The posterior predictive interval includes uncertainty in the mean and future observation noise.",
      },
      ...(Number.isFinite(thresholdProbability)
        ? [{
            title: "Compute posterior tail probability",
            expression: `P(mu > ${formatNumber(request.threshold)}) = ${formatNumber(thresholdProbability)}`,
            detail: "The posterior normal distribution gives direct probability statements about the unknown mean.",
          }]
        : []),
    ],
    table: {
      headers: ["Quantity", "Value"],
      rows: [
        ["Sample size", formatNumber(summary.count)],
        ["Sample mean", formatNumber(summary.mean)],
        ["Known sigma", formatNumber(request.sigma)],
        ["Prior mean", formatNumber(request.priorMean)],
        ["Prior SD", formatNumber(request.priorSd)],
        ["Posterior mean", formatNumber(posteriorMean)],
        ["Posterior SD", formatNumber(posteriorSd)],
        [`${percent}% credible interval`, `[${formatNumber(lower)}, ${formatNumber(upper)}]`],
        [`${percent}% predictive interval`, `[${formatNumber(predictiveLower)}, ${formatNumber(predictiveUpper)}]`],
        ...(Number.isFinite(thresholdProbability) ? [[`P(mu > ${formatNumber(request.threshold)})`, formatNumber(thresholdProbability)]] : []),
      ],
    },
    artifacts: [
      ["Prior", `N(${formatNumber(request.priorMean)}, ${formatNumber(request.priorSd)}^2)`],
      ["Known sigma", formatNumber(request.sigma)],
      ["Sample mean", formatNumber(summary.mean)],
      ["Posterior mean", formatNumber(posteriorMean)],
      ["Posterior SD", formatNumber(posteriorSd)],
      [`${percent}% credible interval`, `[${formatNumber(lower)}, ${formatNumber(upper)}]`],
      [`${percent}% predictive interval`, `[${formatNumber(predictiveLower)}, ${formatNumber(predictiveUpper)}]`],
      ["Data weight", formatNumber(dataWeight)],
      ...(Number.isFinite(thresholdProbability) ? [[`P(mu > ${formatNumber(request.threshold)})`, formatNumber(thresholdProbability)]] : []),
    ],
  };
}

function analyzeBayesianLinearRegression(statement) {
  const request = parseBayesianLinearRegressionInput(statement);
  const design = request.y.map((_, row) => [
    1,
    ...request.predictors.map((predictor) => predictor.values[row]),
  ]);
  const transposed = transposeMatrix(design);
  const normalMatrix = multiplyMatrices(transposed, design);
  const normalVector = multiplyMatrixVector(transposed, request.y);
  const parameterCount = normalVector.length;
  const observationVariance = request.sigma ** 2;
  const priorVariance = request.priorSd ** 2;
  const dataPrecision = scaleMatrix(normalMatrix, 1 / observationVariance);
  const priorPrecision = scaleMatrix(identityMatrix(parameterCount), 1 / priorVariance);
  const posteriorPrecision = addMatrices(dataPrecision, priorPrecision);
  const posteriorCovariance = invertMatrix(posteriorPrecision);
  const posteriorRightHandSide = normalVector.map((value) =>
    value / observationVariance + request.priorMean / priorVariance,
  );
  const posteriorMean = multiplyMatrixVector(posteriorCovariance, posteriorRightHandSide);
  const predictorNames = request.predictors.map((predictor) => predictor.name);
  const coefficientNames = ["Intercept", ...predictorNames];
  const posteriorSds = posteriorCovariance.map((row, index) => Math.sqrt(Math.max(0, row[index])));
  const critical = zCriticalForLevel(request.level);
  const percent = formatNumber(request.level * 100);
  const equation = formatMultipleRegressionEquation(posteriorMean, predictorNames);
  const coefficientRows = coefficientNames.map((name, index) => {
    const lower = posteriorMean[index] - critical * posteriorSds[index];
    const upper = posteriorMean[index] + critical * posteriorSds[index];
    return [
      name,
      formatNumber(posteriorMean[index]),
      formatNumber(posteriorSds[index]),
      `[${formatNumber(lower)}, ${formatNumber(upper)}]`,
    ];
  });
  const hasPrediction = request.prediction.every(Number.isFinite);
  const predictionRow = hasPrediction ? [1, ...request.prediction] : [];
  const prediction = hasPrediction
    ? dotProduct(predictionRow, posteriorMean)
    : Number.NaN;
  const meanVariance = hasPrediction
    ? Math.max(0, dotProduct(predictionRow, multiplyMatrixVector(posteriorCovariance, predictionRow)))
    : Number.NaN;
  const meanSe = Math.sqrt(meanVariance);
  const predictiveSe = Math.sqrt(meanVariance + observationVariance);
  const meanLower = prediction - critical * meanSe;
  const meanUpper = prediction + critical * meanSe;
  const predictiveLower = prediction - critical * predictiveSe;
  const predictiveUpper = prediction + critical * predictiveSe;
  const tree = {
    kind: "statsRegression",
    label: "BAYES-REG",
    children: [
      statsDatasetNode(request.y, [], "Y"),
      ...request.predictors.map((predictor) => statsDatasetNode(predictor.values, [], predictor.name)),
      statsMetricNode("sigma", request.sigma),
      ...coefficientNames.map((name, index) => statsMetricNode(name, posteriorMean[index])),
    ],
  };

  return {
    mode: "statistics",
    tree,
    answer: hasPrediction
      ? `posterior prediction = ${formatNumber(prediction)}, ${percent}% predictive interval = [${formatNumber(predictiveLower)}, ${formatNumber(predictiveUpper)}]`
      : `posterior equation: ${equation}`,
    summary: "Bayesian linear regression",
    details: `${request.y.length} observations, ${request.predictors.length} predictors, known sigma = ${formatNumber(request.sigma)}`,
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read Bayesian regression inputs",
        expression: `n = ${formatNumber(request.y.length)}, predictors = ${predictorNames.join(", ")}, sigma = ${formatNumber(request.sigma)}`,
        detail: "The model uses a normal likelihood with known observation standard deviation.",
      },
      {
        title: "Build design matrix",
        expression: `X has ${formatNumber(design.length)} rows and ${formatNumber(parameterCount)} columns`,
        detail: "The first column is the intercept; the remaining columns are predictor values.",
      },
      {
        title: "Combine prior and data precision",
        expression: `prior N(${formatNumber(request.priorMean)}, ${formatNumber(request.priorSd)}^2) independently for each coefficient`,
        detail: "Normal priors and a normal likelihood produce a multivariate normal posterior for the coefficients.",
      },
      {
        title: "Compute posterior coefficients",
        expression: equation,
        detail: "The posterior mean balances the least-squares signal against prior shrinkage.",
      },
      ...(hasPrediction
        ? [{
            title: "Predict requested input",
            expression: `x = ${formatVector(request.prediction)}, yhat = ${formatNumber(prediction)}`,
            detail: "The mean-response interval uses coefficient uncertainty; the predictive interval also includes observation noise.",
          }]
        : []),
    ],
    table: {
      headers: ["Coefficient", "Posterior mean", "Posterior SD", `${percent}% credible interval`],
      rows: coefficientRows,
    },
    artifacts: [
      ["Posterior equation", equation],
      ["Known sigma", formatNumber(request.sigma)],
      ["Prior mean", formatNumber(request.priorMean)],
      ["Prior SD", formatNumber(request.priorSd)],
      ["Posterior coefficients", formatVector(posteriorMean)],
      ["Posterior covariance", formatMatrix(posteriorCovariance)],
      ...coefficientNames.flatMap((name, index) => [
        [`Coefficient ${name}`, formatNumber(posteriorMean[index])],
        [`Posterior SD ${name}`, formatNumber(posteriorSds[index])],
      ]),
      ...(hasPrediction
        ? [
            ["Prediction input", formatVector(request.prediction)],
            ["Posterior prediction", formatNumber(prediction)],
            ["Mean response SE", formatNumber(meanSe)],
            [`${percent}% mean response interval`, `[${formatNumber(meanLower)}, ${formatNumber(meanUpper)}]`],
            ["Predictive SE", formatNumber(predictiveSe)],
            [`${percent}% predictive interval`, `[${formatNumber(predictiveLower)}, ${formatNumber(predictiveUpper)}]`],
          ]
        : []),
    ],
    ...(request.predictors.length === 1
      ? { graph: buildScatterFitGraph(request.predictors[0].values, request.y, posteriorMean[1], posteriorMean[0], "Posterior mean fit") }
      : {}),
  };
}

function analyzeBayesianAbTest(statement) {
  const request = parseBayesianAbInput(statement);
  const armA = bayesianAbPosterior(request.left, request.priorAlpha, request.priorBeta, request.level);
  const armB = bayesianAbPosterior(request.right, request.priorAlpha, request.priorBeta, request.level);
  const probabilityRightBetter = betaGreaterProbability(armB.alpha, armB.beta, armA.alpha, armA.beta);
  const probabilityLeftBetter = 1 - probabilityRightBetter;
  const meanDifference = armB.mean - armA.mean;
  const differenceSd = Math.sqrt(armA.variance + armB.variance);
  const critical = zCriticalForLevel(request.level);
  const differenceLower = meanDifference - critical * differenceSd;
  const differenceUpper = meanDifference + critical * differenceSd;
  const relativeLift = armA.mean > 0 ? meanDifference / armA.mean : Number.NaN;
  const decision = probabilityRightBetter >= request.decisionThreshold
    ? `${request.right.name} likely better`
    : probabilityLeftBetter >= request.decisionThreshold
      ? `${request.left.name} likely better`
      : "no clear winner";
  const percent = formatNumber(request.level * 100);
  const tree = {
    kind: "statsDistribution",
    label: "BAYES-AB",
    children: [
      statsMetricNode(`${request.left.name} mean`, armA.mean),
      statsMetricNode(`${request.right.name} mean`, armB.mean),
      statsMetricNode("P(B>A)", probabilityRightBetter),
      statsMetricNode("lift", relativeLift),
    ],
  };

  return {
    mode: "statistics",
    tree,
    answer: `P(${request.right.name} > ${request.left.name}) = ${formatNumber(probabilityRightBetter)}, expected lift = ${formatPercent(relativeLift)}`,
    summary: "Bayesian A/B test",
    details: "Beta-binomial posterior comparison for two conversion rates",
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read A/B conversion data",
        expression: `${request.left.name}: ${formatNumber(request.left.successes)}/${formatNumber(request.left.trials)}; ${request.right.name}: ${formatNumber(request.right.successes)}/${formatNumber(request.right.trials)}`,
        detail: "Each arm is modeled as a binomial conversion rate with a beta prior.",
      },
      {
        title: "Update beta posteriors",
        expression: `${request.left.name}: Beta(${formatNumber(armA.alpha)}, ${formatNumber(armA.beta)}); ${request.right.name}: Beta(${formatNumber(armB.alpha)}, ${formatNumber(armB.beta)})`,
        detail: "Successes add to alpha; non-conversions add to beta.",
      },
      {
        title: "Compare posterior rates",
        expression: `P(${request.right.name} > ${request.left.name}) = ${formatNumber(probabilityRightBetter)}`,
        detail: "The solver integrates one beta posterior against the other arm's beta CDF.",
      },
      {
        title: "Estimate lift",
        expression: `difference = ${formatNumber(meanDifference)}, lift = ${formatPercent(relativeLift)}`,
        detail: "Expected lift compares posterior mean conversion rates.",
      },
      {
        title: "Build difference interval",
        expression: `${percent}% approx interval = [${formatNumber(differenceLower)}, ${formatNumber(differenceUpper)}]`,
        detail: "The difference interval uses a normal approximation from independent beta posterior variances.",
      },
      {
        title: "Make decision",
        expression: decision,
        detail: `A winner is called only when posterior probability exceeds ${formatNumber(request.decisionThreshold)}.`,
      },
    ],
    table: {
      headers: ["Arm", "Conversions", "Trials", "Posterior", "Mean", `${percent}% credible interval`],
      rows: [
        [request.left.name, formatNumber(request.left.successes), formatNumber(request.left.trials), `Beta(${formatNumber(armA.alpha)}, ${formatNumber(armA.beta)})`, formatNumber(armA.mean), `[${formatNumber(armA.lower)}, ${formatNumber(armA.upper)}]`],
        [request.right.name, formatNumber(request.right.successes), formatNumber(request.right.trials), `Beta(${formatNumber(armB.alpha)}, ${formatNumber(armB.beta)})`, formatNumber(armB.mean), `[${formatNumber(armB.lower)}, ${formatNumber(armB.upper)}]`],
      ],
    },
    artifacts: [
      [`${request.left.name} posterior mean`, formatNumber(armA.mean)],
      [`${request.right.name} posterior mean`, formatNumber(armB.mean)],
      [`P(${request.right.name} > ${request.left.name})`, formatNumber(probabilityRightBetter)],
      [`P(${request.left.name} > ${request.right.name})`, formatNumber(probabilityLeftBetter)],
      ["Expected absolute lift", formatNumber(meanDifference)],
      ["Expected relative lift", formatPercent(relativeLift)],
      [`${percent}% difference interval`, `[${formatNumber(differenceLower)}, ${formatNumber(differenceUpper)}]`],
      ["Decision threshold", formatNumber(request.decisionThreshold)],
      ["Decision", decision],
    ],
  };
}

function bayesianAbPosterior(arm, priorAlpha, priorBeta, level) {
  const alpha = priorAlpha + arm.successes;
  const beta = priorBeta + arm.trials - arm.successes;
  const meanValue = alpha / (alpha + beta);
  const variance = (alpha * beta) / (((alpha + beta) ** 2) * (alpha + beta + 1));
  const lowerTail = (1 - level) / 2;
  return {
    alpha,
    beta,
    mean: normalizeNumber(meanValue),
    variance,
    lower: normalizeNumber(inverseBetaCdf(lowerTail, alpha, beta)),
    upper: normalizeNumber(inverseBetaCdf(1 - lowerTail, alpha, beta)),
  };
}

function betaGreaterProbability(alphaRight, betaRight, alphaLeft, betaLeft) {
  const epsilon = 1e-6;
  const evaluator = (value) =>
    betaPdf(value, alphaRight, betaRight) * regularizedBeta(value, alphaLeft, betaLeft);
  return clampProbability(approximateDefiniteIntegral(evaluator, epsilon, 1 - epsilon, 800, "simpson").value);
}

function betaPdf(value, alpha, beta) {
  if (!(value > 0 && value < 1)) {
    return 0;
  }
  return Math.exp((alpha - 1) * Math.log(value) + (beta - 1) * Math.log(1 - value) - logBeta(alpha, beta));
}

function analyzeBayesianProportion(statement) {
  const request = parseBayesianProportionInput(statement);
  const posteriorAlpha = request.priorAlpha + request.successes;
  const posteriorBeta = request.priorBeta + request.trials - request.successes;
  const posteriorMean = posteriorAlpha / (posteriorAlpha + posteriorBeta);
  const posteriorMode = posteriorAlpha > 1 && posteriorBeta > 1
    ? (posteriorAlpha - 1) / (posteriorAlpha + posteriorBeta - 2)
    : Number.NaN;
  const lowerTail = (1 - request.level) / 2;
  const upperTail = 1 - lowerTail;
  const lower = inverseBetaCdf(lowerTail, posteriorAlpha, posteriorBeta);
  const upper = inverseBetaCdf(upperTail, posteriorAlpha, posteriorBeta);
  const percent = formatNumber(request.level * 100);
  const predictive = request.futureTrials > 0 && Number.isInteger(request.futureSuccesses)
    ? betaBinomialProbability(request.futureTrials, request.futureSuccesses, posteriorAlpha, posteriorBeta)
    : Number.NaN;
  const predictiveLabel = Number.isFinite(predictive)
    ? `P(X = ${request.futureSuccesses} of ${request.futureTrials})`
    : "";
  const tree = {
    kind: "statsDistribution",
    label: "BETA",
    children: [
      statsMetricNode("prior a", request.priorAlpha),
      statsMetricNode("prior b", request.priorBeta),
      statsMetricNode("post a", posteriorAlpha),
      statsMetricNode("post b", posteriorBeta),
    ],
  };

  return {
    mode: "statistics",
    tree,
    answer: `posterior Beta(${formatNumber(posteriorAlpha)}, ${formatNumber(posteriorBeta)}), mean = ${formatNumber(posteriorMean)}`,
    summary: "Bayesian proportion posterior",
    details: "Beta-binomial conjugate update",
    variables: [],
    metrics: treeMetrics(tree),
    steps: [
      {
        title: "Read prior and data",
        expression: `Beta(${formatNumber(request.priorAlpha)}, ${formatNumber(request.priorBeta)}), successes=${formatNumber(request.successes)}, n=${formatNumber(request.trials)}`,
        detail: "A beta prior is conjugate to binomial success-count data.",
      },
      {
        title: "Update posterior parameters",
        expression: `alpha'=${formatNumber(posteriorAlpha)}, beta'=${formatNumber(posteriorBeta)}`,
        detail: "Successes add to alpha; failures add to beta.",
      },
      {
        title: "Summarize posterior",
        expression: `mean=${formatNumber(posteriorMean)}, ${percent}% credible interval=[${formatNumber(lower)}, ${formatNumber(upper)}]`,
        detail: "The credible interval uses the beta posterior quantiles.",
      },
      ...(Number.isFinite(predictive)
        ? [{
            title: "Predict future successes",
            expression: `${predictiveLabel} = ${formatNumber(predictive)}`,
            detail: "The beta-binomial predictive distribution averages over posterior uncertainty.",
          }]
        : []),
    ],
    table: {
      headers: ["Quantity", "Value"],
      rows: [
        ["Prior alpha", formatNumber(request.priorAlpha)],
        ["Prior beta", formatNumber(request.priorBeta)],
        ["Successes", formatNumber(request.successes)],
        ["Failures", formatNumber(request.trials - request.successes)],
        ["Posterior alpha", formatNumber(posteriorAlpha)],
        ["Posterior beta", formatNumber(posteriorBeta)],
        ["Posterior mean", formatNumber(posteriorMean)],
        ["Posterior mode", Number.isFinite(posteriorMode) ? formatNumber(posteriorMode) : "undefined"],
        [`${percent}% credible interval`, `[${formatNumber(lower)}, ${formatNumber(upper)}]`],
        ...(Number.isFinite(predictive) ? [[predictiveLabel, formatNumber(predictive)]] : []),
      ],
    },
    artifacts: [
      ["Prior", `Beta(${formatNumber(request.priorAlpha)}, ${formatNumber(request.priorBeta)})`],
      ["Data", `${formatNumber(request.successes)} successes, ${formatNumber(request.trials - request.successes)} failures`],
      ["Posterior", `Beta(${formatNumber(posteriorAlpha)}, ${formatNumber(posteriorBeta)})`],
      ["Posterior mean", formatNumber(posteriorMean)],
      ["Posterior mode", Number.isFinite(posteriorMode) ? formatNumber(posteriorMode) : "undefined"],
      [`${percent}% credible interval`, `[${formatNumber(lower)}, ${formatNumber(upper)}]`],
      ...(Number.isFinite(predictive) ? [[predictiveLabel, formatNumber(predictive)]] : []),
    ],
  };
}

function analyzeNormalDistribution(statement) {
  const numbers = parseNumbers(statement);
  const meanValue = readNamedNumber(statement, ["mean", "mu"], numbers[0] ?? 0);
  const sdValue = readNamedNumber(statement, ["sd", "sigma", "std"], numbers.length >= 3 ? numbers[1] : 1);
  const xValue = readNamedNumber(statement, ["x", "value"], numbers.length >= 3 ? numbers[2] : numbers[0]);

  if (!Number.isFinite(xValue)) {
    throw new Error("Normal distribution needs a value, such as normal mean=0 sd=1 x=1.96.");
  }
  if (!(sdValue > 0)) {
    throw new Error("Normal distribution needs a positive standard deviation.");
  }

  const request = parseContinuousDistributionRequest(statement, xValue);
  const z = (request.x - meanValue) / sdValue;
  const leftTail = normalCdf(z);
  const rightTail = 1 - leftTail;
  const probability = continuousDistributionProbability(
    leftTail,
    request,
    (value) => normalCdf((value - meanValue) / sdValue),
  );
  const label = continuousProbabilityLabel("X", request);

  return {
    mode: "statistics",
    tree: {
      kind: "statsDistribution",
      label: "NORMAL",
      children: [
        statsMetricNode("mu", meanValue),
        statsMetricNode("sd", sdValue),
        statsMetricNode("x", request.x),
        statsMetricNode("z", z),
      ],
    },
    answer: `${label} = ${formatNumber(probability)}`,
    summary: "normal probability",
    details: "Continuous probability distribution",
    variables: [],
    metrics: treeMetrics({
      kind: "statsDistribution",
      children: [statsMetricNode("mu", meanValue), statsMetricNode("sd", sdValue), statsMetricNode("x", request.x)],
    }),
    steps: [
      {
        title: "Read normal parameters",
        expression: `mean = ${formatNumber(meanValue)}, sd = ${formatNumber(sdValue)}, x = ${formatNumber(request.x)}`,
        detail: "A normal model uses a mean and standard deviation.",
      },
      {
        title: "Convert to z-score",
        expression: `z = (x - mean) / sd = ${formatNumber(z)}`,
        detail: "The z-score measures how many standard deviations x is from the mean.",
      },
      {
        title: "Evaluate normal CDF",
        expression: `P(X <= ${formatNumber(request.x)}) = ${formatNumber(leftTail)}`,
        detail: "The cumulative distribution function gives left-tail probability.",
      },
    ],
    artifacts: [
      ["z-score", formatNumber(z)],
      [`P(X <= ${formatNumber(request.x)})`, formatNumber(leftTail)],
      [`P(X > ${formatNumber(request.x)})`, formatNumber(rightTail)],
      ...(request.between ? [[label, formatNumber(probability)]] : []),
    ],
    graph: buildContinuousDistributionGraph({
      expression: `Normal(mu=${formatNumber(meanValue)}, sd=${formatNumber(sdValue)})`,
      request,
      pdf: (value) => normalPdf((value - meanValue) / sdValue) / sdValue,
      baseXMin: meanValue - 4 * sdValue,
      baseXMax: meanValue + 4 * sdValue,
      areaLabel: label,
    }),
  };
}

