function isInequalityQuestion(question) {
  const withoutLogicArrows = question.replace(/<->|<=>|->|=>/g, "");
  return /<=|>=|<|>|\u2264|\u2265/.test(withoutLogicArrows);
}

function looksLikeMathExpression(question) {
  return /[a-zA-Z0-9)]\s*[\+\-\*\/\^]\s*[-a-zA-Z0-9(]/.test(question);
}

function extractDerivativeQuestion(question) {
  const dMatch = question.match(/d\s*\/\s*d([A-Za-z_]\w*)\s+(.+)/i);
  if (dMatch) {
    return {
      variable: dMatch[1],
      expression: dMatch[2].replace(/[?!.]+$/, "").trim(),
    };
  }

  const wordMatch = question.match(/(?:derivative of|differentiate)\s+(.+?)(?:\s+with respect to\s+([A-Za-z_]\w*))?[?!.]*$/i);
  if (wordMatch) {
    return {
      variable: wordMatch[2] ?? "x",
      expression: wordMatch[1].trim(),
    };
  }

  return {
    variable: "x",
    expression: cleanSimplifyQuestion(question),
  };
}

function parseMultivariableInput(statement) {
  let text = statement
    .replace(/^(?:find|compute|calculate)\s+(?:the\s+)?/i, "")
    .replace(/[?!.]+$/, "")
    .trim();
  const lower = text.toLowerCase();
  const operation = lower.includes("directional derivative")
    ? "directional"
    : lower.includes("gradient")
      ? "gradient"
      : "partial";
  let variable = "x";

  const directPartialMatch = text.match(/^partial\s+(?!derivative\b)([A-Za-z_]\w*)\s+of\s+(.+)$/i);
  if (directPartialMatch) {
    variable = directPartialMatch[1];
    text = directPartialMatch[2];
  } else {
    const variableMatch = text.match(/\b(?:with respect to|wrt|for)\s+([A-Za-z_]\w*)\b/i) ??
      text.match(/\bd\s*\/\s*d([A-Za-z_]\w*)\b/i);
    if (variableMatch) {
      variable = variableMatch[1];
    }
  }

  const direction = operation === "directional" ? (extractVectors(text)[0] ?? []) : [];
  const point = parsePointAssignments(text);
  const expression = cleanMultivariableExpression(text);
  if (!expression) {
    throw new Error("Use a multivariable expression, such as gradient x^2 + x*y + y^2 at x=1 y=2.");
  }

  return {
    operation,
    expression,
    variable,
    point,
    direction,
    variables: Object.keys(point).sort(),
  };
}

function cleanMultivariableExpression(text) {
  return text
    .replace(/^partial\s+derivative\s+(?:of\s+)?/i, "")
    .replace(/^gradient\s+(?:of\s+)?/i, "")
    .replace(/^directional\s+derivative\s+(?:of\s+)?/i, "")
    .replace(/\b(?:with respect to|wrt|for)\s+[A-Za-z_]\w*\b/gi, "")
    .replace(/\bd\s*\/\s*d[A-Za-z_]\w*\b/gi, "")
    .replace(/\bdirection(?:al)?(?:\s+vector)?\s*\[[^\]]+\]/gi, "")
    .replace(/\[[^\]]+\]/g, "")
    .replace(/\bat\b.*$/i, "")
    .replace(/\bpoint\b.*$/i, "")
    .replace(/\b[A-Za-z_]\w*\s*=\s*[-+]?\d*\.?\d+(?:e[-+]?\d+)?/gi, "")
    .replace(/^of\s+/i, "")
    .replace(/\s+/g, " ")
    .trim();
}

function parsePointAssignments(text) {
  const point = {};
  const pointMatch = text.match(/\b(?:at|point)\b(.+)$/i);
  const segment = pointMatch ? pointMatch[1] : text;
  for (const match of segment.matchAll(/\b([A-Za-z_]\w*)\s*=\s*([-+]?\d*\.?\d+(?:e[-+]?\d+)?)/gi)) {
    point[match[1]] = Number(match[2]);
  }
  return point;
}

function extractTaylorQuestion(question, fallbackVariable) {
  let text = question
    .replace(/^(taylor|maclaurin)\s+(?:polynomial|series|expansion)?\s*/i, "")
    .replace(/^(find|compute|calculate)\s+(?:the\s+)?(?:taylor|maclaurin)\s+(?:polynomial|series|expansion)\s+(?:of\s+)?/i, "")
    .replace(/[?!.]+$/, "")
    .trim();
  const lower = question.toLowerCase();
  let center = lower.includes("maclaurin") ? 0 : Number.NaN;
  let variable = fallbackVariable;
  let order = 5;

  const orderMatch = text.match(/\b(?:order|degree|through degree)\s*=?\s*(\d+)\b/i);
  if (orderMatch) {
    order = Number(orderMatch[1]);
    text = text.replace(orderMatch[0], "").trim();
  }

  const aroundMatch = text.match(/\b(?:around|center(?:ed)? at|about|at)\s+([A-Za-z_]\w*\s*=\s*)?([-+]?\d*\.?\d+(?:e[-+]?\d+)?)\b/i);
  if (aroundMatch) {
    center = Number(aroundMatch[2]);
    if (aroundMatch[1]) {
      variable = aroundMatch[1].replace(/=/g, "").trim();
    }
    text = text.replace(aroundMatch[0], "").trim();
  }

  const variableMatch = text.match(/\b(?:with respect to|wrt|for)\s+([A-Za-z_]\w*)\b/i);
  if (variableMatch) {
    variable = variableMatch[1];
    text = text.replace(variableMatch[0], "").trim();
  }

  if (!Number.isFinite(center)) {
    center = 0;
  }
  if (!Number.isInteger(order) || order < 0 || order > 8) {
    throw new Error("Taylor mode supports integer degrees from 0 through 8.");
  }

  text = text
    .replace(/^of\s+/i, "")
    .replace(/^f\s*\([A-Za-z_]\w*\)\s*=\s*/i, "")
    .replace(/^y\s*=\s*/i, "")
    .trim();

  if (!text) {
    throw new Error("Use a Taylor request such as taylor sin(x) order=5.");
  }

  return {
    expression: text,
    variable,
    center,
    order,
  };
}

function extractLaplaceQuestion(question) {
  let text = question
    .replace(/^(find|compute|calculate)\s+(?:the\s+)?/i, "")
    .replace(/^laplace\s+(?:transform\s+)?(?:of\s+)?/i, "")
    .replace(/^transform\s+laplace\s+(?:of\s+)?/i, "")
    .replace(/[?!.]+$/, "")
    .trim();
  let variable = "";
  let outputVariable = "s";

  const outputMatch = text.match(/\b(?:to|into|output)\s+([A-Za-z_]\w*)\b/i);
  if (outputMatch) {
    outputVariable = outputMatch[1];
    text = text.replace(outputMatch[0], "").trim();
  }

  const variableMatch = text.match(/\b(?:with respect to|wrt|for)\s+([A-Za-z_]\w*)\b/i);
  if (variableMatch) {
    variable = variableMatch[1];
    text = text.replace(variableMatch[0], "").trim();
  }

  text = text
    .replace(/^of\s+/i, "")
    .replace(/^f\s*\([A-Za-z_]\w*\)\s*=\s*/i, "")
    .replace(/^y\s*=\s*/i, "")
    .trim();

  if (!text) {
    throw new Error("Laplace transform needs a function, such as laplace transform of sin(t) + 2t.");
  }

  return {
    expression: text,
    variable,
    outputVariable,
  };
}

function cleanLogicQuestion(question) {
  return question
    .replace(/^(is|check|evaluate|determine)\s+/i, "")
    .replace(/[?!.]+$/, "")
    .trim();
}

function cleanLogicSimplificationQuestion(question) {
  return question
    .replace(/^(simplify\s+(?:logic|boolean)|(?:logic|boolean)\s+simplify)\s+/i, "")
    .replace(/[?!.]+$/, "")
    .trim();
}

function extractLogicNormalFormQuestion(question) {
  const form = readLogicNormalFormTarget(question);
  const formPattern = "(?:nnf|cnf|dnf|negation\\s+normal\\s+form|conjunctive\\s+normal\\s+form|disjunctive\\s+normal\\s+form|normal\\s+forms?|normal\\s+form)";
  const expression = question
    .replace(/[?!.]+$/, "")
    .replace(/\b(?:convert|transform|rewrite|write|put|find|compute|show)\b/gi, " ")
    .replace(/\b(?:logic|boolean|propositional)\b/gi, " ")
    .replace(new RegExp(`\\b(?:to|in|as|into)\\s+${formPattern}\\b`, "gi"), " ")
    .replace(new RegExp(`\\b${formPattern}\\b`, "gi"), " ")
    .replace(/^\s*(?:of|for)\s+/i, "")
    .replace(/\s+/g, " ")
    .trim();

  if (!expression) {
    throw new Error("Logic normal-form mode needs a statement, such as cnf P -> (Q and R).");
  }
  return { form, expression };
}

function extractLogicSatQuestion(question) {
  const expression = question
    .replace(/[?!.]+$/, "")
    .replace(/\b(?:using|with|via)\s+dpll\b/gi, " ")
    .replace(/^(?:check|determine|decide|test|solve|find|show)\s+(?:if|whether)?\s*/i, "")
    .replace(/^(?:is|whether)\s+/i, "")
    .replace(/^(?:dpll|sat(?:\s+solver)?|boolean\s+sat|propositional\s+sat|satisfiability|satisfiable)\s*:?\s*/i, "")
    .replace(/\b(?:is|are)\s+satisfiable\b/gi, " ")
    .replace(/\b(?:sat\s+solver|satisfiability|satisfiable|dpll)\b/gi, " ")
    .replace(/^\s*(?:of|for)\s+/i, "")
    .replace(/\s+/g, " ")
    .trim();

  if (!expression) {
    throw new Error("SAT mode needs a logic statement, such as sat (P or Q) and not R.");
  }
  return { expression };
}

function extractLogicTableauQuestion(question) {
  const lower = question.toLowerCase();
  const goal = /\b(?:unsatisfiable|inconsistent|contradiction|contradictory)\b/.test(lower)
    ? "unsatisfiable"
    : /\b(?:satisfiable|satisfiability|sat|model|consistent)\b/.test(lower)
      ? "satisfiable"
      : "validity";
  const expression = question
    .replace(/[?!.]+$/, "")
    .replace(/\b(?:using|with|via)\s+(?:semantic\s+)?tableaux?\b/gi, " ")
    .replace(/^(?:check|determine|decide|test|solve|find|show|prove)\s+(?:if|whether)?\s*/i, "")
    .replace(/^(?:is|whether)\s+/i, "")
    .replace(/^(?:(?:semantic\s+)?tableaux?|truth\s+tree)\s*:?\s*/i, "")
    .replace(/\b(?:semantic\s+)?tableaux?\b/gi, " ")
    .replace(/\btruth\s+tree\b/gi, " ")
    .replace(/\b(?:valid|invalid|tautology|satisfiable|satisfiability|sat|model|consistent|unsatisfiable|inconsistent|contradiction|contradictory|countermodel)\b/gi, " ")
    .replace(/^\s*(?:of|for)\s+/i, "")
    .replace(/\s+/g, " ")
    .trim();

  if (!expression) {
    throw new Error("Tableau mode needs a logic statement, such as tableau P -> P.");
  }
  return { goal, expression };
}

function extractLogicKarnaughMapQuestion(question) {
  const { text, minterms } = extractKarnaughDontCareClause(question);
  const expression = text
    .replace(/[?!.]+$/, "")
    .replace(/^(?:make|build|draw|create|show|solve|simplify|minimize)\s+(?:a\s+)?/i, "")
    .replace(/^(?:karnaugh\s+map|k-map|kmap|boolean\s+map)\s*:?\s*/i, "")
    .replace(/\b(?:using|with|via)\s+(?:a\s+)?(?:karnaugh\s+map|k-map|kmap)\b/gi, " ")
    .replace(/\b(?:karnaugh\s+map|k-map|kmap|boolean\s+map)\b/gi, " ")
    .replace(/\b(?:logic|boolean|propositional|expression|statement)\b/gi, " ")
    .replace(/^\s*(?:of|for)\s+/i, "")
    .replace(/\s+/g, " ")
    .trim();

  if (!expression) {
    throw new Error("Karnaugh-map mode needs a Boolean statement, such as kmap P or Q.");
  }
  return { expression, dontCareMinterms: minterms };
}

function extractKarnaughDontCareClause(question) {
  const trimmedQuestion = question.replace(/[?!.]+$/, "");
  const patterns = [
    /\b(?:with\s+)?(?:don'?t|dont|do\s+not)[-\s]?care(?:s)?(?:\s+(?:cells?|minterms?))?\s*(?:=|:)?\s*([mx\d,\s]+)$/i,
    /\b(?:dc|dcs|x)\s*(?:=|:)\s*([mx\d,\s]+)$/i,
  ];
  for (const pattern of patterns) {
    const match = trimmedQuestion.match(pattern);
    if (match) {
      return {
        text: trimmedQuestion.slice(0, match.index).trim(),
        minterms: parseKarnaughMintermList(match[1]),
      };
    }
  }
  return { text: trimmedQuestion, minterms: [] };
}

function parseKarnaughMintermList(text) {
  return uniqueSortedNumbers(
    [...text.matchAll(/\b[mx]?\s*(\d+)\b/gi)].map((match) => Number(match[1])),
  );
}

function extractLogicBddQuestion(question) {
  const expression = question
    .replace(/[?!.]+$/, "")
    .replace(/^(?:build|make|create|show|compute|reduce|draw)\s+(?:a\s+)?/i, "")
    .replace(/^(?:reduced\s+ordered\s+)?(?:binary\s+decision\s+diagram|bdd|robdd|ordered\s+bdd)\s*:?\s*/i, "")
    .replace(/\b(?:using|with|via)\s+(?:a\s+)?(?:reduced\s+ordered\s+)?(?:binary\s+decision\s+diagram|bdd|robdd|ordered\s+bdd)\b/gi, " ")
    .replace(/\b(?:reduced\s+ordered\s+binary\s+decision\s+diagram|binary\s+decision\s+diagram|ordered\s+bdd|robdd|bdd)\b/gi, " ")
    .replace(/\b(?:logic|boolean|propositional|expression|statement)\b/gi, " ")
    .replace(/^\s*(?:of|for)\s+/i, "")
    .replace(/\s+/g, " ")
    .trim();

  if (!expression) {
    throw new Error("BDD mode needs a logic statement, such as bdd (P and Q) or (P and R).");
  }
  return { expression };
}

function extractLogicTruthValueQuestion(question) {
  const lower = question.toLowerCase();
  const kind = /\b(?:probabilistic logic|probability logic|prob logic|independent probability)\b/.test(lower)
    ? "probability"
    : "fuzzy";
  const values = parseSoftLogicAssignments(question);
  const expression = question
    .replace(/[?!.]+$/, "")
    .replace(/\b[A-Za-z_]\w*\s*(?:=|:)\s*[-+]?\d*\.?\d+(?:e[-+]?\d+)?\s*%?/gi, " ")
    .replace(/^(?:evaluate|compute|calculate|find|show)\s+(?:the\s+)?/i, "")
    .replace(/^(?:fuzzy\s+logic|fuzzy|soft\s+logic|graded\s+truth|truth\s+values?|probabilistic\s+logic|probability\s+logic|prob\s+logic)\s*:?\s*/i, "")
    .replace(/\b(?:using|with|given|where|values?|truth\s+values?|degrees?)\b/gi, " ")
    .replace(/\b(?:fuzzy\s+logic|soft\s+logic|fuzzy|graded\s+truth|probabilistic\s+logic|probability\s+logic|prob\s+logic|independent\s+probability)\b/gi, " ")
    .replace(/\b(?:logic|boolean|propositional|expression|statement)\b/gi, " ")
    .replace(/^\s*(?:of|for)\s+/i, "")
    .replace(/\s+/g, " ")
    .trim();

  if (!expression) {
    throw new Error("Graded logic needs a statement, such as fuzzy logic P and Q with P=0.8 Q=0.4.");
  }
  return { kind, expression, values };
}

function extractTreeExportQuestion(question) {
  const expression = question
    .replace(/[?!.]+$/, "")
    .replace(/^(?:show|make|build|create|draw|generate|export)\s+(?:a\s+)?/i, "")
    .replace(/^(?:graphviz\s+)?(?:parse\s+)?tree\s*:?\s*/i, "")
    .replace(/^(?:dot\s+tree|tree\s+dot|expression\s+tree|parse\s+tree)\s*:?\s*/i, "")
    .replace(/\b(?:as|to|into|in)\s+(?:graphviz\s+)?dot\b/gi, " ")
    .replace(/\b(?:graphviz|dot)\s+(?:parse\s+)?tree\b/gi, " ")
    .replace(/\b(?:parse|expression)\s+tree\s+(?:graphviz|dot|export)\b/gi, " ")
    .replace(/^\s*(?:of|for)\s+/i, "")
    .replace(/\s+/g, " ")
    .trim();

  if (!expression) {
    throw new Error("Tree export needs a math or logic expression, such as dot tree x^2 + 2x + 1.");
  }
  return { expression };
}

function readLogicNormalFormTarget(question) {
  const lower = question.toLowerCase();
  if (/\bcnf\b/.test(lower) || lower.includes("conjunctive normal form")) return "cnf";
  if (/\bdnf\b/.test(lower) || lower.includes("disjunctive normal form")) return "dnf";
  if (/\bnnf\b/.test(lower) || lower.includes("negation normal form")) return "nnf";
  return "all";
}

function cleanEquationQuestion(question) {
  return question
    .replace(/^(solve|find|calculate|compute)\s+/i, "")
    .replace(/\s+for\s+[A-Za-z_]\w*\s*$/i, "")
    .replace(/[?!.]+$/, "")
    .trim();
}

function cleanSystemQuestion(question) {
  return question
    .replace(/^(solve|find|calculate|compute)\s+/i, "")
    .replace(/\bnonlinear\s+equations?\s*:?\s*/i, "")
    .replace(/\bsystem\s*(?:of equations)?\s*:?\s*/i, "")
    .replace(/\bsimultaneous equations\s*:?\s*/i, "")
    .replace(/[?!.]+$/, "")
    .trim();
}

function stripNonlinearSystemOptions(text) {
  return text
    .replace(/\b(?:tol|tolerance|maxIterations|maxiterations|maxIter|maxiter|iterations)\s*=\s*[-+]?\d*\.?\d+(?:e[-+]?\d+)?/gi, "")
    .replace(/\b(?:guess|initial|start|near)\b.*$/i, "")
    .replace(/\bnonlinear\b/gi, "")
    .replace(/[;\s]+$/g, "")
    .trim();
}

function cleanSimplifyQuestion(question) {
  return question
    .replace(/^(simplify|combine like terms|calculate|compute|what is|find)\s+/i, "")
    .replace(/[?!.]+$/, "")
    .trim();
}

function extractExplicitTrigIdentityQuestion(statement) {
  const lower = statement.toLowerCase();
  const isPowerReduction = /\bpower[-\s]?reduc(?:e|tion)\b/.test(lower);
  const isHalfAngle = /\bhalf[-\s]?angle\b/.test(lower);
  if (!isPowerReduction && !isHalfAngle) {
    return null;
  }

  const kind = isPowerReduction ? "power-reduction" : "half-angle";
  const label = isPowerReduction ? "power-reduction identity" : "half-angle identity";
  const example = isPowerReduction ? "power reduce sin(x)^2" : "half angle sin(x/2)";
  const expression = statement
    .replace(/[?!.]+$/, "")
    .replace(/\b(?:use|using|apply|rewrite|convert|transform|with|by|via|the|identity|identities)\b/gi, " ")
    .replace(/\bpower[-\s]?reduc(?:e|tion)\b/gi, " ")
    .replace(/\bhalf[-\s]?angle\b/gi, " ")
    .replace(/^\s*of\s+/i, "")
    .replace(/\s+/g, " ")
    .trim();

  if (!expression) {
    throw new Error(`${label} needs an expression, such as ${example}.`);
  }
  return { kind, label, example, expression };
}

function cleanComplexQuestion(question) {
  return question
    .replace(/[?!.]+$/, "")
    .replace(/^(evaluate|calculate|compute|simplify|what is)\s+(?:the\s+)?/i, "")
    .replace(/^complex\s+(?:number|expression|arithmetic)?\s*/i, "")
    .trim();
}

function cleanFactorQuestion(question) {
  return question
    .replace(/^(factorize|factorise|fully factor|factor)\s+(?:the\s+)?/i, "")
    .replace(/[?!.]+$/, "")
    .trim();
}

function extractInequalityQuestion(question) {
  const cleaned = question
    .replace(/^(solve|find|calculate|compute)\s+/i, "")
    .replace(/^inequality\s*:?\s*/i, "")
    .replace(/[?!.]+$/, "")
    .trim();
  const match = cleaned.match(/(<=|>=|<|>|\u2264|\u2265)/);
  if (!match) {
    throw new Error("Use an inequality such as x^2 - 5x + 6 > 0.");
  }

  const operator = match[1] === "\u2264" ? "<=" : match[1] === "\u2265" ? ">=" : match[1];
  const left = cleaned.slice(0, match.index).trim();
  const right = cleaned.slice(match.index + match[0].length).trim();
  if (!left || !right) {
    throw new Error("Inequality mode needs expressions on both sides of the comparison.");
  }

  return { left, operator, right };
}

function formatSigned(value) {
  if (value < 0) {
    return `- ${formatNumber(Math.abs(value))}`;
  }
  return `+ ${formatNumber(value)}`;
}

export function parseLogic(statement) {
  return new LogicParser(tokenizeLogic(statement)).parse();
}

function tokenizeLogic(statement) {
  const tokens = [];
  let index = 0;

  while (index < statement.length) {
    const char = statement[index];

    if (/\s/.test(char)) {
      index += 1;
      continue;
    }

    const symbol = matchLogicSymbol(statement, index);
    if (symbol) {
      tokens.push({
        kind: "OP",
        value: LOGIC_SYMBOL_OPERATORS.get(symbol),
        position: index,
      });
      index += symbol.length;
      continue;
    }

    if (char === "(") {
      tokens.push({ kind: "LPAREN", value: char, position: index });
      index += 1;
      continue;
    }

    if (char === ")") {
      tokens.push({ kind: "RPAREN", value: char, position: index });
      index += 1;
      continue;
    }

    if (/[A-Za-z_]/.test(char)) {
      const start = index;
      index += 1;
      while (index < statement.length && /[A-Za-z0-9_]/.test(statement[index])) {
        index += 1;
      }

      const word = statement.slice(start, index);
      const lower = word.toLowerCase();
      if (lower === "true" || lower === "false") {
        tokens.push({ kind: "CONST", value: lower, position: start });
      } else if (LOGIC_WORD_OPERATORS.has(lower)) {
        tokens.push({
          kind: "OP",
          value: LOGIC_WORD_OPERATORS.get(lower),
          position: start,
        });
      } else {
        tokens.push({ kind: "VAR", value: word, position: start });
      }
      continue;
    }

    throw new Error(`Unexpected character '${char}' at position ${index}.`);
  }

  tokens.push({ kind: "EOF", value: "", position: statement.length });
  return tokens;
}

function matchLogicSymbol(statement, index) {
  for (const symbol of LOGIC_SYMBOL_OPERATORS.keys()) {
    if (statement.startsWith(symbol, index)) {
      return symbol;
    }
  }
  return null;
}

class LogicParser {
  constructor(tokens) {
    this.tokens = tokens;
    this.index = 0;
  }

  parse() {
    const expression = this.parseIff();
    if (!this.is("EOF")) {
      const token = this.current();
      throw new Error(`Unexpected token '${token.value}' at position ${token.position}.`);
    }
    return expression;
  }

  parseIff() {
    let expression = this.parseImplies();
    while (this.matchOp("IFF")) {
      expression = logicBinary("iff", expression, this.parseImplies());
    }
    return expression;
  }

  parseImplies() {
    const expression = this.parseOr();
    if (this.matchOp("IMPLIES")) {
      return logicBinary("implies", expression, this.parseImplies());
    }
    return expression;
  }

  parseOr() {
    let expression = this.parseXor();
    while (this.matchOp("OR")) {
      expression = logicBinary("or", expression, this.parseXor());
    }
    return expression;
  }

  parseXor() {
    let expression = this.parseAnd();
    while (this.matchOp("XOR")) {
      expression = logicBinary("xor", expression, this.parseAnd());
    }
    return expression;
  }

  parseAnd() {
    let expression = this.parseNot();
    while (this.matchOp("AND")) {
      expression = logicBinary("and", expression, this.parseNot());
    }
    return expression;
  }

  parseNot() {
    if (this.matchOp("NOT")) {
      return { kind: "logicNot", operand: this.parseNot() };
    }
    return this.parseAtom();
  }

  parseAtom() {
    const token = this.current();
    if (this.match("CONST")) {
      return { kind: "logicConstant", value: token.value === "true" };
    }
    if (this.match("VAR")) {
      return { kind: "logicVariable", name: token.value };
    }
    if (this.match("LPAREN")) {
      const expression = this.parseIff();
      if (!this.match("RPAREN")) {
        throw new Error(`Expected ')' before position ${this.current().position}.`);
      }
      return expression;
    }
    throw new Error(`Expected expression at position ${token.position}.`);
  }

  current() {
    return this.tokens[this.index];
  }

  is(kind, value = null) {
    const token = this.current();
    return token.kind === kind && (value === null || token.value === value);
  }

  match(kind, value = null) {
    if (!this.is(kind, value)) {
      return false;
    }
    this.index += 1;
    return true;
  }

  matchOp(operator) {
    return this.match("OP", operator);
  }
}

function logicBinary(operator, left, right) {
  return { kind: "logicBinary", operator, left, right };
}

export function evaluateLogic(node, assignment) {
  switch (node.kind) {
    case "logicConstant":
      return node.value;
    case "logicVariable":
      return Boolean(assignment[node.name]);
    case "logicNot":
      return !evaluateLogic(node.operand, assignment);
    case "logicBinary": {
      const left = evaluateLogic(node.left, assignment);
      const right = evaluateLogic(node.right, assignment);
      if (node.operator === "and") return left && right;
      if (node.operator === "or") return left || right;
      if (node.operator === "xor") return left !== right;
      if (node.operator === "implies") return !left || right;
      if (node.operator === "iff") return left === right;
      throw new Error(`Unknown logic operator '${node.operator}'.`);
    }
    default:
      throw new Error(`Unknown logic node '${node.kind}'.`);
  }
}

export function logicVariables(node, names = new Set()) {
  if (node.kind === "logicVariable") {
    names.add(node.name);
  }
  for (const child of nodeChildren(node)) {
    logicVariables(child, names);
  }
  return [...names].sort();
}

function logicTruthTable(node) {
  const names = logicVariables(node);
  return booleanAssignments(names).map((assignment) => ({
    assignment,
    result: evaluateLogic(node, assignment),
  }));
}

function classifyLogic(rows) {
  const trueRows = rows.filter((row) => row.result).length;
  const falseRows = rows.length - trueRows;
  let name = "contingency";
  if (trueRows === rows.length) name = "tautology";
  if (falseRows === rows.length) name = "contradiction";
  return { name, trueRows, falseRows, totalRows: rows.length };
}

function booleanAssignments(names) {
  const rows = [];
  const total = 2 ** names.length;
  for (let mask = 0; mask < total; mask += 1) {
    const assignment = {};
    names.forEach((name, index) => {
      const bit = names.length - index - 1;
      assignment[name] = Boolean(mask & (1 << bit));
    });
    rows.push(assignment);
  }
  return rows;
}

function findLogicCounterexample(left, right) {
  const names = [...new Set([...logicVariables(left), ...logicVariables(right)])].sort();
  for (const assignment of booleanAssignments(names)) {
    if (evaluateLogic(left, assignment) !== evaluateLogic(right, assignment)) {
      return assignment;
    }
  }
  return null;
}

function simplifyLogicNode(node, steps = []) {
  if (node.kind === "logicConstant" || node.kind === "logicVariable") {
    return node;
  }

  if (node.kind === "logicNot") {
    const operand = simplifyLogicNode(node.operand, steps);
    if (operand.kind === "logicConstant") {
      const result = { kind: "logicConstant", value: !operand.value };
      steps.push({
        title: "Apply Boolean constant rule",
        expression: `not ${formatTruth(operand.value)} = ${formatTruth(result.value)}`,
        detail: "The negation of a constant truth value can be evaluated immediately.",
      });
      return result;
    }
    if (operand.kind === "logicNot") {
      steps.push({
        title: "Apply double-negation law",
        expression: `not not ${logicToString(operand.operand)} = ${logicToString(operand.operand)}`,
        detail: "Two negations cancel each other.",
      });
      return operand.operand;
    }
    if (operand.kind === "logicBinary" && (operand.operator === "and" || operand.operator === "or")) {
      const operator = operand.operator === "and" ? "or" : "and";
      const result = logicBinary(
        operator,
        simplifyLogicNode({ kind: "logicNot", operand: operand.left }, steps),
        simplifyLogicNode({ kind: "logicNot", operand: operand.right }, steps),
      );
      steps.push({
        title: "Apply De Morgan's law",
        expression: `not (${logicToString(operand)}) = ${logicToString(result)}`,
        detail: "Negation distributes across and/or while flipping the operator.",
      });
      return result;
    }
    return { kind: "logicNot", operand };
  }

  const left = simplifyLogicNode(node.left, steps);
  const right = simplifyLogicNode(node.right, steps);
  if (node.operator === "and") return simplifyLogicAnd(left, right, steps);
  if (node.operator === "or") return simplifyLogicOr(left, right, steps);
  if (node.operator === "xor") return simplifyLogicXor(left, right, steps);
  if (node.operator === "implies") return simplifyLogicImplies(left, right, steps);
  if (node.operator === "iff") return simplifyLogicIff(left, right, steps);
  return logicBinary(node.operator, left, right);
}

function simplifyLogicAnd(left, right, steps) {
  if (sameLogicTree(left, right)) {
    steps.push({
      title: "Apply idempotent law",
      expression: `${logicToString(left)} and ${logicToString(right)} = ${logicToString(left)}`,
      detail: "Repeating the same term with AND does not change the result.",
    });
    return left;
  }
  if (isLogicNegationOf(left, right)) {
    steps.push({
      title: "Apply complement law",
      expression: `${logicToString(left)} and ${logicToString(right)} = false`,
      detail: "A statement and its negation cannot both be true.",
    });
    return logicConstant(false);
  }
  if (isLogicConstant(left, false) || isLogicConstant(right, false)) return logicConstant(false);
  if (isLogicConstant(left, true)) return right;
  if (isLogicConstant(right, true)) return left;
  const absorption = simplifyLogicAbsorption(left, right, "and", steps);
  if (absorption) return absorption;
  const complementaryPair = simplifyLogicComplementaryPair(left, right, "and", steps);
  if (complementaryPair) return complementaryPair;
  return logicBinary("and", left, right);
}

function simplifyLogicOr(left, right, steps) {
  if (sameLogicTree(left, right)) {
    steps.push({
      title: "Apply idempotent law",
      expression: `${logicToString(left)} or ${logicToString(right)} = ${logicToString(left)}`,
      detail: "Repeating the same term with OR does not change the result.",
    });
    return left;
  }
  if (isLogicNegationOf(left, right)) {
    steps.push({
      title: "Apply complement law",
      expression: `${logicToString(left)} or ${logicToString(right)} = true`,
      detail: "A statement or its negation is always true.",
    });
    return logicConstant(true);
  }
  if (isLogicConstant(left, true) || isLogicConstant(right, true)) return logicConstant(true);
  if (isLogicConstant(left, false)) return right;
  if (isLogicConstant(right, false)) return left;
  const absorption = simplifyLogicAbsorption(left, right, "or", steps);
  if (absorption) return absorption;
  const complementaryPair = simplifyLogicComplementaryPair(left, right, "or", steps);
  if (complementaryPair) return complementaryPair;
  const consensus = simplifyLogicConsensus(left, right, steps);
  if (consensus) return consensus;
  return logicBinary("or", left, right);
}

function simplifyLogicXor(left, right, steps) {
  if (sameLogicTree(left, right)) return logicConstant(false);
  if (isLogicConstant(left, false)) return right;
  if (isLogicConstant(right, false)) return left;
  if (isLogicConstant(left, true)) return simplifyLogicNode({ kind: "logicNot", operand: right }, steps);
  if (isLogicConstant(right, true)) return simplifyLogicNode({ kind: "logicNot", operand: left }, steps);
  return logicBinary("xor", left, right);
}

function simplifyLogicImplies(left, right, steps) {
  if (sameLogicTree(left, right)) return logicConstant(true);
  if (isLogicConstant(left, false) || isLogicConstant(right, true)) return logicConstant(true);
  if (isLogicConstant(left, true)) return right;
  if (isLogicConstant(right, false)) return simplifyLogicNode({ kind: "logicNot", operand: left }, steps);
  return logicBinary("implies", left, right);
}

function simplifyLogicIff(left, right, steps) {
  if (sameLogicTree(left, right)) return logicConstant(true);
  if (isLogicConstant(left, true)) return right;
  if (isLogicConstant(right, true)) return left;
  if (isLogicConstant(left, false)) return simplifyLogicNode({ kind: "logicNot", operand: right }, steps);
  if (isLogicConstant(right, false)) return simplifyLogicNode({ kind: "logicNot", operand: left }, steps);
  return logicBinary("iff", left, right);
}

function logicConstant(value) {
  return { kind: "logicConstant", value };
}

function isLogicConstant(node, value) {
  return node.kind === "logicConstant" && node.value === value;
}

function isLogicNegationOf(left, right) {
  return (left.kind === "logicNot" && sameLogicTree(left.operand, right)) ||
    (right.kind === "logicNot" && sameLogicTree(right.operand, left));
}

function simplifyLogicAbsorption(left, right, operator, steps) {
  const innerOperator = operator === "and" ? "or" : "and";
  const leftAbsorbs = logicTermIncludes(right, left, innerOperator);
  if (leftAbsorbs) {
    steps.push({
      title: "Apply absorption law",
      expression: `${logicToString(left)} ${operator} ${logicToString(right)} = ${logicToString(left)}`,
      detail: "A term absorbs a larger clause that already contains that term.",
    });
    return left;
  }

  const rightAbsorbs = logicTermIncludes(left, right, innerOperator);
  if (rightAbsorbs) {
    steps.push({
      title: "Apply absorption law",
      expression: `${logicToString(left)} ${operator} ${logicToString(right)} = ${logicToString(right)}`,
      detail: "A term absorbs a larger clause that already contains that term.",
    });
    return right;
  }

  return null;
}

function simplifyLogicComplementaryPair(left, right, operator, steps) {
  const innerOperator = operator === "and" ? "or" : "and";
  const leftParts = flattenLogicOperator(left, innerOperator);
  const rightParts = flattenLogicOperator(right, innerOperator);
  for (let leftIndex = 0; leftIndex < leftParts.length; leftIndex += 1) {
    const leftPart = leftParts[leftIndex];
    const rightIndex = rightParts.findIndex((part) => isLogicNegationOf(leftPart, part));
    if (rightIndex === -1) {
      continue;
    }

    const remainingLeft = leftParts.filter((_, index) => index !== leftIndex);
    const remainingRight = rightParts.filter((_, index) => index !== rightIndex);
    if (!sameLogicTermMultiset(remainingLeft, remainingRight)) {
      continue;
    }

    const reduced = logicTreeFromTerms(remainingLeft, innerOperator);
    steps.push({
      title: "Apply complementary-pair reduction",
      expression: `${logicToString(left)} ${operator} ${logicToString(right)} = ${logicToString(reduced)}`,
      detail: "Two clauses that differ only by a complemented term reduce to their shared part.",
    });
    return reduced;
  }

  return null;
}

function sameLogicTermMultiset(leftTerms, rightTerms) {
  if (leftTerms.length !== rightTerms.length) {
    return false;
  }
  const used = Array(rightTerms.length).fill(false);
  for (const leftTerm of leftTerms) {
    const matchIndex = rightTerms.findIndex((rightTerm, index) =>
      !used[index] && sameLogicTree(leftTerm, rightTerm),
    );
    if (matchIndex === -1) {
      return false;
    }
    used[matchIndex] = true;
  }
  return true;
}

function simplifyLogicConsensus(left, right, steps) {
  const terms = flattenLogicOperator(logicBinary("or", left, right), "or");
  if (terms.length < 3) {
    return null;
  }

  for (let firstIndex = 0; firstIndex < terms.length; firstIndex += 1) {
    for (let secondIndex = firstIndex + 1; secondIndex < terms.length; secondIndex += 1) {
      const consensus = consensusTerm(terms[firstIndex], terms[secondIndex]);
      if (!consensus) {
        continue;
      }
      const consensusIndex = terms.findIndex((term, index) =>
        index !== firstIndex &&
        index !== secondIndex &&
        sameLogicTree(term, consensus),
      );
      if (consensusIndex === -1) {
        continue;
      }

      const reducedTerms = terms.filter((_, index) => index !== consensusIndex);
      const reduced = logicTreeFromTerms(reducedTerms, "or");
      steps.push({
        title: "Apply consensus theorem",
        expression: `${logicToString(logicTreeFromTerms(terms, "or"))} = ${logicToString(reduced)}`,
        detail: "The consensus term is redundant when both complementary product terms are present.",
      });
      return reduced;
    }
  }

  return null;
}

function consensusTerm(left, right) {
  const leftFactors = flattenLogicOperator(left, "and");
  const rightFactors = flattenLogicOperator(right, "and");
  if (leftFactors.length < 2 || rightFactors.length < 2) {
    return null;
  }

  for (const leftFactor of leftFactors) {
    for (const rightFactor of rightFactors) {
      if (!isLogicNegationOf(leftFactor, rightFactor)) {
        continue;
      }
      const remainingLeft = leftFactors.filter((factor) => factor !== leftFactor);
      const remainingRight = rightFactors.filter((factor) => factor !== rightFactor);
      const consensusFactors = [];
      for (const factor of [...remainingLeft, ...remainingRight]) {
        if (consensusFactors.every((existing) => !sameLogicTree(existing, factor))) {
          consensusFactors.push(factor);
        }
      }
      return logicTreeFromTerms(consensusFactors, "and");
    }
  }
  return null;
}

function logicTermIncludes(container, contained, operator) {
  const containerParts = flattenLogicOperator(container, operator);
  const containedParts = flattenLogicOperator(contained, operator);
  return containedParts.every((part) =>
    containerParts.some((candidate) => sameLogicTree(candidate, part)),
  );
}

function flattenLogicOperator(node, operator) {
  if (node.kind === "logicBinary" && node.operator === operator) {
    return [
      ...flattenLogicOperator(node.left, operator),
      ...flattenLogicOperator(node.right, operator),
    ];
  }
  return [node];
}

function logicTreeFromTerms(terms, operator) {
  if (terms.length === 0) {
    return logicConstant(operator === "and");
  }
  return terms.reduce((tree, term) => tree ? logicBinary(operator, tree, term) : term, null);
}

function buildLogicNormalForms(tree, steps = []) {
  const primitive = eliminateLogicDerivedOperators(tree);
  steps.push({
    title: "Eliminate derived connectives",
    expression: logicToString(primitive),
    detail: "Implication, biconditional, and XOR are rewritten with only AND, OR, and NOT.",
  });

  const nnfRaw = logicNegationNormalForm(primitive);
  steps.push({
    title: "Push negations inward",
    expression: logicToString(nnfRaw),
    detail: "De Morgan's laws move every negation down to a variable or constant.",
  });
  const nnf = simplifyLogicNode(nnfRaw, steps);

  const cnfRaw = logicConjunctiveNormalForm(nnf);
  steps.push({
    title: "Distribute OR over AND",
    expression: logicToString(cnfRaw),
    detail: "CNF is an AND of OR clauses, so OR is distributed across nested AND groups.",
  });
  const cnf = simplifyLogicNode(cnfRaw, steps);

  const dnfRaw = logicDisjunctiveNormalForm(nnf);
  steps.push({
    title: "Distribute AND over OR",
    expression: logicToString(dnfRaw),
    detail: "DNF is an OR of AND terms, so AND is distributed across nested OR groups.",
  });
  const dnf = simplifyLogicNode(dnfRaw, steps);

  return { nnf, cnf, dnf };
}

function logicCnfClauses(cnf) {
  if (cnf.kind === "logicConstant") {
    return cnf.value ? [] : [[]];
  }
  const clauseNodes = flattenLogicOperator(cnf, "and");
  const clauses = [];
  for (const node of clauseNodes) {
    const clause = logicClauseLiterals(node);
    if (clause === null) {
      continue;
    }
    clauses.push(clause);
  }
  return clauses;
}

function logicClauseLiterals(node) {
  if (node.kind === "logicConstant") {
    return node.value ? null : [];
  }
  const literalNodes = flattenLogicOperator(node, "or");
  const byName = new Map();

  for (const literalNode of literalNodes) {
    if (literalNode.kind === "logicConstant") {
      if (literalNode.value) return null;
      continue;
    }
    const literal = logicLiteralFromNode(literalNode);
    const existing = byName.get(literal.name);
    if (existing !== undefined && existing !== literal.positive) {
      return null;
    }
    byName.set(literal.name, literal.positive);
  }

  return [...byName.entries()]
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([name, positive]) => ({ name, positive }));
}

function logicLiteralFromNode(node) {
  if (node.kind === "logicVariable") {
    return { name: node.name, positive: true };
  }
  if (node.kind === "logicNot" && node.operand.kind === "logicVariable") {
    return { name: node.operand.name, positive: false };
  }
  throw new Error("CNF clause extraction expected literals only.");
}

function solveDpllClauses(clauses, variables) {
  const stats = {
    decisions: 0,
    unitPropagations: 0,
    pureLiteralAssignments: 0,
    nodes: 0,
  };
  const trace = [];
  const search = dpllSearch(clauses, {}, variables, stats, trace);
  const assignment = search.satisfiable
    ? completeDpllAssignment(search.assignment, variables)
    : {};
  return {
    satisfiable: search.satisfiable,
    assignment,
    variables,
    stats,
    trace,
  };
}

function findUnsatCoreClauses(clauses, variables) {
  if (clauses.length === 0) {
    return [];
  }

  let core = clauses.map((clause, index) => ({ clause, index }));
  let changed = true;
  while (changed) {
    changed = false;
    for (let index = 0; index < core.length; index += 1) {
      const candidate = core.filter((_, candidateIndex) => candidateIndex !== index);
      const result = solveDpllClauses(candidate.map((entry) => entry.clause), variables);
      if (!result.satisfiable) {
        core = candidate;
        changed = true;
        index -= 1;
      }
    }
  }

  return core;
}

function dpllSearch(clauses, assignment, variables, stats, trace) {
  stats.nodes += 1;
  const propagated = propagateDpllClauses(clauses, assignment, stats, trace);
  if (propagated.conflict) {
    return { satisfiable: false, assignment: propagated.assignment };
  }
  if (propagated.clauses.length === 0) {
    addDpllTrace(trace, "all clauses satisfied", propagated.assignment);
    return { satisfiable: true, assignment: propagated.assignment };
  }

  const decision = chooseDpllLiteral(propagated.clauses, variables, propagated.assignment);
  if (!decision) {
    return { satisfiable: false, assignment: propagated.assignment };
  }

  stats.decisions += 1;
  for (const value of [decision.preferred, !decision.preferred]) {
    const branchAssignment = {
      ...propagated.assignment,
      [decision.name]: value,
    };
    addDpllTrace(trace, `branch ${decision.name}=${formatTruth(value)}`, branchAssignment);
    const result = dpllSearch(clauses, branchAssignment, variables, stats, trace);
    if (result.satisfiable) {
      return result;
    }
  }

  addDpllTrace(trace, `backtrack ${decision.name}`, propagated.assignment);
  return { satisfiable: false, assignment: propagated.assignment };
}

function propagateDpllClauses(clauses, baseAssignment, stats, trace) {
  let assignment = { ...baseAssignment };
  while (true) {
    const simplified = simplifyDpllClauses(clauses, assignment);
    if (simplified.some((clause) => clause.length === 0)) {
      addDpllTrace(trace, "empty clause conflict", assignment);
      return { conflict: true, assignment, clauses: simplified };
    }
    if (simplified.length === 0) {
      return { conflict: false, assignment, clauses: simplified };
    }

    const unit = simplified.find((clause) => clause.length === 1)?.[0];
    if (unit) {
      const assigned = assignDpllLiteral(assignment, unit);
      if (!assigned.ok) {
        addDpllTrace(trace, "unit conflict", assignment);
        return { conflict: true, assignment, clauses: simplified };
      }
      assignment = assigned.assignment;
      stats.unitPropagations += 1;
      addDpllTrace(trace, `unit ${formatDpllLiteral(unit)}`, assignment);
      continue;
    }

    const pure = findPureDpllLiteral(simplified, assignment);
    if (pure) {
      const assigned = assignDpllLiteral(assignment, pure);
      assignment = assigned.assignment;
      stats.pureLiteralAssignments += 1;
      addDpllTrace(trace, `pure ${formatDpllLiteral(pure)}`, assignment);
      continue;
    }

    return { conflict: false, assignment, clauses: simplified };
  }
}

function simplifyDpllClauses(clauses, assignment) {
  const simplified = [];
  for (const clause of clauses) {
    let satisfied = false;
    const unresolved = [];
    for (const literal of clause) {
      const value = assignment[literal.name];
      if (value === undefined) {
        unresolved.push(literal);
      } else if (value === literal.positive) {
        satisfied = true;
        break;
      }
    }
    if (!satisfied) {
      simplified.push(unresolved);
    }
  }
  return simplified;
}

function assignDpllLiteral(assignment, literal) {
  const value = literal.positive;
  if (assignment[literal.name] !== undefined && assignment[literal.name] !== value) {
    return { ok: false, assignment };
  }
  return {
    ok: true,
    assignment: {
      ...assignment,
      [literal.name]: value,
    },
  };
}

function findPureDpllLiteral(clauses, assignment) {
  const signs = new Map();
  for (const clause of clauses) {
    for (const literal of clause) {
      if (assignment[literal.name] !== undefined) continue;
      const current = signs.get(literal.name) ?? { positive: false, negative: false };
      if (literal.positive) {
        current.positive = true;
      } else {
        current.negative = true;
      }
      signs.set(literal.name, current);
    }
  }

  for (const [name, sign] of [...signs.entries()].sort(([left], [right]) => left.localeCompare(right))) {
    if (sign.positive !== sign.negative) {
      return { name, positive: sign.positive };
    }
  }
  return null;
}

function chooseDpllLiteral(clauses, variables, assignment) {
  const scores = new Map();
  for (const clause of clauses) {
    for (const literal of clause) {
      if (assignment[literal.name] !== undefined) continue;
      const score = scores.get(literal.name) ?? { positive: 0, negative: 0 };
      if (literal.positive) {
        score.positive += 1;
      } else {
        score.negative += 1;
      }
      scores.set(literal.name, score);
    }
  }

  let best = null;
  for (const name of variables) {
    const score = scores.get(name);
    if (!score) continue;
    const total = score.positive + score.negative;
    const candidate = {
      name,
      total,
      preferred: score.positive >= score.negative,
    };
    if (!best || candidate.total > best.total || (candidate.total === best.total && candidate.name < best.name)) {
      best = candidate;
    }
  }
  return best;
}

function completeDpllAssignment(assignment, variables) {
  const completed = {};
  for (const name of variables) {
    completed[name] = Boolean(assignment[name] ?? false);
  }
  return completed;
}

function addDpllTrace(trace, action, assignment) {
  if (trace.length >= 40) {
    return;
  }
  trace.push({ action, assignment: { ...assignment } });
}

function formatDpllClause(clause) {
  if (clause.length === 0) {
    return "empty";
  }
  return clause.map(formatDpllLiteral).join(" or ");
}

function formatUnsatCoreClause(entry) {
  return `#${entry.index + 1}: ${formatDpllClause(entry.clause)}`;
}

function formatDpllLiteral(literal) {
  return literal.positive ? literal.name : `not ${literal.name}`;
}

function solveSemanticTableau(rootFormula, variables) {
  const branches = [{
    id: 1,
    formulas: [{ ...rootFormula, expanded: false }],
    closed: false,
    reason: "",
  }];
  const trace = [];
  let nextBranchId = 2;
  let expansions = 0;
  let guard = 0;

  while (guard < 160) {
    guard += 1;
    const branch = branches.find((candidate) => !candidate.closed && selectTableauFormula(candidate));
    if (!branch) {
      break;
    }

    const selected = selectTableauFormula(branch);
    selected.expanded = true;
    const rule = decomposeTableauFormula(selected);
    if (rule.kind === "literal" || rule.kind === "noop") {
      const closure = closeTableauBranchIfNeeded(branch);
      if (closure) {
        addTableauTrace(trace, branch.id, "close", closure);
      }
      continue;
    }
    if (rule.kind === "close") {
      branch.closed = true;
      branch.reason = rule.reason;
      addTableauTrace(trace, branch.id, "close", rule.reason);
      continue;
    }

    expansions += 1;
    if (rule.kind === "alpha") {
      for (const formula of rule.formulas) {
        addTableauFormula(branch, formula);
      }
      addTableauTrace(
        trace,
        branch.id,
        rule.label,
        rule.formulas.map(formatSignedFormula).join("; "),
      );
      const closure = closeTableauBranchIfNeeded(branch);
      if (closure) {
        addTableauTrace(trace, branch.id, "close", closure);
      }
      continue;
    }

    const baseFormulas = branch.formulas.map((formula) => ({ ...formula }));
    const createdIds = [branch.id];
    for (const [index, formulas] of rule.branches.entries()) {
      const target = index === 0
        ? branch
        : {
            id: nextBranchId++,
            formulas: baseFormulas.map((formula) => ({ ...formula })),
            closed: false,
            reason: "",
          };
      for (const formula of formulas) {
        addTableauFormula(target, formula);
      }
      const closure = closeTableauBranchIfNeeded(target);
      if (closure) {
        addTableauTrace(trace, target.id, "close", closure);
      }
      if (index > 0) {
        branches.push(target);
      }
      createdIds[index] = target.id;
    }
    addTableauTrace(
      trace,
      branch.id,
      rule.label,
      rule.branches
        .map((formulas, index) => `B${createdIds[index]}: ${formulas.map(formatSignedFormula).join("; ")}`)
        .join(" | "),
    );
  }

  for (const branch of branches) {
    if (!branch.closed) {
      closeTableauBranchIfNeeded(branch);
    }
  }

  const openBranches = branches.filter((branch) => !branch.closed);
  const model = openBranches.length
    ? tableauBranchModel(openBranches[0], variables)
    : null;
  return {
    branches: branches.sort((left, right) => left.id - right.id),
    branchCount: branches.length,
    closedBranches: branches.length - openBranches.length,
    openBranches: openBranches.length,
    allClosed: openBranches.length === 0,
    model,
    variables,
    trace,
    expansions,
  };
}

function selectTableauFormula(branch) {
  return branch.formulas.find((formula) => !formula.expanded);
}

function decomposeTableauFormula(formula) {
  const { sign, node } = formula;
  if (node.kind === "logicConstant") {
    if ((sign && !node.value) || (!sign && node.value)) {
      return { kind: "close", reason: `${formatSignedFormula(formula)} is impossible` };
    }
    return { kind: "noop" };
  }
  if (node.kind === "logicVariable") {
    return { kind: "literal" };
  }
  if (node.kind === "logicNot") {
    return {
      kind: "alpha",
      label: `${formatSignedFormula(formula)} negation`,
      formulas: [{ sign: !sign, node: node.operand }],
    };
  }
  if (node.kind === "logicBinary" && node.operator === "and") {
    return sign
      ? {
          kind: "alpha",
          label: `${formatSignedFormula(formula)} alpha`,
          formulas: [
            { sign: true, node: node.left },
            { sign: true, node: node.right },
          ],
        }
      : {
          kind: "beta",
          label: `${formatSignedFormula(formula)} beta`,
          branches: [
            [{ sign: false, node: node.left }],
            [{ sign: false, node: node.right }],
          ],
        };
  }
  if (node.kind === "logicBinary" && node.operator === "or") {
    return sign
      ? {
          kind: "beta",
          label: `${formatSignedFormula(formula)} beta`,
          branches: [
            [{ sign: true, node: node.left }],
            [{ sign: true, node: node.right }],
          ],
        }
      : {
          kind: "alpha",
          label: `${formatSignedFormula(formula)} alpha`,
          formulas: [
            { sign: false, node: node.left },
            { sign: false, node: node.right },
          ],
        };
  }
  throw new Error("Tableau expansion expects primitive logic operators.");
}

function addTableauFormula(branch, formula) {
  const key = tableauFormulaKey(formula);
  if (branch.formulas.some((candidate) => tableauFormulaKey(candidate) === key)) {
    return;
  }
  branch.formulas.push({ ...formula, expanded: false });
}

function closeTableauBranchIfNeeded(branch) {
  const assignments = new Map();
  for (const formula of branch.formulas) {
    if (formula.node.kind === "logicConstant") {
      if ((formula.sign && !formula.node.value) || (!formula.sign && formula.node.value)) {
        branch.closed = true;
        branch.reason = `${formatSignedFormula(formula)} is impossible`;
        return branch.reason;
      }
      continue;
    }
    if (formula.node.kind !== "logicVariable") {
      continue;
    }
    const existing = assignments.get(formula.node.name);
    if (existing !== undefined && existing !== formula.sign) {
      branch.closed = true;
      branch.reason = `${formula.node.name} is both true and false`;
      return branch.reason;
    }
    assignments.set(formula.node.name, formula.sign);
  }
  return "";
}

function tableauBranchModel(branch, variables) {
  const assignment = {};
  for (const formula of branch.formulas) {
    if (formula.node.kind === "logicVariable") {
      assignment[formula.node.name] = formula.sign;
    }
  }
  const completed = {};
  for (const name of variables) {
    completed[name] = Boolean(assignment[name] ?? false);
  }
  return completed;
}

function formatTableauBranchLiterals(branch) {
  const literals = branch.formulas
    .filter((formula) => formula.node.kind === "logicVariable")
    .sort((left, right) => left.node.name.localeCompare(right.node.name) || Number(right.sign) - Number(left.sign))
    .map(formatSignedFormula);
  return literals.length ? literals.join(", ") : "none";
}

function formatSignedFormula(formula) {
  return `${formula.sign ? "T" : "F"} ${logicToString(formula.node)}`;
}

function tableauFormulaKey(formula) {
  return `${formula.sign ? "T" : "F"}:${logicToString(formula.node)}`;
}

function addTableauTrace(trace, branchId, rule, result) {
  if (trace.length >= 60) {
    return;
  }
  trace.push({ branchId, rule, result });
}

function normalizeKarnaughDontCareMinterms(minterms, variables) {
  const limit = 2 ** variables.length;
  const normalized = uniqueSortedNumbers(minterms ?? []);
  const invalid = normalized.find((minterm) =>
    !Number.isSafeInteger(minterm) || minterm < 0 || minterm >= limit,
  );
  if (invalid !== undefined) {
    throw new Error(`Karnaugh don't-care minterm ${invalid} is outside 0 through ${limit - 1}.`);
  }
  return normalized;
}

function buildKarnaughMap(tree, variables, requestedDontCareMinterms = []) {
  const rowCount = Math.floor(variables.length / 2);
  const rowVariables = variables.slice(0, rowCount);
  const columnVariables = variables.slice(rowCount);
  const rowCodes = grayCodes(rowVariables.length);
  const columnCodes = grayCodes(columnVariables.length);
  const requestedDontCares = new Set(requestedDontCareMinterms);
  const rows = rowCodes.map((rowCode) => ({
    code: rowCode,
    label: formatKarnaughAxis(rowVariables, rowCode),
    cells: columnCodes.map((columnCode) => {
      const assignment = assignmentFromKarnaughCodes(rowVariables, rowCode, columnVariables, columnCode);
      const value = evaluateLogic(tree, assignment);
      const minterm = karnaughMintermIndex(assignment, variables);
      return {
        assignment,
        value,
        dontCare: !value && requestedDontCares.has(minterm),
        minterm,
      };
    }),
  }));
  const minterms = rows
    .flatMap((row) => row.cells)
    .filter((cell) => cell.value)
    .map((cell) => cell.minterm)
    .sort((left, right) => left - right);
  const dontCareMinterms = rows
    .flatMap((row) => row.cells)
    .filter((cell) => cell.dontCare)
    .map((cell) => cell.minterm)
    .sort((left, right) => left - right);
  const primeGroups = findKarnaughPrimeGroups(rows);

  return {
    rowVariables,
    columnVariables,
    rowLabels: rows.map((row) => row.label),
    columnLabels: columnCodes.map((code) => formatKarnaughAxis(columnVariables, code)),
    rows,
    minterms,
    dontCareMinterms,
    primeGroups,
  };
}

function grayCodes(bits) {
  const count = 2 ** bits;
  const codes = [];
  for (let value = 0; value < count; value += 1) {
    const gray = value ^ (value >> 1);
    codes.push(gray.toString(2).padStart(bits, "0"));
  }
  return codes;
}

function assignmentFromKarnaughCodes(rowVariables, rowCode, columnVariables, columnCode) {
  const assignment = {};
  rowVariables.forEach((name, index) => {
    assignment[name] = rowCode[index] === "1";
  });
  columnVariables.forEach((name, index) => {
    assignment[name] = columnCode[index] === "1";
  });
  return assignment;
}

function formatKarnaughAxis(variables, code) {
  return variables.map((name, index) => `${name}=${code[index]}`).join(", ");
}

function karnaughMintermIndex(assignment, variables) {
  return variables.reduce((index, name) => index * 2 + (assignment[name] ? 1 : 0), 0);
}

function findKarnaughPrimeGroups(rows) {
  const rowTotal = rows.length;
  const columnTotal = rows[0]?.cells.length ?? 0;
  const trueCells = rows.flatMap((row) => row.cells).filter((cell) => cell.value);
  if (trueCells.length === 0) {
    return [];
  }

  const rowSizes = powersOfTwoUpTo(rowTotal);
  const columnSizes = powersOfTwoUpTo(columnTotal);
  const groupsByKey = new Map();

  for (const height of rowSizes) {
    for (const width of columnSizes) {
      for (let rowStart = 0; rowStart < rowTotal; rowStart += 1) {
        for (let columnStart = 0; columnStart < columnTotal; columnStart += 1) {
          const cells = [];
          const seenCells = new Set();
          for (let rowOffset = 0; rowOffset < height; rowOffset += 1) {
            for (let columnOffset = 0; columnOffset < width; columnOffset += 1) {
              const rowIndex = (rowStart + rowOffset) % rowTotal;
              const columnIndex = (columnStart + columnOffset) % columnTotal;
              const key = `${rowIndex},${columnIndex}`;
              if (seenCells.has(key)) continue;
              seenCells.add(key);
              cells.push(rows[rowIndex].cells[columnIndex]);
            }
          }
          if (
            cells.length !== height * width ||
            cells.some((cell) => !cell.value && !cell.dontCare) ||
            cells.every((cell) => !cell.value)
          ) {
            continue;
          }
          const minterms = cells.map((cell) => cell.minterm).sort((left, right) => left - right);
          const requiredMinterms = cells
            .filter((cell) => cell.value)
            .map((cell) => cell.minterm)
            .sort((left, right) => left - right);
          const dontCareMinterms = cells
            .filter((cell) => cell.dontCare)
            .map((cell) => cell.minterm)
            .sort((left, right) => left - right);
          const key = minterms.join(",");
          groupsByKey.set(key, {
            cells: cells.slice().sort((left, right) => left.minterm - right.minterm),
            allMinterms: minterms,
            minterms: requiredMinterms,
            dontCareMinterms,
            size: cells.length,
          });
        }
      }
    }
  }

  const groups = [...groupsByKey.values()];
  return groups
    .filter((group) => !groups.some((other) =>
      other !== group &&
      other.size > group.size &&
      isKarnaughGroupSubset(group, other),
    ))
    .sort(compareKarnaughGroups);
}

function powersOfTwoUpTo(limit) {
  const sizes = [];
  for (let value = 1; value <= limit; value *= 2) {
    sizes.push(value);
  }
  return sizes;
}

function isKarnaughGroupSubset(left, right) {
  const rightMinterms = new Set(right.allMinterms ?? right.minterms);
  return (left.allMinterms ?? left.minterms).every((minterm) => rightMinterms.has(minterm));
}

function selectKarnaughGroups(groups, minterms, variables) {
  if (minterms.length === 0) {
    return [];
  }
  const selected = [];
  const covered = new Set();
  const byMinterm = new Map(minterms.map((minterm) => [minterm, []]));
  for (const group of groups) {
    for (const minterm of group.minterms) {
      if (byMinterm.has(minterm)) {
        byMinterm.get(minterm).push(group);
      }
    }
  }

  for (const minterm of minterms) {
    const candidates = byMinterm.get(minterm) ?? [];
    if (candidates.length === 1) {
      addSelectedKarnaughGroup(selected, covered, candidates[0]);
    }
  }

  while (minterms.some((minterm) => !covered.has(minterm))) {
    const best = groups
      .filter((group) => group.minterms.some((minterm) => !covered.has(minterm)))
      .sort((left, right) => compareKarnaughCoverChoice(left, right, covered, variables))[0];
    if (!best) {
      break;
    }
    addSelectedKarnaughGroup(selected, covered, best);
  }

  return selected.sort((left, right) =>
    karnaughGroupTerm(left, variables).localeCompare(karnaughGroupTerm(right, variables)) ||
    compareKarnaughGroups(left, right),
  );
}

function addSelectedKarnaughGroup(selected, covered, group) {
  if (!selected.includes(group)) {
    selected.push(group);
  }
  for (const minterm of group.minterms) {
    covered.add(minterm);
  }
}

function compareKarnaughCoverChoice(left, right, covered, variables) {
  const leftNew = left.minterms.filter((minterm) => !covered.has(minterm)).length;
  const rightNew = right.minterms.filter((minterm) => !covered.has(minterm)).length;
  if (leftNew !== rightNew) return rightNew - leftNew;
  if (left.size !== right.size) return right.size - left.size;
  const leftLiteralCount = karnaughGroupTermLiteralCount(left, variables);
  const rightLiteralCount = karnaughGroupTermLiteralCount(right, variables);
  if (leftLiteralCount !== rightLiteralCount) return leftLiteralCount - rightLiteralCount;
  return compareKarnaughGroups(left, right);
}

function compareKarnaughGroups(left, right) {
  if (left.size !== right.size) return right.size - left.size;
  return left.minterms.join(",").localeCompare(right.minterms.join(","));
}

function karnaughGroupTerm(group, variables) {
  const pieces = [];
  for (const name of variables) {
    const values = new Set(group.cells.map((cell) => cell.assignment[name]));
    if (values.size === 1) {
      pieces.push(values.has(true) ? name : `not ${name}`);
    }
  }
  return pieces.length ? pieces.join(" and ") : "true";
}

function karnaughGroupTermLiteralCount(group, variables) {
  const term = karnaughGroupTerm(group, variables);
  if (term === "true") return 0;
  return term.split(" and ").length;
}

function formatKarnaughSimplified(groups, minterms, variables) {
  if (minterms.length === 0) {
    return "false";
  }
  if (minterms.length === 2 ** variables.length) {
    return "true";
  }
  const terms = groups.map((group) => karnaughGroupTerm(group, variables));
  if (terms.includes("true")) {
    return "true";
  }
  return terms.join(" or ") || "false";
}

function formatKarnaughGroup(group, variables) {
  return `${formatKarnaughGroupCells(group, ",")} -> ${karnaughGroupTerm(group, variables)}`;
}

function formatKarnaughMinterms(minterms, separator) {
  return minterms.length ? minterms.map((minterm) => `m${minterm}`).join(separator) : "none";
}

function formatKarnaughDontCares(minterms, separator) {
  return minterms.length ? minterms.map((minterm) => `x${minterm}`).join(separator) : "none";
}

function formatKarnaughGroupCells(group, separator) {
  const cells = group.cells ?? [];
  return cells.length
    ? cells.map((cell) => cell.dontCare && !cell.value ? `x${cell.minterm}` : `m${cell.minterm}`).join(separator)
    : "none";
}

function formatKarnaughCell(cell) {
  if (cell.dontCare) {
    return `X m${cell.minterm}`;
  }
  return cell.value ? `1 m${cell.minterm}` : "0";
}

function buildReducedOrderedBdd(tree, variables) {
  const nodes = new Map();
  const unique = new Map();
  let nextId = 2;

  function build(index, assignment) {
    if (index >= variables.length) {
      return evaluateLogic(tree, assignment) ? 1 : 0;
    }

    const variable = variables[index];
    const low = build(index + 1, { ...assignment, [variable]: false });
    const high = build(index + 1, { ...assignment, [variable]: true });
    if (low === high) {
      return low;
    }

    const key = `${variable}|${low}|${high}`;
    const existing = unique.get(key);
    if (existing !== undefined) {
      return existing;
    }

    const id = nextId++;
    const node = { id, variable, low, high };
    unique.set(key, id);
    nodes.set(id, node);
    return id;
  }

  return {
    root: build(0, {}),
    nodes,
    variables,
  };
}

function evaluateBdd(bdd, assignment) {
  let current = bdd.root;
  while (current !== 0 && current !== 1) {
    const node = bdd.nodes.get(current);
    current = assignment[node.variable] ? node.high : node.low;
  }
  return current === 1;
}

function enumerateBddTruePaths(bdd, variables) {
  const paths = [];

  function visit(id, assignment) {
    if (id === 0) {
      return;
    }
    if (id === 1) {
      paths.push({ ...assignment });
      return;
    }

    const node = bdd.nodes.get(id);
    visit(node.low, { ...assignment, [node.variable]: false });
    visit(node.high, { ...assignment, [node.variable]: true });
  }

  visit(bdd.root, {});
  return paths.sort((left, right) => formatBddPath(left, variables).localeCompare(formatBddPath(right, variables)));
}

function bddNodeRows(bdd, decisionNodes) {
  return [
    ["T0", "false", "-", "-"],
    ["T1", "true", "-", "-"],
    ...decisionNodes.map((node) => [
      formatBddNodeId(node.id),
      node.variable,
      formatBddNodeId(node.low),
      formatBddNodeId(node.high),
    ]),
  ];
}

function formatBddPath(path, variables) {
  const assignments = variables
    .filter((variable) => path[variable] !== undefined)
    .map((variable) => `${variable}=${formatTruth(path[variable])}`);
  const skipped = variables
    .filter((variable) => path[variable] === undefined)
    .map((variable) => `${variable}=*`);
  return [...assignments, ...skipped].join(", ") || "all assignments";
}

function formatBddNodeId(id) {
  if (id === 0) return "T0";
  if (id === 1) return "T1";
  return `n${id}`;
}

function bddToGraphvizDot(bdd) {
  const nodes = [...bdd.nodes.values()].sort((left, right) => left.id - right.id);
  const lines = [
    "digraph BinaryDecisionDiagram {",
    "  graph [rankdir=TB, labelloc=\"t\", label=\"Reduced Ordered BDD\"];",
    "  node [fontname=\"Inter\"];",
    "  edge [fontname=\"Inter\"];",
    "  T0 [label=\"false\", shape=box, style=\"rounded,filled\", fillcolor=\"#fee2e2\"];",
    "  T1 [label=\"true\", shape=box, style=\"rounded,filled\", fillcolor=\"#dcfce7\"];",
  ];

  for (const node of nodes) {
    lines.push(`  ${formatBddNodeId(node.id)} [label="${escapeDotLabel(node.variable)}", shape=circle, style=filled, fillcolor="#eff6ff"];`);
  }
  for (const node of nodes) {
    lines.push(`  ${formatBddNodeId(node.id)} -> ${formatBddNodeId(node.low)} [label="0", style=dashed];`);
    lines.push(`  ${formatBddNodeId(node.id)} -> ${formatBddNodeId(node.high)} [label="1"];`);
  }
  lines.push("}");
  return lines.join("\n");
}

function parseSoftLogicAssignments(text) {
  const values = new Map();
  for (const match of text.matchAll(/\b([A-Za-z_]\w*)\s*(?:=|:)\s*([-+]?\d*\.?\d+(?:e[-+]?\d+)?)(\s*%)?/gi)) {
    const raw = Number(match[2]);
    const value = match[3] ? raw / 100 : raw;
    if (!Number.isFinite(value) || value < 0 || value > 1) {
      throw new Error(`Truth value for ${match[1]} must be between 0 and 1, or a percent from 0% to 100%.`);
    }
    values.set(match[1], normalizeNumber(value));
  }
  return values;
}

function resolveSoftLogicAssignments(variables, provided) {
  const assignment = {};
  for (const variable of variables) {
    if (provided.has(variable)) {
      assignment[variable] = provided.get(variable);
      continue;
    }
    const insensitive = [...provided.entries()].find(([name]) => name.toLowerCase() === variable.toLowerCase());
    if (insensitive) {
      assignment[variable] = insensitive[1];
      continue;
    }
    throw new Error(`Missing truth value for ${variable}. Add ${variable}=0.5 or another value from 0 to 1.`);
  }
  return assignment;
}

function evaluateSoftLogic(node, assignment, kind, trace) {
  if (node.kind === "logicConstant") {
    const value = node.value ? 1 : 0;
    trace.push({
      expression: logicToString(node),
      rule: "constant",
      value,
    });
    return value;
  }
  if (node.kind === "logicVariable") {
    const value = assignment[node.name];
    trace.push({
      expression: node.name,
      rule: "variable value",
      value,
    });
    return value;
  }
  if (node.kind === "logicNot") {
    const operand = evaluateSoftLogic(node.operand, assignment, kind, trace);
    const value = normalizeSoftTruth(1 - operand);
    trace.push({
      expression: logicToString(node),
      rule: `not: 1 - ${formatNumber(operand)}`,
      value,
    });
    return value;
  }

  const left = evaluateSoftLogic(node.left, assignment, kind, trace);
  const right = evaluateSoftLogic(node.right, assignment, kind, trace);
  const { value, rule } = kind === "probability"
    ? evaluateProbabilityLogicOperator(node.operator, left, right)
    : evaluateFuzzyLogicOperator(node.operator, left, right);
  trace.push({
    expression: logicToString(node),
    rule,
    value,
  });
  return value;
}

function evaluateFuzzyLogicOperator(operator, left, right) {
  if (operator === "and") {
    return { value: Math.min(left, right), rule: `and: min(${formatNumber(left)}, ${formatNumber(right)})` };
  }
  if (operator === "or") {
    return { value: Math.max(left, right), rule: `or: max(${formatNumber(left)}, ${formatNumber(right)})` };
  }
  if (operator === "xor") {
    return { value: normalizeSoftTruth(Math.abs(left - right)), rule: `xor: abs(${formatNumber(left)} - ${formatNumber(right)})` };
  }
  if (operator === "implies") {
    return { value: Math.max(1 - left, right), rule: `implies: max(1 - ${formatNumber(left)}, ${formatNumber(right)})` };
  }
  if (operator === "iff") {
    return { value: normalizeSoftTruth(1 - Math.abs(left - right)), rule: `iff: 1 - abs(${formatNumber(left)} - ${formatNumber(right)})` };
  }
  throw new Error(`Unsupported fuzzy operator '${operator}'.`);
}

function evaluateProbabilityLogicOperator(operator, left, right) {
  if (operator === "and") {
    return { value: normalizeSoftTruth(left * right), rule: `and: ${formatNumber(left)} * ${formatNumber(right)}` };
  }
  if (operator === "or") {
    return { value: normalizeSoftTruth(left + right - left * right), rule: `or: P(A)+P(B)-P(A)P(B)` };
  }
  if (operator === "xor") {
    return { value: normalizeSoftTruth(left * (1 - right) + (1 - left) * right), rule: "xor: P(A not B) + P(not A B)" };
  }
  if (operator === "implies") {
    return { value: normalizeSoftTruth(1 - left * (1 - right)), rule: "implies: 1 - P(A and not B)" };
  }
  if (operator === "iff") {
    return { value: normalizeSoftTruth(left * right + (1 - left) * (1 - right)), rule: "iff: P(both true) + P(both false)" };
  }
  throw new Error(`Unsupported probability operator '${operator}'.`);
}

function normalizeSoftTruth(value) {
  return Math.min(1, Math.max(0, normalizeNumber(value)));
}

function formatSoftAssignment(assignment) {
  return Object.entries(assignment)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([name, value]) => `${name}=${formatNumber(value)}`)
    .join(", ") || "none";
}

function parseTreeExportExpression(expression) {
  if (isLogicQuestion(expression)) {
    const tree = parseLogic(expression);
    return {
      type: "logic",
      tree,
      variables: logicVariables(tree),
    };
  }

  const tree = parseMath(expression);
  return {
    type: "math",
    tree,
    variables: mathVariables(tree),
  };
}

function treeToGraphvizDot(root, graphLabel = "Expression Tree") {
  const nodes = [];
  const edges = [];

  function visit(node) {
    const id = `n${nodes.length}`;
    const children = nodeChildren(node);
    const row = {
      id,
      label: nodeLabel(node),
      kind: node.kind,
      children: [],
    };
    nodes.push(row);

    children.forEach((child, index) => {
      const childId = visit(child);
      row.children.push(childId);
      edges.push({
        from: id,
        to: childId,
        label: String(index + 1),
      });
    });
    return id;
  }

  visit(root);
  const title = graphLabel === "logic"
    ? "Logic Expression Tree"
    : graphLabel === "math"
      ? "Math Expression Tree"
      : graphLabel;
  const lines = [
    "digraph ExpressionTree {",
    `  graph [rankdir=TB, labelloc="t", label="${escapeDotLabel(title)}"];`,
    "  node [shape=box, style=\"rounded,filled\", fillcolor=\"#f8fafc\", fontname=\"Inter\"];",
    "  edge [fontname=\"Inter\"];",
  ];
  for (const node of nodes) {
    lines.push(`  ${node.id} [label="${escapeDotLabel(node.label)}\\n${escapeDotLabel(node.kind)}"];`);
  }
  for (const edge of edges) {
    lines.push(`  ${edge.from} -> ${edge.to} [label="${escapeDotLabel(edge.label)}"];`);
  }
  lines.push("}");

  return {
    nodes,
    edges,
    text: lines.join("\n"),
    label: graphLabel,
  };
}

function escapeDotLabel(value) {
  return String(value)
    .replace(/\\/g, "\\\\")
    .replace(/"/g, "\\\"")
    .replace(/\r?\n/g, "\\n");
}

function eliminateLogicDerivedOperators(node) {
  if (node.kind === "logicConstant" || node.kind === "logicVariable") {
    return node;
  }
  if (node.kind === "logicNot") {
    return { kind: "logicNot", operand: eliminateLogicDerivedOperators(node.operand) };
  }

  const left = eliminateLogicDerivedOperators(node.left);
  const right = eliminateLogicDerivedOperators(node.right);
  if (node.operator === "and" || node.operator === "or") {
    return logicBinary(node.operator, left, right);
  }
  if (node.operator === "implies") {
    return logicBinary("or", { kind: "logicNot", operand: left }, right);
  }
  if (node.operator === "iff") {
    return logicBinary(
      "or",
      logicBinary("and", left, right),
      logicBinary("and", { kind: "logicNot", operand: left }, { kind: "logicNot", operand: right }),
    );
  }
  if (node.operator === "xor") {
    return logicBinary(
      "or",
      logicBinary("and", left, { kind: "logicNot", operand: right }),
      logicBinary("and", { kind: "logicNot", operand: left }, right),
    );
  }
  throw new Error(`Unknown logic operator '${node.operator}'.`);
}

function logicNegationNormalForm(node, negated = false) {
  if (node.kind === "logicConstant") {
    return logicConstant(negated ? !node.value : node.value);
  }
  if (node.kind === "logicVariable") {
    return negated ? { kind: "logicNot", operand: node } : node;
  }
  if (node.kind === "logicNot") {
    return logicNegationNormalForm(node.operand, !negated);
  }
  if (node.kind === "logicBinary" && (node.operator === "and" || node.operator === "or")) {
    const operator = negated
      ? node.operator === "and" ? "or" : "and"
      : node.operator;
    return logicBinary(
      operator,
      logicNegationNormalForm(node.left, negated),
      logicNegationNormalForm(node.right, negated),
    );
  }
  throw new Error("Negation normal form requires primitive logic operators.");
}

function logicConjunctiveNormalForm(node) {
  if (node.kind !== "logicBinary") {
    return node;
  }
  if (node.operator === "and") {
    return logicBinary("and", logicConjunctiveNormalForm(node.left), logicConjunctiveNormalForm(node.right));
  }
  if (node.operator === "or") {
    return distributeLogicOrOverAnd(
      logicConjunctiveNormalForm(node.left),
      logicConjunctiveNormalForm(node.right),
    );
  }
  return node;
}

function distributeLogicOrOverAnd(left, right) {
  if (left.kind === "logicBinary" && left.operator === "and") {
    return logicBinary(
      "and",
      distributeLogicOrOverAnd(left.left, right),
      distributeLogicOrOverAnd(left.right, right),
    );
  }
  if (right.kind === "logicBinary" && right.operator === "and") {
    return logicBinary(
      "and",
      distributeLogicOrOverAnd(left, right.left),
      distributeLogicOrOverAnd(left, right.right),
    );
  }
  return logicBinary("or", left, right);
}

function logicDisjunctiveNormalForm(node) {
  if (node.kind !== "logicBinary") {
    return node;
  }
  if (node.operator === "or") {
    return logicBinary("or", logicDisjunctiveNormalForm(node.left), logicDisjunctiveNormalForm(node.right));
  }
  if (node.operator === "and") {
    return distributeLogicAndOverOr(
      logicDisjunctiveNormalForm(node.left),
      logicDisjunctiveNormalForm(node.right),
    );
  }
  return node;
}

function distributeLogicAndOverOr(left, right) {
  if (left.kind === "logicBinary" && left.operator === "or") {
    return logicBinary(
      "or",
      distributeLogicAndOverOr(left.left, right),
      distributeLogicAndOverOr(left.right, right),
    );
  }
  if (right.kind === "logicBinary" && right.operator === "or") {
    return logicBinary(
      "or",
      distributeLogicAndOverOr(left, right.left),
      distributeLogicAndOverOr(left, right.right),
    );
  }
  return logicBinary("and", left, right);
}

function sameLogicTree(left, right) {
  if (left.kind !== right.kind) return false;
  if (left.kind === "logicConstant") return left.value === right.value;
  if (left.kind === "logicVariable") return left.name === right.name;
  if (left.kind === "logicNot") return sameLogicTree(left.operand, right.operand);
  if (left.kind === "logicBinary") {
    return left.operator === right.operator &&
      sameLogicTree(left.left, right.left) &&
      sameLogicTree(left.right, right.right);
  }
  return false;
}

function logicToString(node, parentPrecedence = 0) {
  if (node.kind === "logicConstant") {
    return formatTruth(node.value);
  }
  if (node.kind === "logicVariable") {
    return node.name;
  }
  if (node.kind === "logicNot") {
    const text = `not ${logicToString(node.operand, 5)}`;
    return parentPrecedence > 4 ? `(${text})` : text;
  }

  const precedence = logicPrecedence(node.operator);
  const left = logicToString(node.left, precedence);
  const right = logicToString(node.right, precedence + 0.1);
  const text = `${left} ${node.operator} ${right}`;
  return precedence < parentPrecedence ? `(${text})` : text;
}

function logicPrecedence(operator) {
  if (operator === "iff") return 1;
  if (operator === "implies") return 2;
  if (operator === "or") return 3;
  if (operator === "xor") return 3.5;
  if (operator === "and") return 4;
  return 5;
}

export function parseMath(statement) {
  return new MathParser(tokenizeMath(statement)).parse();
}

function tokenizeMath(statement) {
  const tokens = [];
  let index = 0;

  while (index < statement.length) {
    const char = statement[index];

    if (/\s/.test(char)) {
      index += 1;
      continue;
    }

    if (/[0-9.]/.test(char)) {
      const token = readNumber(statement, index);
      tokens.push(token);
      index = token.end;
      continue;
    }

    if (/[A-Za-z_]/.test(char)) {
      const start = index;
      index += 1;
      while (index < statement.length && /[A-Za-z0-9_]/.test(statement[index])) {
        index += 1;
      }
      tokens.push({
        kind: "IDENT",
        value: statement.slice(start, index),
        position: start,
      });
      continue;
    }

    if ("+-*/^=()".includes(char)) {
      tokens.push({ kind: char, value: char, position: index });
      index += 1;
      continue;
    }

    throw new Error(`Unexpected character '${char}' at position ${index}.`);
  }

  tokens.push({ kind: "EOF", value: "", position: statement.length });
  return tokens;
}

function readNumber(statement, start) {
  let index = start;
  let dots = 0;
  while (index < statement.length && /[0-9.]/.test(statement[index])) {
    if (statement[index] === ".") {
      dots += 1;
    }
    index += 1;
  }

  const raw = statement.slice(start, index);
  if (dots > 1 || raw === ".") {
    throw new Error(`Invalid number '${raw}' at position ${start}.`);
  }

  return {
    kind: "NUMBER",
    value: Number(raw),
    position: start,
    end: index,
  };
}

class MathParser {
  constructor(tokens) {
    this.tokens = tokens;
    this.index = 0;
  }

  parse() {
    const left = this.parseExpression();
    if (this.match("=")) {
      const right = this.parseExpression();
      this.expect("EOF");
      return { kind: "equation", left, right };
    }
    this.expect("EOF");
    return left;
  }

  parseExpression() {
    let expression = this.parseTerm();
    while (this.is("+") || this.is("-")) {
      const operator = this.current().value;
      this.index += 1;
      expression = mathBinary(operator, expression, this.parseTerm());
    }
    return expression;
  }

  parseTerm() {
    let expression = this.parsePower();

    while (this.is("*") || this.is("/") || this.canStartImplicitFactor()) {
      if (this.is("*") || this.is("/")) {
        const operator = this.current().value;
        this.index += 1;
        expression = mathBinary(operator, expression, this.parsePower());
      } else {
        expression = mathBinary("*", expression, this.parsePower());
      }
    }

    return expression;
  }

  parsePower() {
    const base = this.parseUnary();
    if (this.match("^")) {
      return mathBinary("^", base, this.parsePower());
    }
    return base;
  }

  parseUnary() {
    if (this.match("+")) {
      return this.parseUnary();
    }
    if (this.match("-")) {
      return { kind: "mathUnary", operator: "-", operand: this.parseUnary() };
    }
    return this.parseAtom();
  }

  parseAtom() {
    const token = this.current();
    if (this.match("NUMBER")) {
      return { kind: "mathNumber", value: token.value };
    }

    if (this.match("IDENT")) {
      const name = token.value;
      if (MATH_FUNCTIONS.has(name.toLowerCase()) && this.match("(")) {
        const argument = this.parseExpression();
        this.expect(")");
        return { kind: "mathFunction", name: name.toLowerCase(), argument };
      }
      return { kind: "mathSymbol", name };
    }

    if (this.match("(")) {
      const expression = this.parseExpression();
      this.expect(")");
      return expression;
    }

    throw new Error(`Expected expression at position ${token.position}.`);
  }

  canStartImplicitFactor() {
    const token = this.current();
    return token.kind === "NUMBER" || token.kind === "IDENT" || token.kind === "(";
  }

  current() {
    return this.tokens[this.index];
  }

  is(kind) {
    return this.current().kind === kind;
  }

  match(kind) {
    if (!this.is(kind)) {
      return false;
    }
    this.index += 1;
    return true;
  }

  expect(kind) {
    if (!this.match(kind)) {
      const token = this.current();
      throw new Error(`Expected '${kind}' before position ${token.position}.`);
    }
  }
}

function mathBinary(operator, left, right) {
  return { kind: "mathBinary", operator, left, right };
}

function mathNumber(value) {
  return { kind: "mathNumber", value };
}

function mathSymbol(name) {
  return { kind: "mathSymbol", name };
}

export function formatMath(node, parentPrecedence = 0) {
  if (node.kind === "equation") {
    return `${formatMath(node.left)} = ${formatMath(node.right)}`;
  }
  if (node.kind === "mathNumber") {
    return formatNumber(node.value);
  }
  if (node.kind === "mathSymbol") {
    return node.name;
  }
  if (node.kind === "mathFunction") {
    return `${node.name}(${formatMath(node.argument)})`;
  }
  if (node.kind === "mathUnary") {
    const text = `-${formatMath(node.operand, 4)}`;
    return parentPrecedence > 4 ? `(${text})` : text;
  }

  const precedence = mathPrecedence(node.operator);
  const left = formatMath(node.left, precedence);
  const right = formatMath(
    node.right,
    node.operator === "^" || node.operator === "-" || node.operator === "/"
      ? precedence + 0.1
      : precedence,
  );
  const symbol = node.operator;
  const text = `${left} ${symbol} ${right}`;
  return precedence < parentPrecedence ? `(${text})` : text;
}

function mathPrecedence(operator) {
  if (operator === "+" || operator === "-") return 1;
  if (operator === "*" || operator === "/") return 2;
  if (operator === "^") return 3;
  return 5;
}

function simplifyNode(node, steps = []) {
  if (node.kind === "mathNumber" || node.kind === "mathSymbol") {
    return node;
  }

  if (node.kind === "mathFunction") {
    const argument = simplifyNode(node.argument, steps);
    if (argument.kind === "mathNumber" && MATH_FUNCTIONS.has(node.name)) {
      const value = evaluateFunction(node.name, argument.value);
      if (Number.isFinite(value)) {
        steps.push({
          title: "Evaluate function",
          expression: `${node.name}(${formatNumber(argument.value)}) = ${formatNumber(value)}`,
          detail: "Numeric function calls are folded into constants.",
        });
        return mathNumber(value);
      }
    }
    const trigIdentity = simplifyTrigFunctionIdentity(node.name, argument, steps);
    if (trigIdentity) {
      return trigIdentity;
    }
    return { ...node, argument };
  }

  if (node.kind === "mathUnary") {
    const operand = simplifyNode(node.operand, steps);
    if (operand.kind === "mathNumber") {
      steps.push({
        title: "Fold negation",
        expression: `-${formatNumber(operand.value)} = ${formatNumber(-operand.value)}`,
        detail: "A negated constant is replaced by one number.",
      });
      return mathNumber(-operand.value);
    }
    if (operand.kind === "mathUnary") {
      steps.push({
        title: "Remove double negative",
        expression: formatMath(operand.operand),
        detail: "Two negatives cancel each other.",
      });
      return operand.operand;
    }
    return { kind: "mathUnary", operator: "-", operand };
  }

  const left = simplifyNode(node.left, steps);
  const right = simplifyNode(node.right, steps);

  if (left.kind === "mathNumber" && right.kind === "mathNumber") {
    const value = evaluateBinary(node.operator, left.value, right.value);
    if (Number.isFinite(value)) {
      steps.push({
        title: "Fold constants",
        expression: `${formatMath(left)} ${node.operator} ${formatMath(right)} = ${formatNumber(value)}`,
        detail: "A subtree with only numbers can be evaluated immediately.",
      });
      return mathNumber(value);
    }
  }

  if (node.operator === "+") {
    const pythagorean = simplifyTrigPythagoreanSum(left, right, steps);
    if (pythagorean) return pythagorean;
    const sumToProduct = simplifyTrigSumToProduct(left, right, "+", steps);
    if (sumToProduct) return sumToProduct;
    if (isZero(left)) return right;
    if (isZero(right)) return left;
  }

  if (node.operator === "-") {
    const pythagoreanDifference = simplifyTrigPythagoreanDifference(left, right, steps);
    if (pythagoreanDifference) return pythagoreanDifference;
    const sumToProduct = simplifyTrigSumToProduct(left, right, "-", steps);
    if (sumToProduct) return sumToProduct;
    if (isZero(right)) return left;
    if (isZero(left)) return { kind: "mathUnary", operator: "-", operand: right };
  }

  if (node.operator === "*") {
    const trigProduct = simplifyTrigProduct(left, right, steps);
    if (trigProduct) return trigProduct;
    if (isZero(left) || isZero(right)) return mathNumber(0);
    if (isOne(left)) return right;
    if (isOne(right)) return left;
  }

  if (node.operator === "/") {
    const trigQuotient = simplifyTrigQuotient(left, right, steps);
    if (trigQuotient) return trigQuotient;
    if (isZero(left)) return mathNumber(0);
    if (isOne(right)) return left;
  }

  if (node.operator === "^") {
    if (isZero(right)) return mathNumber(1);
    if (isOne(right)) return left;
    if (isOne(left)) return mathNumber(1);
  }

  return { kind: "mathBinary", operator: node.operator, left, right };
}

function simplifyTrigFunctionIdentity(name, argument, steps) {
  const supportedTrigFunctions = ["sin", "cos", "tan", "sec", "csc", "cot"];
  const supportsDoubleAndAngleSum = ["sin", "cos", "tan"].includes(name);
  if (!supportedTrigFunctions.includes(name)) {
    return null;
  }

  const doubleArgument = supportsDoubleAndAngleSum ? doubleAngleArgument(argument) : null;
  if (doubleArgument) {
    return rewriteTrigDoubleAngle(name, doubleArgument, steps);
  }

  const cofunctionArgument = trigCofunctionArgument(argument);
  if (cofunctionArgument) {
    return rewriteTrigCofunction(name, cofunctionArgument, steps);
  }

  const angleParts = supportsDoubleAndAngleSum ? trigAngleParts(argument) : null;
  if (angleParts) {
    return rewriteTrigAngleSum(name, angleParts.left, angleParts.right, angleParts.operator, steps);
  }

  return null;
}

function rewriteTrigCofunction(name, argument, steps) {
  const pairs = {
    sin: "cos",
    cos: "sin",
    tan: "cot",
    cot: "tan",
    sec: "csc",
    csc: "sec",
  };
  const target = pairs[name];
  if (!target) {
    return null;
  }

  const theta = formatIdentityArgument(argument);
  steps.push({
    title: "Apply cofunction identity",
    expression: `${name}(pi / 2 - ${theta}) = ${target}(${theta})`,
    detail: "Cofunction identities rewrite trig functions of complementary angles.",
  });
  return trigNode(target, argument);
}

function rewriteTrigDoubleAngle(name, argument, steps) {
  const theta = formatIdentityArgument(argument);
  if (name === "sin") {
    steps.push({
      title: "Apply double-angle identity",
      expression: `sin(2 * ${theta}) = 2 * sin(${theta}) * cos(${theta})`,
      detail: "The sine double-angle rule rewrites sin(2theta) as a product.",
    });
    return mathBinary(
      "*",
      mathBinary("*", mathNumber(2), trigNode("sin", argument)),
      trigNode("cos", argument),
    );
  }

  if (name === "cos") {
    steps.push({
      title: "Apply double-angle identity",
      expression: `cos(2 * ${theta}) = cos(${theta})^2 - sin(${theta})^2`,
      detail: "One standard cosine double-angle form subtracts sine-squared from cosine-squared.",
    });
    return mathBinary("-", squaredTrigNode("cos", argument), squaredTrigNode("sin", argument));
  }

  steps.push({
    title: "Apply double-angle identity",
    expression: `tan(2 * ${theta}) = (2 * tan(${theta})) / (1 - tan(${theta})^2)`,
    detail: "The tangent double-angle rule uses a quotient with one minus tangent-squared.",
  });
  return mathBinary(
    "/",
    mathBinary("*", mathNumber(2), trigNode("tan", argument)),
    mathBinary("-", mathNumber(1), squaredTrigNode("tan", argument)),
  );
}

function rewriteTrigAngleSum(name, left, right, operator, steps) {
  const leftText = formatIdentityArgument(left);
  const rightText = formatIdentityArgument(right);
  if (name === "sin") {
    const secondOperator = operator === "+" ? "+" : "-";
    steps.push({
      title: "Apply angle-sum identity",
      expression: `sin(${leftText} ${operator} ${rightText}) = sin(${leftText}) * cos(${rightText}) ${secondOperator} cos(${leftText}) * sin(${rightText})`,
      detail: "Sine of a sum or difference distributes into matching sine-cosine products.",
    });
    return mathBinary(
      secondOperator,
      mathBinary("*", trigNode("sin", left), trigNode("cos", right)),
      mathBinary("*", trigNode("cos", left), trigNode("sin", right)),
    );
  }

  if (name === "cos") {
    const secondOperator = operator === "+" ? "-" : "+";
    steps.push({
      title: "Apply angle-sum identity",
      expression: `cos(${leftText} ${operator} ${rightText}) = cos(${leftText}) * cos(${rightText}) ${secondOperator} sin(${leftText}) * sin(${rightText})`,
      detail: "Cosine changes the middle sign for sums and preserves it for differences.",
    });
    return mathBinary(
      secondOperator,
      mathBinary("*", trigNode("cos", left), trigNode("cos", right)),
      mathBinary("*", trigNode("sin", left), trigNode("sin", right)),
    );
  }

  const numeratorOperator = operator;
  const denominatorOperator = operator === "+" ? "-" : "+";
  steps.push({
    title: "Apply angle-sum identity",
    expression: `tan(${leftText} ${operator} ${rightText}) = (tan(${leftText}) ${numeratorOperator} tan(${rightText})) / (1 ${denominatorOperator} tan(${leftText}) * tan(${rightText}))`,
    detail: "Tangent of a sum or difference becomes a quotient of tangent terms.",
  });
  return mathBinary(
    "/",
    mathBinary(numeratorOperator, trigNode("tan", left), trigNode("tan", right)),
    mathBinary(
      denominatorOperator,
      mathNumber(1),
      mathBinary("*", trigNode("tan", left), trigNode("tan", right)),
    ),
  );
}

function doubleAngleArgument(argument) {
  if (argument.kind !== "mathBinary" || argument.operator !== "*") {
    return null;
  }
  if (argument.left.kind === "mathNumber" && nearlyEqual(argument.left.value, 2)) {
    return argument.right;
  }
  if (argument.right.kind === "mathNumber" && nearlyEqual(argument.right.value, 2)) {
    return argument.left;
  }
  return null;
}

function trigAngleParts(argument) {
  if (argument.kind !== "mathBinary" || (argument.operator !== "+" && argument.operator !== "-")) {
    return null;
  }
  return {
    left: argument.left,
    right: argument.right,
    operator: argument.operator,
  };
}

function trigCofunctionArgument(argument) {
  if (argument.kind !== "mathBinary" || argument.operator !== "-" || !isHalfPiNode(argument.left)) {
    return null;
  }
  return argument.right;
}

function isHalfPiNode(node) {
  if (node.kind === "mathBinary" && node.operator === "/" && isPiSymbol(node.left) && isNumericValue(node.right, 2)) {
    return true;
  }
  if (node.kind === "mathBinary" && node.operator === "*" && isPiSymbol(node.left) && isNumericValue(node.right, 0.5)) {
    return true;
  }
  if (node.kind === "mathBinary" && node.operator === "*" && isNumericValue(node.left, 0.5) && isPiSymbol(node.right)) {
    return true;
  }
  return false;
}

function isPiSymbol(node) {
  return node.kind === "mathSymbol" && node.name.toLowerCase() === "pi";
}

function isNumericValue(node, value) {
  return node.kind === "mathNumber" && nearlyEqual(node.value, value);
}

function trigNode(name, argument) {
  return { kind: "mathFunction", name, argument };
}

function halfAngleCombination(left, operator, right) {
  return mathBinary("/", mathBinary(operator, left, right), mathNumber(2));
}

function formatIdentityArgument(argument) {
  const text = formatMath(argument);
  return ["mathNumber", "mathSymbol", "mathFunction"].includes(argument.kind) ? text : `(${text})`;
}

function simplifyTrigPythagoreanSum(left, right, steps) {
  const leftSin = squaredTrigArgument(left, "sin");
  const leftCos = squaredTrigArgument(left, "cos");
  const rightSin = squaredTrigArgument(right, "sin");
  const rightCos = squaredTrigArgument(right, "cos");
  const argument = leftSin && rightCos && sameMathTree(leftSin, rightCos)
    ? leftSin
    : leftCos && rightSin && sameMathTree(leftCos, rightSin)
      ? leftCos
      : null;
  if (!argument) {
    return null;
  }

  steps.push({
    title: "Apply Pythagorean identity",
    expression: `sin(${formatMath(argument)})^2 + cos(${formatMath(argument)})^2 = 1`,
    detail: "The matching sine-squared and cosine-squared terms add to one.",
  });
  return mathNumber(1);
}

function simplifyTrigPythagoreanDifference(left, right, steps) {
  if (!isOne(left)) {
    return null;
  }
  const sinArgument = squaredTrigArgument(right, "sin");
  if (sinArgument) {
    const result = squaredTrigNode("cos", sinArgument);
    steps.push({
      title: "Apply Pythagorean identity",
      expression: `1 - sin(${formatMath(sinArgument)})^2 = cos(${formatMath(sinArgument)})^2`,
      detail: "Rearrange sin^2(theta) + cos^2(theta) = 1.",
    });
    return result;
  }

  const cosArgument = squaredTrigArgument(right, "cos");
  if (cosArgument) {
    const result = squaredTrigNode("sin", cosArgument);
    steps.push({
      title: "Apply Pythagorean identity",
      expression: `1 - cos(${formatMath(cosArgument)})^2 = sin(${formatMath(cosArgument)})^2`,
      detail: "Rearrange sin^2(theta) + cos^2(theta) = 1.",
    });
    return result;
  }
  return null;
}

function simplifyTrigSumToProduct(left, right, operator, steps) {
  const leftSin = trigFunctionArgument(left, "sin");
  const rightSin = trigFunctionArgument(right, "sin");
  const leftCos = trigFunctionArgument(left, "cos");
  const rightCos = trigFunctionArgument(right, "cos");

  if (leftSin && rightSin && !sameMathTree(leftSin, rightSin)) {
    const sumArgument = halfAngleCombination(leftSin, "+", rightSin);
    const differenceArgument = halfAngleCombination(leftSin, "-", rightSin);
    const result = operator === "+"
      ? mathBinary("*", mathBinary("*", mathNumber(2), trigNode("sin", sumArgument)), trigNode("cos", differenceArgument))
      : mathBinary("*", mathBinary("*", mathNumber(2), trigNode("cos", sumArgument)), trigNode("sin", differenceArgument));
    steps.push({
      title: "Apply sum-to-product identity",
      expression: operator === "+"
        ? `sin(${formatMath(leftSin)}) + sin(${formatMath(rightSin)}) = 2sin((a + b)/2)cos((a - b)/2)`
        : `sin(${formatMath(leftSin)}) - sin(${formatMath(rightSin)}) = 2cos((a + b)/2)sin((a - b)/2)`,
      detail: "A sum or difference of sine terms can be rewritten as a product.",
    });
    return result;
  }

  if (leftCos && rightCos && !sameMathTree(leftCos, rightCos)) {
    const sumArgument = halfAngleCombination(leftCos, "+", rightCos);
    const differenceArgument = halfAngleCombination(leftCos, "-", rightCos);
    const product = mathBinary("*", trigNode("sin", sumArgument), trigNode("sin", differenceArgument));
    const result = operator === "+"
      ? mathBinary("*", mathBinary("*", mathNumber(2), trigNode("cos", sumArgument)), trigNode("cos", differenceArgument))
      : mathBinary("*", mathNumber(-2), product);
    steps.push({
      title: "Apply sum-to-product identity",
      expression: operator === "+"
        ? `cos(${formatMath(leftCos)}) + cos(${formatMath(rightCos)}) = 2cos((a + b)/2)cos((a - b)/2)`
        : `cos(${formatMath(leftCos)}) - cos(${formatMath(rightCos)}) = -2sin((a + b)/2)sin((a - b)/2)`,
      detail: "A sum or difference of cosine terms can be rewritten as a product.",
    });
    return result;
  }

  return null;
}

function simplifyTrigProduct(left, right, steps) {
  const leftTan = trigFunctionArgument(left, "tan");
  const leftCos = trigFunctionArgument(left, "cos");
  const leftCot = trigFunctionArgument(left, "cot");
  const leftSec = trigFunctionArgument(left, "sec");
  const leftCsc = trigFunctionArgument(left, "csc");
  const leftSin = trigFunctionArgument(left, "sin");
  const rightTan = trigFunctionArgument(right, "tan");
  const rightCos = trigFunctionArgument(right, "cos");
  const rightCot = trigFunctionArgument(right, "cot");
  const rightSec = trigFunctionArgument(right, "sec");
  const rightCsc = trigFunctionArgument(right, "csc");
  const rightSin = trigFunctionArgument(right, "sin");
  const argument = leftTan && rightCos && sameMathTree(leftTan, rightCos)
    ? leftTan
    : leftCos && rightTan && sameMathTree(leftCos, rightTan)
      ? leftCos
      : null;
  if (argument) {
    steps.push({
      title: "Apply tangent identity",
      expression: `tan(${formatMath(argument)}) * cos(${formatMath(argument)}) = sin(${formatMath(argument)})`,
      detail: "Because tan(theta) = sin(theta) / cos(theta), multiplying by cos(theta) leaves sin(theta).",
    });
    return trigNode("sin", argument);
  }

  const cotArgument = leftCot && rightSin && sameMathTree(leftCot, rightSin)
    ? leftCot
    : leftSin && rightCot && sameMathTree(leftSin, rightCot)
      ? leftSin
      : null;
  if (cotArgument) {
    steps.push({
      title: "Apply cotangent identity",
      expression: `cot(${formatMath(cotArgument)}) * sin(${formatMath(cotArgument)}) = cos(${formatMath(cotArgument)})`,
      detail: "Because cot(theta) = cos(theta) / sin(theta), multiplying by sin(theta) leaves cos(theta).",
    });
    return trigNode("cos", cotArgument);
  }

  const reciprocalPair = matchingTrigPair([
    [leftSec, rightCos, "sec", "cos"],
    [leftCos, rightSec, "cos", "sec"],
    [leftCsc, rightSin, "csc", "sin"],
    [leftSin, rightCsc, "sin", "csc"],
    [leftCot, rightTan, "cot", "tan"],
    [leftTan, rightCot, "tan", "cot"],
  ]);
  if (reciprocalPair) {
    steps.push({
      title: "Cancel reciprocal trig functions",
      expression: `${reciprocalPair.leftName}(${formatMath(reciprocalPair.argument)}) * ${reciprocalPair.rightName}(${formatMath(reciprocalPair.argument)}) = 1`,
      detail: "Reciprocal trigonometric functions multiply to one when their arguments match.",
    });
    return mathNumber(1);
  }

  return simplifyTrigProductToSum(leftSin, leftCos, rightSin, rightCos, steps);
}

function simplifyTrigProductToSum(leftSin, leftCos, rightSin, rightCos, steps) {
  const sinCosArgument = leftSin && rightCos && !sameMathTree(leftSin, rightCos)
    ? { sinArgument: leftSin, cosArgument: rightCos, orientation: "sin-cos" }
    : leftCos && rightSin && !sameMathTree(leftCos, rightSin)
      ? { sinArgument: rightSin, cosArgument: leftCos, orientation: "cos-sin" }
      : null;
  if (sinCosArgument) {
    const firstArgument = sinCosArgument.orientation === "sin-cos" ? sinCosArgument.sinArgument : sinCosArgument.cosArgument;
    const secondArgument = sinCosArgument.orientation === "sin-cos" ? sinCosArgument.cosArgument : sinCosArgument.sinArgument;
    const sumTerm = trigNode("sin", mathBinary("+", firstArgument, secondArgument));
    const differenceTerm = trigNode("sin", mathBinary("-", firstArgument, secondArgument));
    const body = sinCosArgument.orientation === "sin-cos"
      ? mathBinary("+", sumTerm, differenceTerm)
      : mathBinary("-", sumTerm, differenceTerm);
    steps.push({
      title: "Apply product-to-sum identity",
      expression: `${sinCosArgument.orientation === "sin-cos" ? "sin(a)cos(b)" : "cos(a)sin(b)"} = 0.5[sin(a + b) ${sinCosArgument.orientation === "sin-cos" ? "+" : "-"} sin(a - b)]`,
      detail: "A sine-cosine product can be rewritten as a sum of sine terms.",
    });
    return mathBinary("*", mathNumber(0.5), body);
  }

  if (leftCos && rightCos && !sameMathTree(leftCos, rightCos)) {
    steps.push({
      title: "Apply product-to-sum identity",
      expression: "cos(a)cos(b) = 0.5[cos(a + b) + cos(a - b)]",
      detail: "A cosine-cosine product can be rewritten as a sum of cosine terms.",
    });
    return mathBinary(
      "*",
      mathNumber(0.5),
      mathBinary(
        "+",
        trigNode("cos", mathBinary("+", leftCos, rightCos)),
        trigNode("cos", mathBinary("-", leftCos, rightCos)),
      ),
    );
  }

  if (leftSin && rightSin && !sameMathTree(leftSin, rightSin)) {
    steps.push({
      title: "Apply product-to-sum identity",
      expression: "sin(a)sin(b) = 0.5[cos(a - b) - cos(a + b)]",
      detail: "A sine-sine product can be rewritten as a difference of cosine terms.",
    });
    return mathBinary(
      "*",
      mathNumber(0.5),
      mathBinary(
        "-",
        trigNode("cos", mathBinary("-", leftSin, rightSin)),
        trigNode("cos", mathBinary("+", leftSin, rightSin)),
      ),
    );
  }

  return null;
}

function simplifyTrigQuotient(left, right, steps) {
  const sinArgument = trigFunctionArgument(left, "sin");
  const cosArgument = trigFunctionArgument(right, "cos");
  if (sinArgument && cosArgument && sameMathTree(sinArgument, cosArgument)) {
    steps.push({
      title: "Apply tangent identity",
      expression: `sin(${formatMath(sinArgument)}) / cos(${formatMath(sinArgument)}) = tan(${formatMath(sinArgument)})`,
      detail: "The quotient identity rewrites sine divided by cosine as tangent.",
    });
    return trigNode("tan", sinArgument);
  }

  const leftCos = trigFunctionArgument(left, "cos");
  const rightSin = trigFunctionArgument(right, "sin");
  if (leftCos && rightSin && sameMathTree(leftCos, rightSin)) {
    steps.push({
      title: "Apply cotangent identity",
      expression: `cos(${formatMath(leftCos)}) / sin(${formatMath(leftCos)}) = cot(${formatMath(leftCos)})`,
      detail: "The quotient identity rewrites cosine divided by sine as cotangent.",
    });
    return trigNode("cot", leftCos);
  }

  if (isOne(left)) {
    const reciprocal = [
      ["sin", "csc"],
      ["cos", "sec"],
      ["tan", "cot"],
      ["sec", "cos"],
      ["csc", "sin"],
      ["cot", "tan"],
    ].find(([source]) => trigFunctionArgument(right, source));
    if (reciprocal) {
      const [source, target] = reciprocal;
      const argument = trigFunctionArgument(right, source);
      steps.push({
        title: "Apply reciprocal trig identity",
        expression: `1 / ${source}(${formatMath(argument)}) = ${target}(${formatMath(argument)})`,
        detail: "A reciprocal trigonometric function can replace one divided by its paired trig function.",
      });
      return trigNode(target, argument);
    }
  }

  return null;
}

function matchingTrigPair(pairs) {
  for (const [leftArgument, rightArgument, leftName, rightName] of pairs) {
    if (leftArgument && rightArgument && sameMathTree(leftArgument, rightArgument)) {
      return {
        argument: leftArgument,
        leftName,
        rightName,
      };
    }
  }
  return null;
}

function trigFunctionArgument(node, name) {
  return node.kind === "mathFunction" && node.name === name ? node.argument : null;
}

function squaredTrigArgument(node, name) {
  if (node.kind !== "mathBinary" || node.operator !== "^" || node.right.kind !== "mathNumber" || !nearlyEqual(node.right.value, 2)) {
    return null;
  }
  if (node.left.kind !== "mathFunction" || node.left.name !== name) {
    return null;
  }
  return node.left.argument;
}

function squaredTrigNode(name, argument) {
  return mathBinary("^", { kind: "mathFunction", name, argument }, mathNumber(2));
}

function rewriteTrigPowerReduction(node, steps) {
  const sinArgument = squaredTrigArgument(node, "sin");
  if (sinArgument) {
    const result = mathBinary(
      "/",
      mathBinary("-", mathNumber(1), trigNode("cos", doubleAngleNode(sinArgument))),
      mathNumber(2),
    );
    steps.push({
      title: "Apply power-reduction identity",
      expression: `sin(${formatMath(sinArgument)})^2 = (1 - cos(2theta)) / 2`,
      detail: "Power-reduction identities replace squared trig functions with first powers of double angles.",
    });
    return result;
  }

  const cosArgument = squaredTrigArgument(node, "cos");
  if (cosArgument) {
    const result = mathBinary(
      "/",
      mathBinary("+", mathNumber(1), trigNode("cos", doubleAngleNode(cosArgument))),
      mathNumber(2),
    );
    steps.push({
      title: "Apply power-reduction identity",
      expression: `cos(${formatMath(cosArgument)})^2 = (1 + cos(2theta)) / 2`,
      detail: "Power-reduction identities replace squared trig functions with first powers of double angles.",
    });
    return result;
  }

  const tanArgument = squaredTrigArgument(node, "tan");
  if (tanArgument) {
    const doubleAngle = doubleAngleNode(tanArgument);
    const result = mathBinary(
      "/",
      mathBinary("-", mathNumber(1), trigNode("cos", doubleAngle)),
      mathBinary("+", mathNumber(1), trigNode("cos", doubleAngle)),
    );
    steps.push({
      title: "Apply power-reduction identity",
      expression: `tan(${formatMath(tanArgument)})^2 = (1 - cos(2theta)) / (1 + cos(2theta))`,
      detail: "The tangent-squared reduction follows from sin-squared over cos-squared reductions.",
    });
    return result;
  }

  const product = matchingSineCosineProduct(node);
  if (product) {
    const result = mathBinary("*", mathNumber(0.5), trigNode("sin", doubleAngleNode(product)));
    steps.push({
      title: "Apply product power-reduction identity",
      expression: `sin(${formatMath(product)})cos(${formatMath(product)}) = 0.5sin(2theta)`,
      detail: "The sine double-angle identity can be rearranged to collapse a matching sine-cosine product.",
    });
    return result;
  }

  return null;
}

function rewriteTrigHalfAngle(node, steps) {
  const sinArgument = trigFunctionArgument(node, "sin");
  const sinBase = sinArgument ? halfAngleBaseArgument(sinArgument) : null;
  if (sinBase) {
    const result = trigNode(
      "sqrt",
      mathBinary("/", mathBinary("-", mathNumber(1), trigNode("cos", sinBase)), mathNumber(2)),
    );
    steps.push({
      title: "Apply half-angle identity",
      expression: `sin(${formatMath(sinBase)} / 2) = sqrt((1 - cos(${formatMath(sinBase)})) / 2)`,
      detail: "The solver reports the principal square-root half-angle form.",
    });
    return result;
  }

  const cosArgument = trigFunctionArgument(node, "cos");
  const cosBase = cosArgument ? halfAngleBaseArgument(cosArgument) : null;
  if (cosBase) {
    const result = trigNode(
      "sqrt",
      mathBinary("/", mathBinary("+", mathNumber(1), trigNode("cos", cosBase)), mathNumber(2)),
    );
    steps.push({
      title: "Apply half-angle identity",
      expression: `cos(${formatMath(cosBase)} / 2) = sqrt((1 + cos(${formatMath(cosBase)})) / 2)`,
      detail: "The solver reports the principal square-root half-angle form.",
    });
    return result;
  }

  const tanArgument = trigFunctionArgument(node, "tan");
  const tanBase = tanArgument ? halfAngleBaseArgument(tanArgument) : null;
  if (tanBase) {
    const result = mathBinary(
      "/",
      trigNode("sin", tanBase),
      mathBinary("+", mathNumber(1), trigNode("cos", tanBase)),
    );
    steps.push({
      title: "Apply half-angle identity",
      expression: `tan(${formatMath(tanBase)} / 2) = sin(${formatMath(tanBase)}) / (1 + cos(${formatMath(tanBase)}))`,
      detail: "This tangent half-angle form avoids an extra square-root branch.",
    });
    return result;
  }

  return null;
}

function matchingSineCosineProduct(node) {
  if (node.kind !== "mathBinary" || node.operator !== "*") {
    return null;
  }
  const leftSin = trigFunctionArgument(node.left, "sin");
  const leftCos = trigFunctionArgument(node.left, "cos");
  const rightSin = trigFunctionArgument(node.right, "sin");
  const rightCos = trigFunctionArgument(node.right, "cos");
  if (leftSin && rightCos && sameMathTree(leftSin, rightCos)) return leftSin;
  if (leftCos && rightSin && sameMathTree(leftCos, rightSin)) return leftCos;
  return null;
}

function halfAngleBaseArgument(argument) {
  if (argument.kind === "mathBinary" && argument.operator === "/" && isNumericValue(argument.right, 2)) {
    return argument.left;
  }
  if (argument.kind === "mathBinary" && argument.operator === "*") {
    if (isNumericValue(argument.left, 0.5)) return argument.right;
    if (isNumericValue(argument.right, 0.5)) return argument.left;
  }
  return null;
}

function doubleAngleNode(argument) {
  return mathBinary("*", mathNumber(2), argument);
}

function sameMathTree(left, right) {
  if (left.kind !== right.kind) {
    return false;
  }
  if (left.kind === "mathNumber") {
    return nearlyEqual(left.value, right.value);
  }
  if (left.kind === "mathSymbol") {
    return left.name === right.name;
  }
  if (left.kind === "mathFunction") {
    return left.name === right.name && sameMathTree(left.argument, right.argument);
  }
  if (left.kind === "mathUnary") {
    return left.operator === right.operator && sameMathTree(left.operand, right.operand);
  }
  if (left.kind === "mathBinary") {
    return left.operator === right.operator &&
      sameMathTree(left.left, right.left) &&
      sameMathTree(left.right, right.right);
  }
  if (left.kind === "equation") {
    return sameMathTree(left.left, right.left) && sameMathTree(left.right, right.right);
  }
  return false;
}

function evaluateBinary(operator, left, right) {
  if (operator === "+") return left + right;
  if (operator === "-") return left - right;
  if (operator === "*") return left * right;
  if (operator === "/") return right === 0 ? Number.NaN : left / right;
  if (operator === "^") return left ** right;
  return Number.NaN;
}

function evaluateFunction(name, value) {
  if (name === "sin") return Math.sin(value);
  if (name === "cos") return Math.cos(value);
  if (name === "tan") return Math.tan(value);
  if (name === "sec") return 1 / Math.cos(value);
  if (name === "csc") return 1 / Math.sin(value);
  if (name === "cot") return 1 / Math.tan(value);
  if (name === "exp") return Math.exp(value);
  if (name === "ln") return Math.log(value);
  if (name === "sqrt") return Math.sqrt(value);
  if (name === "atan") return Math.atan(value);
  return Number.NaN;
}

function evaluateComplex(node) {
  if (node.kind === "mathNumber") {
    return complex(node.value, 0);
  }
  if (node.kind === "mathSymbol") {
    if (node.name.toLowerCase() === "i") {
      return complex(0, 1);
    }
    throw new Error(`Complex mode only knows the imaginary unit i. '${node.name}' looks like a variable.`);
  }
  if (node.kind === "mathUnary") {
    return complexNeg(evaluateComplex(node.operand));
  }
  if (node.kind === "mathFunction") {
    return evaluateComplexFunction(node.name, evaluateComplex(node.argument));
  }
  if (node.kind === "mathBinary") {
    const left = evaluateComplex(node.left);
    const right = evaluateComplex(node.right);
    if (node.operator === "+") return complexAdd(left, right);
    if (node.operator === "-") return complexSub(left, right);
    if (node.operator === "*") return complexMul(left, right);
    if (node.operator === "/") return complexDiv(left, right);
    if (node.operator === "^") return complexPow(left, right);
    throw new Error(`Cannot evaluate complex operator '${node.operator}'.`);
  }
  throw new Error("Complex mode expects a math expression.");
}

function evaluateComplexFunction(name, value) {
  if (name === "sin") {
    return complex(Math.sin(value.re) * Math.cosh(value.im), Math.cos(value.re) * Math.sinh(value.im));
  }
  if (name === "cos") {
    return complex(Math.cos(value.re) * Math.cosh(value.im), -Math.sin(value.re) * Math.sinh(value.im));
  }
  if (name === "tan") {
    return complexDiv(evaluateComplexFunction("sin", value), evaluateComplexFunction("cos", value));
  }
  if (name === "sec") {
    return complexDiv(complex(1), evaluateComplexFunction("cos", value));
  }
  if (name === "csc") {
    return complexDiv(complex(1), evaluateComplexFunction("sin", value));
  }
  if (name === "cot") {
    return complexDiv(evaluateComplexFunction("cos", value), evaluateComplexFunction("sin", value));
  }
  if (name === "exp") {
    const scale = Math.exp(value.re);
    return complex(scale * Math.cos(value.im), scale * Math.sin(value.im));
  }
  if (name === "ln") {
    if (nearlyEqual(complexAbs(value), 0)) {
      throw new Error("Complex logarithm is undefined at 0.");
    }
    return complex(Math.log(complexAbs(value)), Math.atan2(value.im, value.re));
  }
  if (name === "sqrt") {
    return complexSqrt(value);
  }
  if (name === "atan") {
    const i = complex(0, 1);
    const iz = complexMul(i, value);
    const numerator = complexSub(
      evaluateComplexFunction("ln", complexAdd(complex(1), iz)),
      evaluateComplexFunction("ln", complexSub(complex(1), iz)),
    );
    return complexMul(complex(0, -0.5), numerator);
  }
  throw new Error(`Complex mode does not support the function '${name}'.`);
}

function complex(re, im = 0) {
  if (!Number.isFinite(re) || !Number.isFinite(im)) {
    throw new Error("Complex evaluation produced a non-finite value.");
  }
  return {
    re: normalizeComplexPart(re),
    im: normalizeComplexPart(im),
  };
}

function normalizeComplexPart(value) {
  if (nearlyEqual(value, 0)) {
    return 0;
  }
  return Number(value.toFixed(10));
}

function complexAdd(left, right) {
  return complex(left.re + right.re, left.im + right.im);
}

function complexSub(left, right) {
  return complex(left.re - right.re, left.im - right.im);
}

function complexNeg(value) {
  return complex(-value.re, -value.im);
}

function complexMul(left, right) {
  return complex(
    left.re * right.re - left.im * right.im,
    left.re * right.im + left.im * right.re,
  );
}

function complexDiv(left, right) {
  const denominator = right.re ** 2 + right.im ** 2;
  if (nearlyEqual(denominator, 0)) {
    throw new Error("Division by zero is undefined for complex numbers.");
  }
  return complex(
    (left.re * right.re + left.im * right.im) / denominator,
    (left.im * right.re - left.re * right.im) / denominator,
  );
}

function complexPow(base, exponent) {
  if (nearlyEqual(exponent.im, 0) && Number.isInteger(exponent.re) && Math.abs(exponent.re) <= 32) {
    return complexIntegerPower(base, exponent.re);
  }
  if (nearlyEqual(complexAbs(base), 0)) {
    throw new Error("Complex powers with base 0 are only supported for integer exponents.");
  }
  return evaluateComplexFunction("exp", complexMul(exponent, evaluateComplexFunction("ln", base)));
}

function complexIntegerPower(base, exponent) {
  if (exponent === 0) {
    return complex(1, 0);
  }

  let power = Math.abs(exponent);
  let result = complex(1, 0);
  let factor = base;
  while (power > 0) {
    if (power % 2 === 1) {
      result = complexMul(result, factor);
    }
    factor = complexMul(factor, factor);
    power = Math.floor(power / 2);
  }

  return exponent < 0 ? complexDiv(complex(1, 0), result) : result;
}

function complexSqrt(value) {
  const radius = complexAbs(value);
  const real = Math.sqrt((radius + value.re) / 2);
  const sign = value.im < 0 ? -1 : 1;
  const imaginary = sign * Math.sqrt((radius - value.re) / 2);
  return complex(real, imaginary);
}

function complexAbs(value) {
  return Math.hypot(value.re, value.im);
}

function formatComplex(value) {
  const real = normalizeComplexPart(value.re);
  const imaginary = normalizeComplexPart(value.im);
  if (nearlyEqual(imaginary, 0)) {
    return formatNumber(real);
  }
  if (nearlyEqual(real, 0)) {
    return formatImaginary(imaginary);
  }
  const sign = imaginary < 0 ? "-" : "+";
  return `${formatNumber(real)} ${sign} ${formatImaginary(Math.abs(imaginary))}`;
}

function formatImaginary(value) {
  const magnitude = Math.abs(normalizeComplexPart(value));
  const text = nearlyEqual(magnitude, 1) ? "i" : `${formatNumber(magnitude)}i`;
  return value < 0 ? `-${text}` : text;
}

function isZero(node) {
  return node.kind === "mathNumber" && nearlyEqual(node.value, 0);
}

function isOne(node) {
  return node.kind === "mathNumber" && nearlyEqual(node.value, 1);
}

function polynomialFrom(node) {
  if (node.kind === "mathNumber") {
    return cleanPolynomial(new Map([["", node.value]]));
  }
  if (node.kind === "mathSymbol") {
    return new Map([[monomialKey({ [node.name]: 1 }), 1]]);
  }
  if (node.kind === "mathUnary") {
    const operand = polynomialFrom(node.operand);
    return operand ? scalePolynomial(operand, -1) : null;
  }
  if (node.kind !== "mathBinary") {
    return null;
  }

  const left = polynomialFrom(node.left);
  const right = polynomialFrom(node.right);

  if (node.operator === "+") return left && right ? addPolynomials(left, right) : null;
  if (node.operator === "-") return left && right ? addPolynomials(left, scalePolynomial(right, -1)) : null;
  if (node.operator === "*") return left && right ? multiplyPolynomials(left, right) : null;
  if (node.operator === "/") {
    if (!left || !right || right.size !== 1 || !right.has("")) return null;
    const denominator = right.get("");
    if (nearlyEqual(denominator, 0)) return null;
    return scalePolynomial(left, 1 / denominator);
  }
  if (node.operator === "^") {
    if (!left || node.right.kind !== "mathNumber") return null;
    const power = node.right.value;
    if (!Number.isInteger(power) || power < 0 || power > 8) return null;
    return powerPolynomial(left, power);
  }

  return null;
}

function addPolynomials(left, right) {
  const result = new Map(left);
  for (const [key, coefficient] of right.entries()) {
    result.set(key, (result.get(key) ?? 0) + coefficient);
  }
  return cleanPolynomial(result);
}

function scalePolynomial(poly, scalar) {
  return cleanPolynomial(new Map([...poly.entries()].map(([key, value]) => [key, value * scalar])));
}

function multiplyPolynomials(left, right) {
  const result = new Map();
  for (const [leftKey, leftCoeff] of left.entries()) {
    for (const [rightKey, rightCoeff] of right.entries()) {
      const key = multiplyMonomialKeys(leftKey, rightKey);
      result.set(key, (result.get(key) ?? 0) + leftCoeff * rightCoeff);
    }
  }
  return cleanPolynomial(result);
}

function powerPolynomial(poly, power) {
  let result = new Map([["", 1]]);
  for (let index = 0; index < power; index += 1) {
    result = multiplyPolynomials(result, poly);
  }
  return cleanPolynomial(result);
}

function cleanPolynomial(poly) {
  const result = new Map();
  for (const [key, coefficient] of poly.entries()) {
    if (!nearlyEqual(coefficient, 0)) {
      result.set(key, normalizeNumber(coefficient));
    }
  }
  if (result.size === 0) {
    result.set("", 0);
  }
  return result;
}

function monomialKey(powers) {
  return Object.entries(powers)
    .filter(([, power]) => power > 0)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([name, power]) => `${name}:${power}`)
    .join("|");
}

function powersFromKey(key) {
  if (!key) return {};
  return Object.fromEntries(
    key.split("|").map((part) => {
      const [name, power] = part.split(":");
      return [name, Number(power)];
    }),
  );
}

function multiplyMonomialKeys(leftKey, rightKey) {
  const powers = powersFromKey(leftKey);
  for (const [name, power] of Object.entries(powersFromKey(rightKey))) {
    powers[name] = (powers[name] ?? 0) + power;
  }
  return monomialKey(powers);
}

function polynomialToNode(poly) {
  const terms = sortedPolynomialTerms(poly).map(([key, coefficient]) =>
    termToNode(key, coefficient),
  );
  return terms.reduce((expression, term) =>
    expression ? mathBinary("+", expression, term) : term,
  );
}

function termToNode(key, coefficient) {
  if (!key) {
    return mathNumber(coefficient);
  }

  let expression = null;
  for (const [name, power] of Object.entries(powersFromKey(key))) {
    const factor = power === 1 ? mathSymbol(name) : mathBinary("^", mathSymbol(name), mathNumber(power));
    expression = expression ? mathBinary("*", expression, factor) : factor;
  }

  if (nearlyEqual(coefficient, 1)) return expression;
  if (nearlyEqual(coefficient, -1)) return { kind: "mathUnary", operator: "-", operand: expression };
  return mathBinary("*", mathNumber(coefficient), expression);
}

function sortedPolynomialTerms(poly) {
  return [...poly.entries()]
    .filter(([, coefficient]) => !nearlyEqual(coefficient, 0))
    .sort(([leftKey], [rightKey]) => {
      const degreeDelta = monomialDegree(rightKey) - monomialDegree(leftKey);
      return degreeDelta || leftKey.localeCompare(rightKey);
    });
}

function monomialDegree(key) {
  return Object.values(powersFromKey(key)).reduce((sum, power) => sum + power, 0);
}

function formatPolynomial(poly) {
  const terms = sortedPolynomialTerms(poly);
  if (terms.length === 0) {
    return "0";
  }

  return terms
    .map(([key, coefficient], index) => {
      const sign = coefficient < 0 ? "-" : "+";
      const body = formatPolynomialTerm(key, Math.abs(coefficient));
      if (index === 0) {
        return coefficient < 0 ? `-${body}` : body;
      }
      return ` ${sign} ${body}`;
    })
    .join("");
}

function formatPolynomialTerm(key, coefficient) {
  const monomial = formatMonomial(key);
  if (!monomial) {
    return formatNumber(coefficient);
  }
  if (nearlyEqual(coefficient, 1)) {
    return monomial;
  }
  return `${formatNumber(coefficient)}${monomial}`;
}

function formatMonomial(key) {
  const powers = powersFromKey(key);
  return Object.entries(powers)
    .map(([name, power]) => (power === 1 ? name : `${name}^${power}`))
    .join("*");
}

function polynomialVariables(poly) {
  const names = new Set();
  for (const key of poly.keys()) {
    for (const name of Object.keys(powersFromKey(key))) {
      names.add(name);
    }
  }
  return [...names].sort();
}

function linearPolynomialRow(poly, variables) {
  const coefficients = Object.fromEntries(variables.map((variable) => [variable, 0]));
  let constant = 0;

  for (const [key, coefficient] of poly.entries()) {
    if (!key) {
      constant += coefficient;
      continue;
    }

    const powers = powersFromKey(key);
    const entries = Object.entries(powers);
    if (entries.length !== 1 || entries[0][1] !== 1) {
      throw new Error("System solving currently supports linear equations only.");
    }

    const [variable] = entries[0];
    coefficients[variable] += coefficient;
  }

  return {
    coefficients: variables.map((variable) => normalizeNumber(coefficients[variable])),
    constant: normalizeNumber(-constant),
  };
}

function solveLinearSystem(matrix, constants) {
  const size = matrix.length;
  const augmented = matrix.map((row, index) => [...row, constants[index]]);

  for (let column = 0; column < size; column += 1) {
    let pivot = column;
    for (let row = column + 1; row < size; row += 1) {
      if (Math.abs(augmented[row][column]) > Math.abs(augmented[pivot][column])) {
        pivot = row;
      }
    }

    if (nearlyEqual(augmented[pivot][column], 0)) {
      throw new Error("The system has no unique solution.");
    }

    [augmented[column], augmented[pivot]] = [augmented[pivot], augmented[column]];
    const pivotValue = augmented[column][column];
    for (let col = column; col <= size; col += 1) {
      augmented[column][col] /= pivotValue;
    }

    for (let row = 0; row < size; row += 1) {
      if (row === column) continue;
      const factor = augmented[row][column];
      for (let col = column; col <= size; col += 1) {
        augmented[row][col] -= factor * augmented[column][col];
      }
    }
  }

  return augmented.map((row) => normalizeNumber(row[size]));
}

function formatAugmentedMatrix(matrix, constants) {
  return matrix
    .map((row, index) => `[${row.map(formatNumber).join(", ")} | ${formatNumber(constants[index])}]`)
    .join("; ");
}

function chooseVariable(variableNames, hint) {
  if (variableNames.includes(hint)) {
    return hint;
  }
  return variableNames[0] ?? hint;
}

function solvePolynomial(poly, variable) {
  const coefficients = polynomialCoefficients(poly, variable);
  const degree = polynomialDegree(coefficients);

  if (degree === 0) {
    const constant = coefficients[0] ?? 0;
    return {
      answer: nearlyEqual(constant, 0) ? "all real numbers" : "no solution",
      summary: nearlyEqual(constant, 0) ? "identity" : "inconsistent",
      steps: [
        {
          title: "Check constant equation",
          expression: `${formatNumber(constant)} = 0`,
          detail: nearlyEqual(constant, 0)
            ? "The equation is always true."
            : "A nonzero constant cannot equal zero.",
        },
      ],
    };
  }

  if (degree === 1) {
    const b = coefficients[0] ?? 0;
    const a = coefficients[1] ?? 0;
    const root = -b / a;
    return {
      answer: `${variable} = ${formatNumber(root)}`,
      summary: "linear solution",
      steps: [
        {
          title: "Apply linear formula",
          expression: `${formatNumber(a)}${variable} + ${formatNumber(b)} = 0`,
          detail: `${variable} = -b / a = ${formatNumber(root)}.`,
        },
      ],
    };
  }

  if (degree === 2) {
    const c = coefficients[0] ?? 0;
    const b = coefficients[1] ?? 0;
    const a = coefficients[2] ?? 0;
    const discriminant = b * b - 4 * a * c;
    const result = quadraticRootResult(a, b, c, discriminant);
    return {
      answer: result.roots.map((root) => `${variable} = ${root}`).join(", "),
      summary: "quadratic solution",
      steps: [
        {
          title: "Compute discriminant",
          expression: `b^2 - 4ac = ${formatNumber(discriminant)}`,
          detail: "The discriminant determines the quadratic roots.",
        },
        {
          title: "Apply quadratic formula",
          expression: `${variable} = (-b +/- sqrt(b^2 - 4ac)) / 2a`,
          detail: `Solutions: ${result.roots.join(", ")}.`,
        },
      ],
      artifacts: [
        ["Discriminant", formatNumber(discriminant)],
        ...(result.exactRadicals ? [["Numeric approximations", result.numericRoots.join(", ")]] : []),
      ],
    };
  }

  if (degree === 4) {
    const biquadratic = solveBiquadraticEquation(coefficients, variable);
    if (biquadratic) {
      return biquadratic;
    }
  }

  if (degree >= 3) {
    const rationalFactorSolution = solveRationalFactorEquation(coefficients, variable);
    if (rationalFactorSolution) {
      return rationalFactorSolution;
    }
  }

  const numericRoots = approximateRealPolynomialRoots(coefficients);
  return {
    answer: numericRoots.length
      ? numericRoots.map((root) => `${variable} ~= ${formatNumber(root)}`).join(", ")
      : "no real roots found",
    summary: numericRoots.length ? "numeric roots" : "no real roots found",
    steps: [
      {
        title: "Detect polynomial degree",
        expression: `degree ${degree}`,
        detail: "For degree three and higher, the browser solver switches to numerical approximation.",
      },
      {
        title: "Search for sign changes",
        expression: numericRoots.length
          ? numericRoots.map((root) => formatNumber(root)).join(", ")
          : "none found",
        detail: "The solver scans real-number intervals and refines roots with bisection.",
      },
    ],
  };
}

function solveRationalFactorEquation(coefficients, variable) {
  const degree = polynomialDegree(coefficients);
  const content = polynomialContent(coefficients);
  let working = trimPolynomialCoefficients(coefficients.map((coefficient) =>
    normalizeNumber((coefficient ?? 0) / content),
  ));
  const rationalRoots = [];

  while (polynomialDegree(working) > 0) {
    const root = findRationalRoot(working);
    if (!root) {
      break;
    }
    rationalRoots.push(root);
    working = syntheticDivide(working, root.value);
  }

  if (rationalRoots.length === 0) {
    return null;
  }

  const residualDegree = polynomialDegree(working);
  if (residualDegree > 2) {
    return null;
  }

  const residualRoots = residualDegree === 2
    ? quadraticRootEntries(working[2] ?? 0, working[1] ?? 0, working[0] ?? 0)
    : residualDegree === 1
      ? [linearRootEntry(working[1] ?? 0, working[0] ?? 0)]
      : [];
  const rationalEntries = rationalRoots.map((root) => ({
    value: root.value,
    text: formatRationalRootValue(root),
    approximate: false,
    exactRadical: false,
    complex: false,
  }));
  const realRoots = uniqueSortedRootEntries(
    [...rationalEntries, ...residualRoots.filter((root) => !root.complex)],
  );
  const complexRoots = uniqueTextRootEntries(residualRoots.filter((root) => root.complex));
  const roots = [...realRoots, ...complexRoots];
  if (roots.length === 0) {
    return null;
  }

  const hasApproximation = roots.some((root) => root.approximate && !root.complex);
  const hasExactRadical = roots.some((root) => root.exactRadical);
  const multiplicities = rationalRootMultiplicities(rationalRoots);
  const residualText = residualDegree > 0
    ? `${formatPolynomialFromCoefficients(working, variable)} = 0`
    : `${formatNumber(working[0] ?? 1)} after extracting all linear factors`;

  return {
    answer: roots.map((root) => `${variable} ${root.approximate ? "~=" : "="} ${root.text}`).join(", "),
    summary: "rational-root equation solution",
    steps: [
      {
        title: "Detect polynomial degree",
        expression: `degree ${degree}`,
        detail: "For degree three and higher, the solver first checks whether exact rational roots can reduce the equation.",
      },
      {
        title: "Apply rational root theorem",
        expression: rationalRoots.map((root) => formatRationalRootValue(root)).join(", "),
        detail: "Candidate rational roots divide the constant term over the leading coefficient.",
      },
      {
        title: "Use synthetic division",
        expression: residualText,
        detail: "Each exact rational root is divided out, leaving at most a quadratic residual factor.",
      },
      {
        title: residualDegree === 2 ? "Solve residual quadratic" : "Collect exact roots",
        expression: roots.map((root) => root.text).join(", "),
        detail: residualDegree === 2
          ? "The remaining quadratic is solved with the quadratic formula, preserving radical or complex output when needed."
          : "All roots came from exact rational factors.",
      },
    ],
    artifacts: [
      ["Method", "rational root theorem + synthetic division"],
      ["Rational roots", rationalEntries.length ? rationalEntries.map((root) => root.text).join(", ") : "none"],
      ["Multiplicities", multiplicities.length ? multiplicities.join(", ") : "none"],
      ["Residual factor", residualText],
      ...(hasApproximation || hasExactRadical
        ? [["Numeric approximations", roots
          .filter((root) => !root.complex && Number.isFinite(root.value))
          .map((root) => formatNumber(root.value))
          .join(", ")]]
        : []),
    ],
  };
}

function formatRationalRootValue(root) {
  if (root.denominator === 1) {
    return formatNumber(root.numerator);
  }
  return `${formatNumber(root.numerator)}/${formatNumber(root.denominator)}`;
}

function linearRootEntry(a, b) {
  const value = normalizeNumber(-b / a);
  return {
    value,
    text: formatNumber(value),
    approximate: false,
    exactRadical: false,
    complex: false,
  };
}

function quadraticRootEntries(a, b, c) {
  const discriminant = b * b - 4 * a * c;
  const result = quadraticRootResult(a, b, c, discriminant);
  if (discriminant < -EPSILON) {
    return result.roots.map((text) => ({
      value: Number.NaN,
      text,
      approximate: false,
      exactRadical: false,
      complex: true,
    }));
  }

  const denominator = 2 * a;
  const values = nearlyEqual(discriminant, 0)
    ? [normalizeNumber(-b / denominator)]
    : [
      normalizeNumber((-b + Math.sqrt(Math.max(0, discriminant))) / denominator),
      normalizeNumber((-b - Math.sqrt(Math.max(0, discriminant))) / denominator),
    ];
  return result.roots.map((text, index) => ({
    value: values[index],
    text,
    approximate: false,
    exactRadical: result.exactRadicals,
    complex: false,
  }));
}

function rationalRootMultiplicities(roots) {
  const counts = new Map();
  for (const root of roots) {
    const text = formatRationalRootValue(root);
    counts.set(text, (counts.get(text) ?? 0) + 1);
  }
  return [...counts.entries()].map(([root, count]) =>
    count === 1 ? root : `${root} (multiplicity ${count})`,
  );
}

function uniqueTextRootEntries(entries) {
  const seen = new Set();
  const unique = [];
  for (const entry of entries) {
    if (!seen.has(entry.text)) {
      seen.add(entry.text);
      unique.push(entry);
    }
  }
  return unique;
}

function solveBiquadraticEquation(coefficients, variable) {
  const oddTermsAreZero = nearlyEqual(coefficients[1] ?? 0, 0) &&
    nearlyEqual(coefficients[3] ?? 0, 0);
  if (!oddTermsAreZero || nearlyEqual(coefficients[4] ?? 0, 0)) {
    return null;
  }

  const c = coefficients[0] ?? 0;
  const b = coefficients[2] ?? 0;
  const a = coefficients[4] ?? 0;
  const discriminant = b * b - 4 * a * c;
  const uRoots = realQuadraticRootEntries(a, b, c, discriminant);
  const roots = uniqueSortedRootEntries(
    uRoots.flatMap((root) => xRootEntriesFromBiquadraticRoot(root)),
  );
  const hasApproximation = roots.some((root) => root.approximate);
  const answer = roots.length
    ? roots.map((root) => `${variable} ${root.approximate ? "~=" : "="} ${root.text}`).join(", ")
    : "no real roots found";

  return {
    answer,
    summary: "biquadratic quartic solution",
    steps: [
      {
        title: "Detect biquadratic form",
        expression: `${formatPolynomialFromCoefficients(coefficients, variable)} = 0`,
        detail: `Only even powers appear, so the quartic can be reduced with u = ${variable}^2.`,
      },
      {
        title: "Substitute u",
        expression: `${formatPolynomialFromCoefficients([c, b, a], "u")} = 0`,
        detail: `Let u = ${variable}^2 and solve the resulting quadratic equation.`,
      },
      {
        title: "Solve the quadratic in u",
        expression: `b^2 - 4ac = ${formatNumber(discriminant)}`,
        detail: uRoots.length
          ? `Real u roots: ${uRoots.map((root) => root.text).join(", ")}.`
          : "The quadratic in u has no real nonnegative roots.",
      },
      {
        title: "Take square roots",
        expression: roots.length
          ? roots.map((root) => `${variable} ${root.approximate ? "~=" : "="} ${root.text}`).join(", ")
          : "none",
        detail: roots.length
          ? `Each nonnegative u root gives ${variable} = +/-sqrt(u).`
          : "No real x-values satisfy the quartic.",
      },
    ],
    artifacts: [
      ["Substitution", `u = ${variable}^2`],
      ["Quadratic in u", `${formatPolynomialFromCoefficients([c, b, a], "u")} = 0`],
      ["u roots", uRoots.length ? uRoots.map((root) => root.text).join(", ") : "none"],
      ...(hasApproximation || roots.some((root) => root.exactRadical)
        ? [["Numeric approximations", roots.length ? roots.map((root) => formatNumber(root.value)).join(", ") : "none"]]
        : []),
    ],
  };
}

function realQuadraticRootEntries(a, b, c, discriminant) {
  if (discriminant < -EPSILON) {
    return [];
  }

  const denominator = 2 * a;
  if (nearlyEqual(discriminant, 0)) {
    const value = normalizeNumber(-b / denominator);
    return [{ value, text: formatNumber(value), exact: isIntegerLike(value) }];
  }

  const root = Math.sqrt(Math.max(0, discriminant));
  const values = [
    normalizeNumber((-b + root) / denominator),
    normalizeNumber((-b - root) / denominator),
  ];
  const exactRoots = exactQuadraticRadicalRoots(a, b, c, discriminant);
  return uniqueSortedRootEntries(values.map((value, index) => ({
    value,
    text: exactRoots ? exactRoots[index] : formatNumber(value),
    exact: Boolean(exactRoots) || isIntegerLike(value),
    approximate: !exactRoots && !isIntegerLike(value),
  })));
}

function xRootEntriesFromBiquadraticRoot(uRoot) {
  if (uRoot.value < -EPSILON) {
    return [];
  }
  if (nearlyEqual(uRoot.value, 0)) {
    return [{ value: 0, text: "0", exact: true }];
  }

  const magnitudeValue = normalizeNumber(Math.sqrt(Math.max(0, uRoot.value)));
  const magnitude = exactSquareRootMagnitude(uRoot);
  const makeEntry = (sign) => {
    const value = normalizeNumber(sign * magnitudeValue);
    return {
      value,
      text: sign < 0 ? `-${magnitude.text}` : magnitude.text,
      exact: magnitude.exact,
      exactRadical: magnitude.exactRadical,
      approximate: !magnitude.exact,
    };
  };
  return [makeEntry(-1), makeEntry(1)];
}

function exactSquareRootMagnitude(root) {
  if (isIntegerLike(root.value)) {
    const integer = Math.round(root.value);
    const { outside, radicand } = simplifySquareRootInteger(integer);
    if (radicand === 1) {
      return { text: formatNumber(outside), exact: true, exactRadical: false };
    }
    return {
      text: formatRadicalFactor(outside, radicand),
      exact: true,
      exactRadical: true,
    };
  }

  if (root.exact) {
    return {
      text: `sqrt(${wrapExpressionForFunction(root.text)})`,
      exact: true,
      exactRadical: true,
    };
  }

  return {
    text: formatNumber(Math.sqrt(Math.max(0, root.value))),
    exact: false,
    exactRadical: false,
  };
}

function wrapExpressionForFunction(text) {
  return /^[A-Za-z0-9_.]+$/.test(text) ? text : `(${text})`;
}

function factorPolynomialOverRationals(poly, variable) {
  const coefficients = trimPolynomialCoefficients(polynomialCoefficients(poly, variable));
  const degree = polynomialDegree(coefficients);
  if (degree === 0) {
    return {
      answer: formatNumber(coefficients[0] ?? 0),
      summary: "constant factor",
      roots: [],
      remaining: "constant",
      steps: [
        {
          title: "Check degree",
          expression: "degree 0",
          detail: "A constant polynomial has no variable factors.",
        },
      ],
    };
  }

  const content = polynomialContent(coefficients);
  let working = coefficients.map((coefficient) => normalizeNumber(coefficient / content));
  const roots = [];
  let denominatorProduct = 1;

  while (polynomialDegree(working) > 0) {
    const root = findRationalRoot(working);
    if (!root) {
      break;
    }
    roots.push(root);
    denominatorProduct *= root.denominator;
    working = syntheticDivide(working, root.value);
  }

  const residualCoefficients = denominatorProduct > 1
    ? working.map((coefficient) => normalizeNumber(coefficient / denominatorProduct))
    : working;
  const residualDegree = polynomialDegree(residualCoefficients);
  const rootFactors = roots.map((root) => formatLinearRootFactor(variable, root));
  const factors = [...rootFactors];
  let numericFactor = content;
  let remaining = "1";

  if (residualDegree === 0) {
    numericFactor = normalizeNumber(numericFactor * (residualCoefficients[0] ?? 1));
  } else {
    remaining = formatPolynomialFromCoefficients(residualCoefficients, variable);
    factors.push(formatParenthesizedFactor(remaining));
  }

  const answer = formatFactorProduct(numericFactor, factors);
  const summary = roots.length || !nearlyEqual(Math.abs(content), 1)
    ? "rational factorization"
    : "irreducible over rationals";

  return {
    answer,
    summary,
    roots,
    remaining,
    steps: [
      {
        title: "Detect polynomial degree",
        expression: `degree ${degree}`,
        detail: "Factoring starts from the one-variable polynomial degree.",
      },
      {
        title: "Extract numeric content",
        expression: `content = ${formatNumber(content)}`,
        detail: "A common numeric factor is separated before searching for roots.",
      },
      {
        title: "Search rational roots",
        expression: roots.length ? roots.map((root) => formatNumber(root.value)).join(", ") : "none found",
        detail: "The solver applies the rational root theorem and synthetic division.",
      },
      {
        title: roots.length ? "Build factor product" : "Check irreducibility",
        expression: answer,
        detail: roots.length
          ? "Each rational root r contributes a factor (x - r)."
          : "No rational roots were found, so the remaining polynomial is left as one factor.",
      },
    ],
  };
}

function trimPolynomialCoefficients(coefficients) {
  const trimmed = [...coefficients].map((coefficient) => normalizeNumber(coefficient ?? 0));
  while (trimmed.length > 1 && nearlyEqual(trimmed[trimmed.length - 1] ?? 0, 0)) {
    trimmed.pop();
  }
  return trimmed.length ? trimmed : [0];
}

function polynomialContent(coefficients) {
  const integerized = integerizeCoefficients(coefficients);
  if (!integerized) {
    return 1;
  }
  const nonzero = integerized.coefficients.filter((coefficient) => coefficient !== 0);
  if (nonzero.length === 0) {
    return 1;
  }
  const gcd = nonzero.map((coefficient) => Math.abs(coefficient)).reduce(gcdIntegers);
  const leading = integerized.coefficients[polynomialDegree(integerized.coefficients)];
  const sign = leading < 0 ? -1 : 1;
  return normalizeNumber((sign * gcd) / integerized.scale);
}

function integerizeCoefficients(coefficients) {
  for (let scale = 1; scale <= 1_000_000; scale *= 10) {
    const scaled = coefficients.map((coefficient) => Math.round((coefficient ?? 0) * scale));
    if (coefficients.every((coefficient, index) => nearlyEqual((coefficient ?? 0) * scale, scaled[index]))) {
      return { coefficients: scaled, scale };
    }
  }
  return null;
}

function findRationalRoot(coefficients) {
  const degree = polynomialDegree(coefficients);
  if (degree <= 0) {
    return null;
  }
  if (nearlyEqual(coefficients[0] ?? 0, 0)) {
    return { numerator: 0, denominator: 1, value: 0 };
  }

  const integerized = integerizeCoefficients(coefficients);
  if (!integerized) {
    return null;
  }

  const constant = Math.abs(integerized.coefficients[0] ?? 0);
  const leading = Math.abs(integerized.coefficients[degree] ?? 0);
  if (constant === 0 || leading === 0) {
    return null;
  }

  for (const candidate of rationalRootCandidates(constant, leading)) {
    if (nearlyEqual(evaluatePolynomialCoefficients(coefficients, candidate.value), 0)) {
      return candidate;
    }
  }
  return null;
}

function rationalRootCandidates(constant, leading) {
  const candidates = new Map();
  for (const numerator of integerDivisors(constant)) {
    for (const denominator of integerDivisors(leading)) {
      const divisor = gcdIntegers(numerator, denominator);
      const baseNumerator = numerator / divisor;
      const baseDenominator = denominator / divisor;
      for (const sign of [1, -1]) {
        const signedNumerator = sign * baseNumerator;
        const key = `${signedNumerator}/${baseDenominator}`;
        candidates.set(key, {
          numerator: signedNumerator,
          denominator: baseDenominator,
          value: signedNumerator / baseDenominator,
        });
      }
    }
  }
  return [...candidates.values()].sort((left, right) =>
    Math.abs(left.value) - Math.abs(right.value) || left.value - right.value,
  );
}

function integerDivisors(value) {
  const divisors = [];
  for (let candidate = 1; candidate <= Math.sqrt(value); candidate += 1) {
    if (value % candidate === 0) {
      divisors.push(candidate);
      if (candidate !== value / candidate) {
        divisors.push(value / candidate);
      }
    }
  }
  return divisors.sort((left, right) => left - right);
}

function gcdIntegers(left, right) {
  let a = Math.abs(left);
  let b = Math.abs(right);
  while (b !== 0) {
    [a, b] = [b, a % b];
  }
  return a;
}

function syntheticDivide(coefficients, root) {
  const degree = polynomialDegree(coefficients);
  const quotient = Array(degree).fill(0);
  quotient[degree - 1] = coefficients[degree];
  for (let index = degree - 2; index >= 0; index -= 1) {
    quotient[index] = coefficients[index + 1] + root * quotient[index + 1];
  }
  return trimPolynomialCoefficients(quotient.map(normalizeNumber));
}

function formatLinearRootFactor(variable, root) {
  if (root.numerator === 0) {
    return formatParenthesizedFactor(variable);
  }

  const coefficient = root.denominator === 1 ? variable : `${root.denominator}${variable}`;
  const constantText = formatNumber(Math.abs(root.numerator));
  const operator = root.numerator > 0 ? "-" : "+";
  return formatParenthesizedFactor(`${coefficient} ${operator} ${constantText}`);
}

function formatPolynomialFromCoefficients(coefficients, variable) {
  const poly = new Map();
  coefficients.forEach((coefficient, power) => {
    if (nearlyEqual(coefficient ?? 0, 0)) {
      return;
    }
    poly.set(power === 0 ? "" : monomialKey({ [variable]: power }), coefficient);
  });
  return formatPolynomial(cleanPolynomial(poly));
}

function formatParenthesizedFactor(text) {
  return `(${text})`;
}

function formatFactorProduct(coefficient, factors) {
  const normalized = normalizeNumber(coefficient);
  if (factors.length === 0) {
    return formatNumber(normalized);
  }
  if (nearlyEqual(normalized, 1)) {
    return factors.join("");
  }
  if (nearlyEqual(normalized, -1)) {
    return `-${factors.join("")}`;
  }
  return `${formatNumber(normalized)}${factors.join("")}`;
}

function solvePolynomialInequality(coefficients, operator, variable) {
  const degree = polynomialDegree(coefficients);
  if (degree === 0) {
    const constant = coefficients[0] ?? 0;
    const isTrue = compareWithOperator(constant, operator, 0);
    return {
      answer: isTrue ? "all real numbers" : "no solution",
      roots: [],
      table: {
        headers: ["Region", "Test value", "Polynomial", "Included"],
        rows: [["all real numbers", "any", formatNumber(constant), isTrue ? "yes" : "no"]],
      },
      steps: [
        {
          title: "Check constant inequality",
          expression: `${formatNumber(constant)} ${operator} 0`,
          detail: isTrue
            ? "The constant inequality is true for every real value."
            : "The constant inequality is false for every real value.",
        },
      ],
    };
  }

  const roots = realPolynomialRoots(coefficients);
  const includeEqual = operator.includes("=");
  const intervals = [];
  const signRows = [];
  const boundaries = [-Infinity, ...roots, Infinity];

  for (let index = 0; index < boundaries.length - 1; index += 1) {
    const lower = boundaries[index];
    const upper = boundaries[index + 1];
    const testValue = chooseIntervalTestValue(lower, upper);
    const value = evaluatePolynomialCoefficients(coefficients, testValue);
    const included = compareWithOperator(value, operator, 0);
    const part = {
      type: "interval",
      lower,
      upper,
      lowerClosed: includeEqual && Number.isFinite(lower),
      upperClosed: includeEqual && Number.isFinite(upper),
    };
    signRows.push([
      formatIntervalPart(part),
      formatNumber(testValue),
      formatNumber(value),
      included ? "yes" : "no",
    ]);
    if (included) {
      intervals.push(part);
    }
  }

  if (includeEqual) {
    for (const root of roots) {
      if (nearlyEqual(evaluatePolynomialCoefficients(coefficients, root), 0) && !intervals.some((part) => intervalContainsRoot(part, root))) {
        intervals.push({ type: "point", value: root });
      }
    }
  }

  const sortedSolution = sortSolutionParts(intervals);
  const answer = formatInequalitySolution(variable, sortedSolution);

  return {
    answer,
    roots,
    table: {
      headers: ["Region", "Test value", "Polynomial", "Included"],
      rows: signRows,
    },
    steps: [
      {
        title: "Find critical points",
        expression: roots.length ? roots.map(formatNumber).join(", ") : "none",
        detail: "The sign of a polynomial can change only at real roots.",
      },
      {
        title: "Build sign chart",
        expression: signRows.map((row) => `${row[0]}: ${row[3]}`).join("; "),
        detail: "The solver tests one value in each interval between critical points.",
      },
      {
        title: "Write interval solution",
        expression: answer,
        detail: includeEqual ? "Boundary roots are included because the inequality allows equality." : "Boundary roots are excluded for a strict inequality.",
      },
    ],
  };
}

function realPolynomialRoots(coefficients) {
  const degree = polynomialDegree(coefficients);
  if (degree <= 0) {
    return [];
  }
  if (degree === 1) {
    return uniqueSortedNumbers([-(coefficients[0] ?? 0) / (coefficients[1] ?? 0)]).map(normalizeNumber);
  }
  if (degree === 2) {
    const c = coefficients[0] ?? 0;
    const b = coefficients[1] ?? 0;
    const a = coefficients[2] ?? 0;
    const discriminant = b * b - 4 * a * c;
    if (discriminant < -EPSILON) {
      return [];
    }
    if (nearlyEqual(discriminant, 0)) {
      return uniqueSortedNumbers([-b / (2 * a)]).map(normalizeNumber);
    }
    const root = Math.sqrt(discriminant);
    return uniqueSortedNumbers([
      (-b - root) / (2 * a),
      (-b + root) / (2 * a),
    ]).map(normalizeNumber);
  }
  return approximateRealPolynomialRoots(coefficients);
}

function compareWithOperator(left, operator, right) {
  if (operator === "<") return left < right && !nearlyEqual(left, right);
  if (operator === "<=") return left < right || nearlyEqual(left, right);
  if (operator === ">") return left > right && !nearlyEqual(left, right);
  if (operator === ">=") return left > right || nearlyEqual(left, right);
  return false;
}

function chooseIntervalTestValue(lower, upper) {
  if (!Number.isFinite(lower) && !Number.isFinite(upper)) return 0;
  if (!Number.isFinite(lower)) return upper - 1;
  if (!Number.isFinite(upper)) return lower + 1;
  return (lower + upper) / 2;
}

function intervalContainsRoot(part, root) {
  if (part.type !== "interval") return false;
  if (part.lowerClosed && nearlyEqual(part.lower, root)) return true;
  if (part.upperClosed && nearlyEqual(part.upper, root)) return true;
  return part.lower < root && root < part.upper;
}

function sortSolutionParts(parts) {
  return [...parts].sort((left, right) => solutionPartStart(left) - solutionPartStart(right));
}

function solutionPartStart(part) {
  return part.type === "point" ? part.value : part.lower;
}

function formatInequalitySolution(variable, parts) {
  if (parts.length === 0) {
    return "no solution";
  }
  if (parts.length === 1) {
    const [part] = parts;
    if (part.type === "interval" && !Number.isFinite(part.lower) && !Number.isFinite(part.upper)) {
      return "all real numbers";
    }
  }
  return `${variable} in ${parts.map(formatIntervalPart).join(" U ")}`;
}

function formatIntervalPart(part) {
  if (part.type === "point") {
    return `{${formatNumber(part.value)}}`;
  }
  const leftBracket = part.lowerClosed ? "[" : "(";
  const rightBracket = part.upperClosed ? "]" : ")";
  const lower = Number.isFinite(part.lower) ? formatNumber(part.lower) : "-inf";
  const upper = Number.isFinite(part.upper) ? formatNumber(part.upper) : "inf";
  return `${leftBracket}${lower}, ${upper}${rightBracket}`;
}

function polynomialCoefficients(poly, variable) {
  const coefficients = [];
  for (const [key, coefficient] of poly.entries()) {
    const powers = powersFromKey(key);
    const degree = powers[variable] ?? 0;
    const otherVariables = Object.keys(powers).filter((name) => name !== variable);
    if (otherVariables.length > 0) {
      return [];
    }
    coefficients[degree] = (coefficients[degree] ?? 0) + coefficient;
  }
  return coefficients.map((value) => normalizeNumber(value ?? 0));
}

function polynomialDegree(coefficients) {
  for (let index = coefficients.length - 1; index >= 0; index -= 1) {
    if (!nearlyEqual(coefficients[index] ?? 0, 0)) {
      return index;
    }
  }
  return 0;
}

function approximateRealPolynomialRoots(coefficients) {
  const roots = [];
  const min = -50;
  const max = 50;
  const step = 0.25;
  let previousX = min;
  let previousY = evaluatePolynomialCoefficients(coefficients, previousX);

  for (let x = min + step; x <= max; x += step) {
    const y = evaluatePolynomialCoefficients(coefficients, x);
    if (nearlyEqual(y, 0)) {
      roots.push(x);
    } else if (previousY * y < 0) {
      roots.push(bisectPolynomialRoot(coefficients, previousX, x));
    }
    previousX = x;
    previousY = y;
  }

  return uniqueSortedNumbers(roots.map((root) => normalizeNumber(root)));
}

function evaluatePolynomialCoefficients(coefficients, x) {
  return coefficients.reduce((sum, coefficient, power) => sum + (coefficient ?? 0) * x ** power, 0);
}

function bisectPolynomialRoot(coefficients, lowStart, highStart) {
  let low = lowStart;
  let high = highStart;
  let lowValue = evaluatePolynomialCoefficients(coefficients, low);

  for (let index = 0; index < 80; index += 1) {
    const mid = (low + high) / 2;
    const midValue = evaluatePolynomialCoefficients(coefficients, mid);
    if (nearlyEqual(midValue, 0)) {
      return mid;
    }
    if (lowValue * midValue < 0) {
      high = mid;
    } else {
      low = mid;
      lowValue = midValue;
    }
  }

  return (low + high) / 2;
}

function uniqueSortedNumbers(values) {
  const sorted = values
    .filter((value) => Number.isFinite(value))
    .sort((left, right) => left - right);
  const unique = [];
  for (const value of sorted) {
    if (unique.every((existing) => Math.abs(existing - value) > 1e-5)) {
      unique.push(value);
    }
  }
  return unique;
}

function uniqueSortedRootEntries(entries) {
  const sorted = entries
    .filter((entry) => Number.isFinite(entry.value))
    .sort((left, right) => left.value - right.value);
  const unique = [];
  for (const entry of sorted) {
    if (unique.every((existing) => Math.abs(existing.value - entry.value) > 1e-5)) {
      unique.push(entry);
    }
  }
  return unique;
}

function quadraticRootResult(a, b, c, discriminant) {
  const numericRoots = quadraticRoots(a, b, c, discriminant);
  const exactRoots = exactQuadraticRadicalRoots(a, b, c, discriminant);
  if (!exactRoots) {
    return {
      roots: numericRoots,
      numericRoots,
      exactRadicals: false,
    };
  }
  return {
    roots: exactRoots,
    numericRoots,
    exactRadicals: true,
  };
}

function quadraticRoots(a, b, c, discriminant) {
  const denominator = 2 * a;
  if (nearlyEqual(discriminant, 0)) {
    return [formatNumber(-b / denominator)];
  }
  if (discriminant > 0) {
    const root = Math.sqrt(discriminant);
    return [
      formatNumber((-b + root) / denominator),
      formatNumber((-b - root) / denominator),
    ];
  }

  const real = -b / denominator;
  const imaginary = Math.sqrt(-discriminant) / Math.abs(denominator);
  return [
    formatComplex(complex(real, imaginary)),
    formatComplex(complex(real, -imaginary)),
  ];
}

function exactQuadraticRadicalRoots(a, b, c, discriminant) {
  if (![a, b, c, discriminant].every(isIntegerLike)) {
    return null;
  }
  const integerDiscriminant = Math.round(discriminant);
  if (integerDiscriminant <= 0) {
    return null;
  }

  const { outside, radicand } = simplifySquareRootInteger(integerDiscriminant);
  if (radicand === 1) {
    return null;
  }

  const constant = -Math.round(b);
  const denominator = 2 * Math.round(a);
  return [
    formatQuadraticRadicalRoot(constant, outside, radicand, denominator),
    formatQuadraticRadicalRoot(constant, -outside, radicand, denominator),
  ];
}

function isIntegerLike(value) {
  return Number.isFinite(value) &&
    Number.isSafeInteger(Math.round(value)) &&
    Math.abs(value - Math.round(value)) < 1e-9;
}

function simplifySquareRootInteger(value) {
  let radicand = Math.abs(Math.round(value));
  let outside = 1;
  for (let factor = 2; factor * factor <= radicand; factor += 1) {
    const square = factor * factor;
    while (radicand % square === 0) {
      outside *= factor;
      radicand /= square;
    }
  }
  return { outside, radicand };
}

function formatQuadraticRadicalRoot(constantInput, radicalInput, radicand, denominatorInput) {
  let constant = constantInput;
  let radical = radicalInput;
  let denominator = denominatorInput;

  if (denominator < 0) {
    constant *= -1;
    radical *= -1;
    denominator *= -1;
  }

  const common = gcdManyIntegers([constant, radical, denominator]);
  if (common > 1) {
    constant /= common;
    radical /= common;
    denominator /= common;
  }

  const numerator = formatRadicalNumerator(constant, radical, radicand);
  if (denominator === 1) {
    return numerator;
  }
  return numerator.includes(" + ") || numerator.includes(" - ")
    ? `(${numerator}) / ${denominator}`
    : `${numerator} / ${denominator}`;
}

function gcdManyIntegers(values) {
  const positives = values
    .map((value) => Math.abs(Math.round(value)))
    .filter((value) => value > 0);
  if (positives.length === 0) {
    return 1;
  }
  return positives.reduce((divisor, value) => gcdIntegers(divisor, value));
}

function formatRadicalNumerator(constant, radical, radicand) {
  const radicalText = formatRadicalFactor(Math.abs(radical), radicand);
  if (constant === 0) {
    return radical < 0 ? `-${radicalText}` : radicalText;
  }
  const sign = radical < 0 ? "-" : "+";
  return `${formatNumber(constant)} ${sign} ${radicalText}`;
}

function formatRadicalFactor(coefficient, radicand) {
  const radical = `sqrt(${formatNumber(radicand)})`;
  return coefficient === 1 ? radical : `${formatNumber(coefficient)}*${radical}`;
}

function unsupportedEquation(parsed, steps, detail) {
  steps.push({
    title: "Stop at supported scope",
    expression: formatMath(parsed),
    detail,
  });
  return {
    mode: "equation",
    tree: parsed,
    answer: "unsupported equation",
    summary: "unsupported",
    details: detail,
    variables: mathVariables(parsed),
    metrics: treeMetrics(parsed),
    steps,
    artifacts: [["Reason", detail]],
  };
}

function differentiate(node, variable, steps) {
  if (node.kind === "mathNumber") {
    return mathNumber(0);
  }

  if (node.kind === "mathSymbol") {
    const value = node.name === variable ? 1 : 0;
    steps.push({
      title: node.name === variable ? "Variable rule" : "Constant variable rule",
      expression: `d/d${variable} ${node.name} = ${value}`,
      detail: node.name === variable
        ? "The derivative of the active variable is one."
        : "Other variables are treated as constants.",
    });
    return mathNumber(value);
  }

  if (node.kind === "mathUnary") {
    return { kind: "mathUnary", operator: "-", operand: differentiate(node.operand, variable, steps) };
  }

  if (node.kind === "mathFunction") {
    const innerDerivative = differentiate(node.argument, variable, steps);
    const rule = functionDerivative(node, innerDerivative);
    steps.push({
      title: "Function rule",
      expression: `d/d${variable} ${formatMath(node)} = ${formatMath(rule)}`,
      detail: `Apply the derivative rule for ${node.name} and the chain rule.`,
    });
    return rule;
  }

  const leftDerivative = differentiate(node.left, variable, steps);
  const rightDerivative = differentiate(node.right, variable, steps);

  if (node.operator === "+") {
    steps.push({
      title: "Sum rule",
      expression: `d/d${variable} (${formatMath(node)})`,
      detail: "Differentiate each term and add the results.",
    });
    return mathBinary("+", leftDerivative, rightDerivative);
  }

  if (node.operator === "-") {
    steps.push({
      title: "Difference rule",
      expression: `d/d${variable} (${formatMath(node)})`,
      detail: "Differentiate each term and subtract the results.",
    });
    return mathBinary("-", leftDerivative, rightDerivative);
  }

  if (node.operator === "*") {
    steps.push({
      title: "Product rule",
      expression: `d/d${variable} (${formatMath(node)})`,
      detail: "Use f'g + fg' for multiplied expressions.",
    });
    return mathBinary(
      "+",
      mathBinary("*", leftDerivative, node.right),
      mathBinary("*", node.left, rightDerivative),
    );
  }

  if (node.operator === "/") {
    steps.push({
      title: "Quotient rule",
      expression: `d/d${variable} (${formatMath(node)})`,
      detail: "Use (f'g - fg') / g^2 for divided expressions.",
    });
    return mathBinary(
      "/",
      mathBinary(
        "-",
        mathBinary("*", leftDerivative, node.right),
        mathBinary("*", node.left, rightDerivative),
      ),
      mathBinary("^", node.right, mathNumber(2)),
    );
  }

  if (node.operator === "^") {
    if (node.right.kind === "mathNumber") {
      const exponent = node.right.value;
      steps.push({
        title: "Power rule",
        expression: `d/d${variable} (${formatMath(node)})`,
        detail: "Use n*f^(n-1)*f' for a constant exponent.",
      });
      return mathBinary(
        "*",
        mathBinary(
          "*",
          mathNumber(exponent),
          mathBinary("^", node.left, mathNumber(exponent - 1)),
        ),
        leftDerivative,
      );
    }

    steps.push({
      title: "General power rule",
      expression: `d/d${variable} (${formatMath(node)})`,
      detail: "Use f^g * (g'ln(f) + g*f'/f).",
    });
    return mathBinary(
      "*",
      node,
      mathBinary(
        "+",
        mathBinary("*", rightDerivative, { kind: "mathFunction", name: "ln", argument: node.left }),
        mathBinary("*", node.right, mathBinary("/", leftDerivative, node.left)),
      ),
    );
  }

  throw new Error(`Cannot differentiate operator '${node.operator}'.`);
}

function symbolicDerivative(parsed, variable) {
  const derivativeSteps = [];
  const derivative = differentiate(parsed, variable, derivativeSteps);
  const simplified = simplifyNode(derivative, derivativeSteps);
  const polynomial = polynomialFrom(simplified);
  const isZeroPolynomial = polynomial && polynomial.size === 1 && nearlyEqual(polynomial.get("") ?? Number.NaN, 0);
  const finalTree = polynomial ? (isZeroPolynomial ? mathNumber(0) : polynomialToNode(polynomial)) : simplified;
  return {
    node: finalTree,
    answer: polynomial ? formatPolynomial(polynomial) : formatMath(finalTree),
  };
}

function evaluateAtPointIfAvailable(node, point) {
  const variables = mathVariables(node);
  if (variables.length === 0) {
    return safeEvaluateMath(node, {});
  }
  if (variables.some((variable) => !Number.isFinite(point[variable]))) {
    return Number.NaN;
  }
  return safeEvaluateMath(node, point);
}

function formatPointAssignments(point) {
  return Object.entries(point)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([name, value]) => `${name}=${formatNumber(value)}`)
    .join(", ");
}

function functionDerivative(node, innerDerivative) {
  const arg = node.argument;
  if (node.name === "sin") {
    return mathBinary("*", { kind: "mathFunction", name: "cos", argument: arg }, innerDerivative);
  }
  if (node.name === "cos") {
    return mathBinary(
      "*",
      { kind: "mathUnary", operator: "-", operand: { kind: "mathFunction", name: "sin", argument: arg } },
      innerDerivative,
    );
  }
  if (node.name === "tan") {
    return mathBinary(
      "*",
      mathBinary("^", { kind: "mathFunction", name: "cos", argument: arg }, mathNumber(-2)),
      innerDerivative,
    );
  }
  if (node.name === "sec") {
    return mathBinary(
      "*",
      mathBinary("*", trigNode("sec", arg), trigNode("tan", arg)),
      innerDerivative,
    );
  }
  if (node.name === "csc") {
    return mathBinary(
      "*",
      { kind: "mathUnary", operator: "-", operand: mathBinary("*", trigNode("csc", arg), trigNode("cot", arg)) },
      innerDerivative,
    );
  }
  if (node.name === "cot") {
    return mathBinary(
      "*",
      { kind: "mathUnary", operator: "-", operand: mathBinary("^", trigNode("csc", arg), mathNumber(2)) },
      innerDerivative,
    );
  }
  if (node.name === "exp") {
    return mathBinary("*", { kind: "mathFunction", name: "exp", argument: arg }, innerDerivative);
  }
  if (node.name === "ln") {
    return mathBinary("/", innerDerivative, arg);
  }
  if (node.name === "sqrt") {
    return mathBinary(
      "/",
      innerDerivative,
      mathBinary("*", mathNumber(2), { kind: "mathFunction", name: "sqrt", argument: arg }),
    );
  }
  if (node.name === "atan") {
    return mathBinary(
      "/",
      innerDerivative,
      mathBinary("+", mathNumber(1), mathBinary("^", arg, mathNumber(2))),
    );
  }
  throw new Error(`Unsupported function '${node.name}'.`);
}

export function mathVariables(node, names = new Set()) {
  if (node.kind === "mathSymbol") {
    names.add(node.name);
  }
  for (const child of nodeChildren(node)) {
    mathVariables(child, names);
  }
  return [...names].sort();
}

export function treeMetrics(node) {
  const children = nodeChildren(node);
  if (children.length === 0) {
    return {
      nodes: 1,
      height: 1,
      operators: 0,
    };
  }

  const childMetrics = children.map(treeMetrics);
  return {
    nodes: 1 + childMetrics.reduce((sum, metric) => sum + metric.nodes, 0),
    height: 1 + Math.max(...childMetrics.map((metric) => metric.height)),
    operators: Number(isOperatorNode(node)) + childMetrics.reduce((sum, metric) => sum + metric.operators, 0),
  };
}

function isOperatorNode(node) {
  return [
    "logicNot",
    "logicBinary",
    "mathUnary",
    "mathBinary",
    "mathFunction",
    "equation",
    "mathFourierSeries",
    "mathLaplaceTransform",
    "matrixOperation",
  ].includes(node.kind);
}

export function nodeChildren(node) {
  if (Array.isArray(node.children)) return node.children;
  if (node.kind === "logicNot") return [node.operand];
  if (node.kind === "logicBinary") return [node.left, node.right];
  if (node.kind === "mathUnary") return [node.operand];
  if (node.kind === "mathBinary") return [node.left, node.right];
  if (node.kind === "mathFunction") return [node.argument];
  if (node.kind === "equation") return [node.left, node.right];
  return [];
}

export function nodeLabel(node) {
  if (node.kind === "logicConstant") return node.value ? "TRUE" : "FALSE";
  if (node.kind === "logicVariable") return node.name;
  if (node.kind === "logicNot") return "NOT";
  if (node.kind === "logicBinary") return LOGIC_LABELS[node.operator] ?? node.operator.toUpperCase();
  if (node.kind === "mathNumber") return formatNumber(node.value);
  if (node.kind === "mathSymbol") return node.name;
  if (node.kind === "mathUnary") return "NEG";
  if (node.kind === "mathBinary") return node.operator;
  if (node.kind === "mathFunction") return node.name.toUpperCase();
  if (node.kind === "equation") return "=";
  if (node.kind === "mathInequality") return node.operator;
  if (node.kind === "statsDataset") return node.label ?? "DATA";
  if (node.kind === "statsMetric") return `${node.label}`;
  if (node.kind === "statsRegression") return "REG";
  if (node.kind === "statsDistribution") return node.label ?? "DIST";
  if (node.kind === "system") return "SYSTEM";
  if (node.kind === "matrixOperation") return node.label ?? "MATRIX";
  if (node.kind === "matrix") return node.label ?? "M";
  if (node.kind === "matrixRow") return node.label ?? "ROW";
  return "?";
}

export function nodeTone(node) {
  if (node.kind.startsWith("logic")) return "logic";
  if (node.kind.startsWith("stats")) return "statistics";
  if (node.kind.startsWith("matrix")) return "matrix";
  if (node.kind === "system") return "equation";
  if (node.kind === "mathNumber") return "number";
  if (node.kind === "mathSymbol") return "symbol";
  if (node.kind === "mathFunction") return "function";
  if (node.kind === "equation") return "equation";
  if (node.kind === "mathInequality") return "equation";
  return "operator";
}

function formatAssignment(assignment) {
  const entries = Object.entries(assignment).sort(([left], [right]) => left.localeCompare(right));
  if (entries.length === 0) {
    return "no variables";
  }
  return entries.map(([name, value]) => `${name}=${formatTruth(value)}`).join(", ");
}

export function formatTruth(value) {
  return value ? "true" : "false";
}

function formatNumber(value) {
  const normalized = normalizeNumber(value);
  if (Object.is(normalized, -0)) {
    return "0";
  }
  if (Number.isInteger(normalized)) {
    return String(normalized);
  }
  return String(Number(normalized.toFixed(6))).replace(/\.0+$/, "");
}

function formatPercent(value) {
  return Number.isFinite(value) ? `${formatNumber(value * 100)}%` : "undefined";
}

function formatFiniteNumber(value) {
  return Number.isFinite(value) ? formatNumber(value) : "undefined";
}

function formatStatisticValue(value) {
  if (value === Infinity) return "infinity";
  if (value === -Infinity) return "-infinity";
  return formatNumber(value);
}

function normalizeNumber(value) {
  return nearlyEqual(value, 0) ? 0 : Number(value.toFixed(10));
}

function nearlyEqual(left, right) {
  return Math.abs(left - right) < EPSILON;
}
